window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2021-1"]={"track":"written","round":"2021-1","questions":[{"id":"written-2021-1-1","no":1,"unit":"소프트웨어 설계","q":"운영체제 분석을 위해 리눅스에서 버전을 확인하고자 할 때 사용되는 명령어는?(문제 오류로 가답안 발표시 4번으로 발표되었지만 확정답안 발표시 2, 4번이 정답처리 되었습니다. 여기서는 가답안인 4번을 누르시면 정답 처리 됩니다.)","choices":["ls","cat","pwd","uname"],"ans":4,"rate":60,"wiki":[{"title":"리눅스 ls","url":"https://itwiki.kr/w/리눅스 ls"},{"title":"리눅스 uname","url":"https://itwiki.kr/w/리눅스 uname"},{"title":"리눅스 pwd","url":"https://itwiki.kr/w/리눅스 pwd"}],"exp":{"concept":"리눅스에서 운영체제 정보를 보는 대표 명령어는 uname이다. uname -a는 커널 이름, 커널 버전, 호스트 이름, 하드웨어 종류 등을 한 줄로 보여 주고, uname -r은 커널 버전만 보여 준다. 배포판(우분투, CentOS 등)의 버전은 /etc/os-release 같은 파일에 적혀 있어서 cat으로 열어 볼 수도 있다.","choices":[{"verdict":"오답","why":"ls는 디렉터리 안의 파일과 하위 디렉터리 목록을 보여 주는 명령어다. 운영체제 버전과는 관계없다."},{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하는 명령어다. cat /etc/os-release처럼 버전 정보 파일을 열면 배포판 버전을 볼 수 있어 보기 내용상 맞는 설명으로 볼 수도 있지만(문제 안내문대로 확정 답안에서도 정답으로 인정), 버전 확인 전용 명령어는 아니다."},{"verdict":"오답","why":"pwd(Print Working Directory)는 현재 작업 중인 디렉터리의 경로를 보여 주는 명령어다."},{"verdict":"정답","why":"uname은 시스템과 커널 정보를 출력하는 명령어다. uname -a로 전체 정보를, uname -r로 커널 버전을 확인한다."}],"keywords":[{"term":"uname","desc":"커널 이름·버전 등 시스템 정보 출력 (-a 전체, -r 커널 버전)"},{"term":"cat","desc":"파일 내용을 화면에 출력"},{"term":"ls","desc":"디렉터리의 파일 목록 출력"},{"term":"pwd","desc":"현재 작업 디렉터리 경로 출력"}],"memo":"uname은 'Unix name', 즉 내 시스템의 이름표를 보여 주는 명령어로 기억한다.","doubt":"문제 안내문에 따르면 확정 답안에서 2번(cat)과 4번(uname)이 모두 정답 처리되었다. 보기 내용상 cat /etc/os-release처럼 버전 정보 파일을 열어 배포판 버전을 확인할 수 있으므로 2번도 맞는 설명으로 볼 수 있다. 이 문제에서는 가답안인 4번을 정답으로 처리한다."}},{"id":"written-2021-1-2","no":2,"unit":"소프트웨어 설계","q":"통신을 위한 프로그램을 생성하여 포트를 할당하고, 클라이언트의 통신 요청 시 클라이언트와 연결하는 내·외부 송·수신 연계기술은?","choices":["DB링크 기술","소켓 기술","스크럼 기술","프로토타입 기술"],"ans":2,"rate":76,"exp":{"concept":"소켓(Socket)은 프로그램끼리 네트워크로 통신하기 위한 출입구다. 서버 프로그램이 소켓을 만들어 포트 번호를 할당하고 기다리다가, 클라이언트가 연결을 요청하면 둘을 연결해 데이터를 주고받는다. 전화기를 설치하고(소켓 생성) 번호를 정해 두었다가(포트 할당) 전화가 오면 받는(연결) 것과 비슷하다.","choices":[{"verdict":"오답","why":"DB링크는 데이터베이스가 제공하는 링크 객체를 이용해 다른 시스템의 데이터베이스에 직접 접근하는 연계 기술이다. 포트를 할당해 클라이언트와 연결하는 방식이 아니다."},{"verdict":"정답","why":"소켓 기술은 통신 프로그램이 소켓을 생성해 포트를 할당하고, 클라이언트의 요청이 오면 연결해 데이터를 송수신하는 연계 기술이다."},{"verdict":"오답","why":"스크럼(Scrum)은 짧은 스프린트 단위로 개발을 반복하는 애자일 개발 방법론이다. 시스템 연계 기술이 아니다."},{"verdict":"오답","why":"프로토타입은 시제품을 먼저 만들어 사용자 확인을 받는 개발 모형이다. 연계 기술이 아니다."}],"keywords":[{"term":"소켓(Socket)","desc":"포트를 할당하고 클라이언트 요청 시 연결해 통신하는 기술"},{"term":"DB링크","desc":"DB가 제공하는 링크 객체로 상대 DB에 직접 접근하는 연계 기술"},{"term":"API/OpenAPI","desc":"송신 시스템의 데이터를 제공하는 인터페이스 프로그램을 통한 연계 기술"}],"memo":"지문에 '포트 할당'과 '클라이언트 연결'이 함께 나오면 소켓이다."}},{"id":"written-2021-1-3","no":3,"unit":"소프트웨어 설계","q":"객체지향 개념에서 연관된 데이터와 함수를 함께 묶어 외부와 경계를 만들고 필요한 인터페이스만을 밖으로 드러내는 과정은?","choices":["메시지(Message)","캡슐화(Encapsulation)","다형성(Polymorphism)","상속(Inheritance)"],"ans":2,"rate":87,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"캡슐화(Encapsulation)는 서로 관련 있는 데이터(속성)와 그 데이터를 다루는 함수(메서드)를 하나의 객체로 묶고, 내부는 숨긴 채 꼭 필요한 기능만 밖에 보여 주는 것이다. 알약 캡슐 안의 가루는 보이지 않고 겉모습만 보이는 것과 같다. 내부를 바꿔도 밖에 보이는 인터페이스가 같으면 다른 부분에 영향이 적다.","choices":[{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 동작을 하라고 보내는 요청이다. 데이터와 함수를 묶는 과정이 아니다."},{"verdict":"정답","why":"데이터와 함수를 하나로 묶고 내부를 감추어 필요한 인터페이스만 드러내는 것이 캡슐화다. 정보 은닉(Information Hiding)과 함께 쓰인다."},{"verdict":"오답","why":"다형성(Polymorphism)은 같은 이름의 메시지에 객체마다 다르게 반응하는 성질이다(오버로딩, 오버라이딩)."},{"verdict":"오답","why":"상속(Inheritance)은 상위 클래스의 속성과 메서드를 하위 클래스가 물려받아 쓰는 것이다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"데이터와 함수를 묶고 내부를 숨겨 인터페이스만 공개"},{"term":"정보 은닉(Information Hiding)","desc":"다른 객체가 내부 구현을 직접 볼 수 없게 감춤"},{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체마다 다른 방식으로 응답"},{"term":"상속(Inheritance)","desc":"상위 클래스의 속성·메서드를 하위 클래스가 물려받음"}],"memo":"'묶고 경계를 만들어 감춘다' = 캡슐(약 캡슐에 가루를 넣어 감춘다)."}},{"id":"written-2021-1-4","no":4,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴의 생성패턴에 속하지 않는 것은?","choices":["추상 팩토리(Abstract Factory)","빌더(Builder)","어댑터(Adapter)","싱글턴(Singleton)"],"ans":3,"rate":59,"exp":{"concept":"GoF 디자인 패턴 23가지는 생성, 구조, 행위 세 가지로 나뉜다. 생성 패턴은 객체를 만드는 방법을 다루는 패턴으로 추상 팩토리, 빌더, 팩토리 메서드, 프로토타입, 싱글턴 다섯 가지다. 어댑터는 서로 맞지 않는 인터페이스를 연결해 주는 구조 패턴이다.","choices":[{"verdict":"오답","why":"추상 팩토리(Abstract Factory)는 서로 관련된 객체들을 구체 클래스에 의존하지 않고 한꺼번에 생성하게 해 주는 생성 패턴이다."},{"verdict":"오답","why":"빌더(Builder)는 복잡한 객체를 단계별로 조립해 생성하는 생성 패턴이다."},{"verdict":"정답","why":"어댑터(Adapter)는 호환되지 않는 인터페이스를 가진 클래스를 함께 쓸 수 있게 변환해 주는 구조 패턴이다. 생성 패턴이 아니다."},{"verdict":"오답","why":"싱글턴(Singleton)은 클래스의 인스턴스를 하나만 만들도록 보장하는 생성 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"추상 팩토리, 빌더, 팩토리 메서드, 프로토타입, 싱글턴"},{"term":"구조 패턴","desc":"어댑터, 브리지, 컴포지트, 데코레이터, 퍼사드, 플라이웨이트, 프록시"},{"term":"행위 패턴","desc":"옵서버, 전략, 커맨드, 반복자, 상태, 템플릿 메서드 등 객체 간 책임·상호작용"}],"memo":"생성 패턴 5개만 외우면 나머지는 구조·행위로 걸러진다: 추상팩토리·빌더·팩토리메서드·프로토타입·싱글턴."}},{"id":"written-2021-1-5","no":5,"unit":"소프트웨어 설계","q":"응용프로그램의 프로시저를 사용하여 원격 프로시저를 로컬 프로시저처럼 호출하는 방식의 미들웨어는?","choices":["WAS(Web Application Server)","MOM(Message Oriented Middleware)","RPC(Remote Procedure Call)","ORB(Object Request Broker)"],"ans":3,"rate":74,"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"exp":{"concept":"미들웨어는 서로 다른 시스템 사이에서 통신을 도와주는 중간 소프트웨어다. 그중 RPC(Remote Procedure Call)는 다른 컴퓨터에 있는 함수(프로시저)를 내 프로그램 안의 함수처럼 호출하게 해 준다. 네트워크 통신 과정은 감춰지므로 개발자는 일반 함수를 부르듯 코드를 쓰면 된다.","choices":[{"verdict":"오답","why":"WAS(Web Application Server)는 웹 환경에서 동적인 콘텐츠를 처리하기 위한 미들웨어다(예: Tomcat, JEUS)."},{"verdict":"오답","why":"MOM(Message Oriented Middleware)은 메시지를 주고받는 방식으로 시스템을 연결하는 미들웨어로, 주로 비동기 방식이다."},{"verdict":"정답","why":"RPC는 원격 프로시저를 로컬 프로시저처럼 호출할 수 있게 해 주는 미들웨어다."},{"verdict":"오답","why":"ORB(Object Request Broker)는 객체 지향 시스템에서 원격 객체 간의 요청을 중개하는 미들웨어로, CORBA 표준이 대표적이다."}],"keywords":[{"term":"RPC(Remote Procedure Call)","desc":"원격 프로시저를 로컬처럼 호출"},{"term":"MOM(Message Oriented Middleware)","desc":"메시지 기반, 주로 비동기 통신"},{"term":"ORB(Object Request Broker)","desc":"원격 객체 간 요청 중개, CORBA"},{"term":"WAS(Web Application Server)","desc":"웹의 동적 콘텐츠 처리"}],"memo":"'프로시저'를 원격으로 부른다 = Remote Procedure Call, 이름 그대로다."}},{"id":"written-2021-1-6","no":6,"unit":"소프트웨어 설계","q":"바람직한 소프트웨어 설계 지침이 아닌 것은?","choices":["모듈의 기능을 예측할 수 있도록 정의한다.","이식성을 고려한다.","적당한 모듈의 크기를 유지한다.","가능한 모듈을 독립적으로 생성하고 결합도를 최대화한다."],"ans":4,"rate":89,"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"},{"title":"응집도","url":"https://itwiki.kr/w/응집도"},{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"exp":{"concept":"좋은 소프트웨어 설계는 모듈 하나하나가 독립적이어야 한다. 그러려면 모듈끼리 얽힌 정도인 결합도는 낮추고, 모듈 안의 요소들이 한 가지 목적으로 뭉친 정도인 응집도는 높여야 한다. 모듈의 기능은 예측 가능하게, 크기는 적당하게 유지하고, 이식성도 고려한다.","choices":[{"verdict":"오답","why":"모듈의 기능을 예측할 수 있도록 정의하는 것은 바람직한 설계 지침이다."},{"verdict":"오답","why":"다른 환경에서도 쉽게 옮겨 쓸 수 있도록 이식성을 고려하는 것은 바람직한 설계 지침이다."},{"verdict":"오답","why":"모듈이 너무 크거나 작지 않게 적당한 크기를 유지하는 것은 바람직한 설계 지침이다."},{"verdict":"정답","why":"모듈을 독립적으로 만들려면 결합도는 최소화해야 한다. 결합도를 최대화한다는 설명은 틀렸다."}],"keywords":[{"term":"결합도(Coupling)","desc":"모듈 사이의 상호 의존 정도, 낮을수록 좋음"},{"term":"응집도(Cohesion)","desc":"모듈 내부 요소가 하나의 기능으로 뭉친 정도, 높을수록 좋음"},{"term":"모듈 독립성","desc":"결합도는 낮추고 응집도는 높여 확보"}],"memo":"결합도는 낮게, 응집도는 높게. '최대화' 앞에 결합도가 오면 틀린 문장이다."}},{"id":"written-2021-1-7","no":7,"unit":"소프트웨어 설계","q":"객체지향 분석 방법론 중 Coad-Yourdon 방법에 해당하는 것은?","choices":["E-R 다이어그램을 사용하여 객체의 행위를 데이터 모델링하는데 초점을 둔 방법이다.","객체, 동적, 기능 모델로 나누어 수행하는 방법이다.","미시적 개발 프로세스와 거시적 개발 프로세스를 모두 사용하는 방법이다.","Use-Case를 강조하여 사용하는 방법이다."],"ans":1,"rate":62,"exp":{"concept":"객체지향 분석 방법론은 만든 사람마다 강조점이 다르다. Coad-Yourdon 방법은 E-R 다이어그램을 사용해 객체의 행위를 데이터 모델링하는 데 초점을 둔다. Rumbaugh는 객체·동적·기능 모델, Booch는 미시적·거시적 개발 프로세스, Jacobson은 유스케이스를 강조한다.","choices":[{"verdict":"정답","why":"E-R 다이어그램으로 객체의 행위를 데이터 모델링하는 데 초점을 둔 방법이 Coad-Yourdon 방법이다."},{"verdict":"오답","why":"객체 모델링, 동적 모델링, 기능 모델링으로 나누어 수행하는 것은 Rumbaugh(럼바우) 방법(OMT)이다."},{"verdict":"오답","why":"미시적 개발 프로세스와 거시적 개발 프로세스를 모두 사용하는 것은 Booch(부치) 방법이다."},{"verdict":"오답","why":"Use-Case를 강조하는 것은 Jacobson(제이콥슨) 방법이다."}],"keywords":[{"term":"Coad-Yourdon","desc":"E-R 다이어그램으로 객체 행위를 데이터 모델링"},{"term":"Rumbaugh(OMT)","desc":"객체 → 동적 → 기능 모델링"},{"term":"Booch","desc":"미시적·거시적 개발 프로세스 모두 사용"},{"term":"Jacobson","desc":"유스케이스(Use Case) 강조"},{"term":"Wirfs-Brock","desc":"분석과 설계 구분 없이 고객 명세서를 평가해 설계까지 진행"}],"memo":"럼바우=객동기, 부치=미시·거시, 제이콥슨=유스케이스, 코드-요든=E-R 다이어그램."}},{"id":"written-2021-1-8","no":8,"unit":"소프트웨어 설계","q":"다음은 어떤 프로그램 구조를 나타낸다. 모듈 F에서의 fan-in과 fan-out의 수는 얼마인가?\n<img src=\"data/img/eip_written_20210307_008.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["fan-in : 2, fan-out : 3","fan-in : 3, fan-out : 2","fan-in : 1, fan-out : 2","fan-in : 2, fan-out : 1"],"ans":2,"rate":85,"exp":{"concept":"모듈 구조도에서 위 모듈이 아래 모듈을 호출한다. 팬인(fan-in)은 어떤 모듈을 호출하는 상위 모듈의 수, 즉 위에서 들어오는 선의 수다. 팬아웃(fan-out)은 그 모듈이 호출하는 하위 모듈의 수, 즉 아래로 나가는 선의 수다. 그림에서 F에는 B, C, D 세 모듈의 선이 들어오고, F에서 G, H 두 모듈로 선이 나간다.","choices":[{"verdict":"오답","why":"F로 들어오는 선은 B, C, D 세 개이고 나가는 선은 G, H 두 개다. 팬인과 팬아웃을 바꾸어 센 값이다."},{"verdict":"정답","why":"F를 호출하는 상위 모듈은 B, C, D로 팬인 3, F가 호출하는 하위 모듈은 G, H로 팬아웃 2다."},{"verdict":"오답","why":"팬인은 1이 아니라 B, C, D 세 개다. D에서 F로 길게 내려오는 선과 C에서 내려오는 선까지 세야 한다."},{"verdict":"오답","why":"팬인 2는 D에서 F로 오는 선을 빠뜨린 값이고, 팬아웃도 G, H 두 개이므로 1이 아니다."}],"keywords":[{"term":"팬인(Fan-In)","desc":"나를 호출하는 상위 모듈 수, 높으면 재사용이 많다는 뜻"},{"term":"팬아웃(Fan-Out)","desc":"내가 호출하는 하위 모듈 수, 너무 높으면 단순화 검토"},{"term":"구조도(Structure Chart)","desc":"모듈 간 호출 관계를 위에서 아래로 나타낸 그림"}],"memo":"In은 위에서 들어오는 선, Out은 아래로 나가는 선. 대각선으로 길게 들어오는 선을 빠뜨리지 않게 F에 닿는 선을 하나씩 짚어 센다."}},{"id":"written-2021-1-9","no":9,"unit":"소프트웨어 설계","q":"현행 시스템 분석에서 고려하지 않아도 되는 항목은?","choices":["DBMS 분석","네트워크 분석","운영체제 분석","인적 자원 분석"],"ans":4,"rate":81,"exp":{"concept":"현행 시스템 분석은 새 시스템을 만들기 전에 지금 쓰고 있는 시스템의 기술 환경을 파악하는 일이다. 주로 시스템 구성·기능·인터페이스, 아키텍처와 소프트웨어 구성, 하드웨어와 네트워크 구성, 운영체제·DBMS·미들웨어 같은 플랫폼을 분석한다. 사람에 관한 인적 자원은 이 기술 분석의 대상이 아니다.","choices":[{"verdict":"오답","why":"DBMS 분석은 현재 쓰는 DBMS의 종류, 버전, 구성 방식 등을 파악하는 현행 시스템 분석 항목이다."},{"verdict":"오답","why":"네트워크 분석은 현재 네트워크 구성과 장비 등을 파악하는 현행 시스템 분석 항목이다."},{"verdict":"오답","why":"운영체제 분석은 현재 쓰는 운영체제 종류와 버전, 라이선스 등을 파악하는 현행 시스템 분석 항목이다."},{"verdict":"정답","why":"인적 자원 분석은 시스템의 기술 환경을 파악하는 현행 시스템 분석 항목에 포함되지 않는다."}],"keywords":[{"term":"현행 시스템 파악","desc":"구성·기능·인터페이스 → 아키텍처·SW 구성 → HW·네트워크 구성 순으로 파악"},{"term":"플랫폼 분석","desc":"운영체제, DBMS, 미들웨어 등 기반 소프트웨어 분석"},{"term":"네트워크 분석","desc":"현재 네트워크 구성도와 장비 파악"}],"memo":"현행 시스템 분석은 기계(HW·SW·네트워크)를 보는 일이다. 사람(인적 자원)이 나오면 정답 후보다."}},{"id":"written-2021-1-10","no":10,"unit":"소프트웨어 설계","q":"분산 컴퓨팅 환경에서 서로 다른 기종 간의 하드웨어나 프로토콜, 통신환경 등을 연결하여 응용프로그램과 운영환경 간에 원만한 통신이 이루어질 수 있게 서비스를 제공하는 소프트웨어는?","choices":["미들웨어","하드웨어","오픈허브웨어","그레이웨어"],"ans":1,"rate":92,"wiki":[{"title":"미들웨어","url":"https://itwiki.kr/w/미들웨어"}],"exp":{"concept":"미들웨어(Middleware)는 이름처럼 가운데(Middle)에 있는 소프트웨어다. 서로 다른 기종의 하드웨어, 프로토콜, 통신 환경 사이에 끼어 응용 프로그램과 운영 환경이 원활하게 통신하도록 서비스를 제공한다. 서로 다른 언어를 쓰는 두 사람 사이의 통역사와 비슷하다.","choices":[{"verdict":"정답","why":"분산 환경에서 서로 다른 기종과 프로토콜을 연결해 응용 프로그램과 운영 환경 사이의 통신을 돕는 소프트웨어가 미들웨어다."},{"verdict":"오답","why":"하드웨어는 컴퓨터를 이루는 물리적 장치 자체를 말하며, 통신을 중개하는 소프트웨어가 아니다."},{"verdict":"오답","why":"오픈허브웨어는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"그레이웨어(Grayware)는 악성 코드인지 정상 프로그램인지 판단하기 애매한 프로그램(애드웨어, 일부 스파이웨어 등)을 말한다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"이기종 시스템 사이에서 통신을 중개하는 소프트웨어"},{"term":"미들웨어 종류","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS 등"},{"term":"그레이웨어(Grayware)","desc":"유해성 판단이 애매한 프로그램"}],"memo":"서로 다른 것 '사이'를 이어 준다는 말이 나오면 미들(Middle)웨어."}},{"id":"written-2021-1-11","no":11,"unit":"소프트웨어 설계","q":"CASE(Computer Aided Software Engineering)에 대한 설명으로 틀린 것은?","choices":["소프트웨어 모듈의 재사용성이 향상된다.","자동화된 기법을 통해 소프트웨어 품질이 향상된다.","소프트웨어 사용자들에게 사용 방법을 신속히 숙지시키기 위해 사용된다.","소프트웨어 유지보수를 간편하게 수행할 수 있다."],"ans":3,"rate":79,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발 과정(분석, 설계, 구현, 테스트, 유지보수)의 작업을 컴퓨터 도구로 자동화해 돕는 기술이다. 덕분에 품질과 생산성이 오르고, 모듈 재사용과 유지보수가 쉬워진다. 개발자를 위한 도구이지, 완성된 소프트웨어의 사용법을 사용자에게 가르치는 도구가 아니다.","choices":[{"verdict":"오답","why":"CASE 도구로 만든 설계와 모듈을 표준화해 관리하므로 소프트웨어 모듈의 재사용성이 향상된다. 맞는 설명이다."},{"verdict":"오답","why":"자동화된 기법으로 오류를 줄이고 표준을 지키게 하므로 소프트웨어 품질이 향상된다. 맞는 설명이다."},{"verdict":"정답","why":"CASE는 개발 작업을 자동화하는 개발자용 도구다. 사용자에게 사용 방법을 익히게 하기 위한 도구라는 설명은 틀렸다."},{"verdict":"오답","why":"설계 문서와 코드가 일관되게 관리되므로 유지보수를 간편하게 할 수 있다. 맞는 설명이다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 과정을 컴퓨터 도구로 자동화해 지원"},{"term":"상위 CASE","desc":"요구 분석·설계 단계 지원"},{"term":"하위 CASE","desc":"코드 작성·테스트·문서화 단계 지원"}],"memo":"CASE의 E는 Engineering. 만드는 사람(개발자)을 돕는 도구이지 쓰는 사람(사용자) 교육용이 아니다."}},{"id":"written-2021-1-12","no":12,"unit":"소프트웨어 설계","q":"UML(Unified Modeling Language)에 대한 설명 중 틀린 것은?","choices":["기능적 모델은 사용자 측면에서 본 시스템 기능이며, UML에서는 Use case Diagram을 사용한다.","정적 모델은 객체, 속성, 연관관계, 오퍼레이션의 시스템의 구조를 나타내며, UML에서는 Class Diagram을 사용한다.","동적 모델은 시스템의 내부 동작을 말하며, UML에서는 Sequence Diagram, State Diagram, Activity Diagram을 사용한다.","State Diagram은 객체들 사이의 메시지 교환을 나타내며, Sequence Diagram은 하나의 객체가 가진 상태와 그 상태의 변화에 의한 동작순서를 나타낸다."],"ans":4,"rate":59,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML로 시스템을 볼 때 기능 모델은 유스케이스 다이어그램, 정적 모델은 클래스 다이어그램, 동적 모델은 시퀀스·상태·활동 다이어그램 등으로 표현한다. 시퀀스 다이어그램은 객체들이 시간 순서에 따라 주고받는 메시지를 그리고, 상태 다이어그램은 한 객체의 상태가 이벤트에 따라 어떻게 바뀌는지 그린다.","choices":[{"verdict":"오답","why":"기능적 모델은 사용자 관점의 시스템 기능을 나타내며 유스케이스 다이어그램을 사용한다. 맞는 설명이다."},{"verdict":"오답","why":"정적 모델은 객체, 속성, 연관 관계, 오퍼레이션 같은 시스템 구조를 나타내며 클래스 다이어그램을 사용한다. 맞는 설명이다."},{"verdict":"오답","why":"동적 모델은 시스템 내부 동작을 나타내며 시퀀스, 상태, 활동 다이어그램 등을 사용한다. 맞는 설명이다."},{"verdict":"정답","why":"두 다이어그램의 설명이 서로 바뀌었다. 객체들 사이의 메시지 교환을 나타내는 것이 시퀀스 다이어그램이고, 한 객체의 상태와 그 변화를 나타내는 것이 상태 다이어그램이다."}],"keywords":[{"term":"시퀀스 다이어그램","desc":"객체 간 메시지 교환을 시간 순서로 표현"},{"term":"상태 다이어그램","desc":"한 객체의 상태 변화와 그 원인(이벤트) 표현"},{"term":"클래스 다이어그램","desc":"클래스와 속성, 관계의 정적 구조 표현"},{"term":"유스케이스 다이어그램","desc":"사용자 관점의 시스템 기능 표현"}],"memo":"Sequence는 순서대로 오가는 메시지, State는 한 객체의 상태 변화. 이름 그대로 짝지으면 바뀐 설명을 바로 잡는다."}},{"id":"written-2021-1-13","no":13,"unit":"소프트웨어 설계","q":"기본 유스케이스 수행 시 특별한 조건을 만족할 때 수행하는 유스케이스는?","choices":["연관","확장","선택","특화"],"ans":2,"rate":54,"exp":{"concept":"유스케이스 사이의 관계에는 포함(include), 확장(extend), 일반화(generalization) 등이 있다. 확장 관계는 기본 유스케이스를 수행하다가 특별한 조건을 만족할 때만 추가로 수행되는 유스케이스를 연결한다. 포함 관계는 조건 없이 항상 함께 수행되는 유스케이스를 연결한다.","choices":[{"verdict":"오답","why":"연관(Association) 관계는 액터와 유스케이스가 서로 상호작용함을 나타내는 관계다. 조건부 수행과는 관계없다."},{"verdict":"정답","why":"기본 유스케이스 수행 중 특정 조건을 만족할 때만 수행되는 유스케이스는 확장(extend) 관계로 연결한다."},{"verdict":"오답","why":"선택은 유스케이스 관계의 표준 용어가 아니다."},{"verdict":"오답","why":"특화는 유스케이스 관계의 표준 용어가 아니다. 상위·하위 유스케이스 사이의 관계는 일반화(generalization) 관계라고 한다."}],"keywords":[{"term":"확장(extend)","desc":"특정 조건을 만족할 때만 수행되는 유스케이스 연결"},{"term":"포함(include)","desc":"기본 유스케이스 수행 시 항상 함께 수행되는 유스케이스 연결"},{"term":"일반화(generalization)","desc":"상위 유스케이스와 이를 구체화한 하위 유스케이스의 관계"},{"term":"연관(association)","desc":"액터와 유스케이스의 상호작용"}],"memo":"포함은 '항상', 확장은 '조건이 맞을 때만'."}},{"id":"written-2021-1-14","no":14,"unit":"소프트웨어 설계","q":"다음 중 요구사항 모델링에 활용되지 않는 것은?","choices":["애자일(Agile) 방법","유스케이스 다이어그램(Use Case Diagram)","시퀀스 다이어그램(Sequence Diagram)","단계 다이어그램(Phase Diagram)"],"ans":4,"rate":60,"wiki":[{"title":"시퀀스 다이어그램","url":"https://itwiki.kr/w/시퀀스 다이어그램"},{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"},{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"요구사항 모델링은 수집한 요구사항을 그림이나 모델로 표현해 이해와 검증을 돕는 작업이다. UML의 유스케이스 다이어그램, 시퀀스 다이어그램 등이 쓰이고, 애자일 방법에서도 사용자 스토리 등으로 요구사항을 모델링한다. 단계 다이어그램(Phase Diagram)은 물질의 상태(고체·액체·기체)를 나타내는 과학 용어로 소프트웨어 요구사항 모델링 도구가 아니다.","choices":[{"verdict":"오답","why":"애자일 방법은 사용자 스토리 등을 이용해 요구사항을 짧은 주기로 모델링하고 반영하므로 요구사항 모델링에 활용된다."},{"verdict":"오답","why":"유스케이스 다이어그램은 사용자 관점에서 시스템 기능을 표현하는 대표적인 요구사항 모델링 도구다."},{"verdict":"오답","why":"시퀀스 다이어그램은 객체 간 상호작용 순서를 표현해 요구사항의 동작 흐름을 모델링하는 데 쓰인다."},{"verdict":"정답","why":"단계 다이어그램(Phase Diagram)은 물질의 상(相)을 나타내는 그림으로, 소프트웨어 요구사항 모델링에 쓰이는 도구가 아니다."}],"keywords":[{"term":"요구사항 모델링","desc":"요구사항을 모델로 표현해 이해·검증을 돕는 작업"},{"term":"유스케이스 다이어그램","desc":"사용자 관점의 기능 요구사항 표현"},{"term":"사용자 스토리","desc":"애자일에서 쓰는 짧은 요구사항 서술"}],"memo":"보기 중 UML이나 개발 방법론에 없는 낯선 다이어그램 이름이 나오면 그것이 정답일 가능성이 높다."}},{"id":"written-2021-1-15","no":15,"unit":"소프트웨어 설계","q":"디자인 패턴을 이용한 소프트웨어 재사용으로 얻어지는 장 점이 아닌 것은?","choices":["소프트웨어 코드의 품질을 향상시킬 수 있다.","개발 프로세스를 무시할 수 있다.","개발자들 사이의 의사소통을 원활하게 할 수 있다.","소프트웨어의 품질과 생산성을 향상시킬 수 있다."],"ans":2,"rate":94,"wiki":[{"title":"소프트웨어 재사용","url":"https://itwiki.kr/w/소프트웨어 재사용"}],"exp":{"concept":"디자인 패턴은 자주 마주치는 설계 문제에 대해 검증된 해결 방법을 정리해 둔 것이다. 이를 재사용하면 코드 품질과 생산성이 오르고, 개발자들이 패턴 이름만으로 설계 의도를 주고받을 수 있어 의사소통도 쉬워진다. 하지만 개발 프로세스 자체를 생략해도 된다는 뜻은 아니다.","choices":[{"verdict":"오답","why":"검증된 설계 구조를 재사용하므로 소프트웨어 코드의 품질이 향상된다. 디자인 패턴의 장점이다."},{"verdict":"정답","why":"디자인 패턴은 설계를 돕는 도구일 뿐, 분석·설계·구현·테스트 같은 개발 프로세스를 무시해도 된다는 의미가 아니다."},{"verdict":"오답","why":"'싱글턴으로 하자'처럼 패턴 이름으로 설계를 설명할 수 있어 개발자 간 의사소통이 원활해진다. 디자인 패턴의 장점이다."},{"verdict":"오답","why":"이미 검증된 해법을 쓰므로 품질과 생산성이 함께 향상된다. 디자인 패턴의 장점이다."}],"keywords":[{"term":"디자인 패턴(Design Pattern)","desc":"반복되는 설계 문제의 검증된 해결 방법"},{"term":"GoF 패턴","desc":"생성·구조·행위 3분류 23개 패턴"},{"term":"재사용성(Reusability)","desc":"이미 만든 설계·코드를 다른 곳에서 다시 쓰는 정도"}],"memo":"'무시할 수 있다', '필요 없다'처럼 절차를 건너뛴다는 표현은 장점 문항에서 대부분 오답 문장이다."}},{"id":"written-2021-1-16","no":16,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh) 분석기법에서 정보모델링이라고도 하며, 시스템에서 요구되는 객체를 찾아내어 속성과 연산 식별 및 객체들 간의 관계를 규정하여 다이어그램을 표시하는 모델링은?","choices":["Object","Dynamic","Function","Static"],"ans":1,"rate":68,"wiki":[{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"exp":{"concept":"럼바우(Rumbaugh)의 OMT는 객체 모델링 → 동적 모델링 → 기능 모델링 순서로 분석한다. 객체 모델링(Object Modeling)은 정보 모델링이라고도 하며, 시스템에 필요한 객체를 찾아 속성과 연산을 정하고 객체 간 관계를 객체 다이어그램으로 나타낸다. 동적 모델링은 상태 다이어그램, 기능 모델링은 자료 흐름도(DFD)를 쓴다.","choices":[{"verdict":"정답","why":"객체를 찾아 속성·연산과 객체 간 관계를 규정해 객체 다이어그램으로 표시하는 정보 모델링이 객체(Object) 모델링이다."},{"verdict":"오답","why":"동적(Dynamic) 모델링은 상태 다이어그램으로 시간에 따른 객체의 상태 변화와 제어 흐름을 표현한다."},{"verdict":"오답","why":"기능(Function) 모델링은 자료 흐름도(DFD)로 입력 값이 출력 값으로 바뀌는 과정을 표현한다."},{"verdict":"오답","why":"Static(정적) 모델링은 럼바우 분석 기법의 세 가지 모델링에 들어가지 않는다."}],"keywords":[{"term":"객체 모델링","desc":"정보 모델링, 객체 다이어그램으로 객체·속성·연산·관계 표현"},{"term":"동적 모델링","desc":"상태 다이어그램으로 상태 변화 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)로 데이터 처리 과정 표현"}],"memo":"럼바우는 '객동기'(객체 → 동적 → 기능). 정보 모델링 = 객체 모델링."}},{"id":"written-2021-1-17","no":17,"unit":"소프트웨어 설계","q":"소프트웨어를 개발하기 위한 비즈니스(업무)를 객체와 속성, 클래스와 멤버, 전체와 부분 등으로 나누어서 분석해 내는 기법은?","choices":["객체지향 분석","구조적 분석","기능적 분석","실시간 분석"],"ans":1,"rate":70,"exp":{"concept":"객체지향 분석은 업무를 객체와 속성, 클래스와 멤버, 전체와 부분 같은 단위로 나누어 바라보는 분석 기법이다. 현실 세계의 사물을 객체로 보고 그 객체가 가진 데이터와 행동을 함께 정리한다. 구조적 분석이 기능(처리 과정) 위주로 나누는 것과 대비된다.","choices":[{"verdict":"정답","why":"업무를 객체와 속성, 클래스와 멤버, 전체와 부분으로 나누어 분석하는 것이 객체지향 분석이다."},{"verdict":"오답","why":"구조적 분석은 자료 흐름도(DFD), 자료 사전 등을 이용해 시스템을 기능과 자료 흐름 중심으로 분석하는 기법이다."},{"verdict":"오답","why":"기능적 분석은 시스템이 수행해야 할 기능을 중심으로 나누는 관점으로, 객체·클래스 단위로 나누지 않는다."},{"verdict":"오답","why":"실시간 분석은 정해진 시간 안에 응답해야 하는 시스템의 시간 제약을 중심으로 보는 분석이며, 객체·클래스 단위 분석이 아니다."}],"keywords":[{"term":"객체지향 분석(OOA)","desc":"업무를 객체·클래스·관계 중심으로 분석"},{"term":"구조적 분석","desc":"DFD, 자료 사전, 소단위 명세서로 기능·자료 흐름 중심 분석"},{"term":"클래스(Class)","desc":"공통 속성과 연산을 가진 객체들의 틀"}],"memo":"'객체', '클래스', '멤버'라는 단어가 지문에 보이면 객체지향."}},{"id":"written-2021-1-18","no":18,"unit":"소프트웨어 설계","q":"애자일 소프트웨어 개발 기법의 가치가 아닌 것은?","choices":["프로세스의 도구보다는 개인과 상호작용에 더 가치를 둔다.","계약 협상보다는 고객과의 협업에 더 가치를 둔다.","실제 작동하는 소프트웨어보다는 이해하기 좋은 문서에 더 가치를 둔다.","계획을 따르기보다는 변화에 대응하는 것에 더 가치를 둔다."],"ans":3,"rate":88,"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"애자일 선언문은 네 가지 가치를 말한다. 프로세스와 도구보다 개인과 상호작용, 포괄적인 문서보다 작동하는 소프트웨어, 계약 협상보다 고객과의 협력, 계획을 따르기보다 변화에 대응하기에 더 가치를 둔다. 오른쪽 항목도 가치가 있지만 왼쪽 항목을 더 중시한다는 뜻이다.","choices":[{"verdict":"오답","why":"프로세스와 도구보다 개인과 상호작용을 중시하는 것은 애자일 선언문의 가치다."},{"verdict":"오답","why":"계약 협상보다 고객과의 협업을 중시하는 것은 애자일 선언문의 가치다."},{"verdict":"정답","why":"애자일은 문서보다 실제 작동하는 소프트웨어에 더 가치를 둔다. 보기는 순서가 거꾸로 되어 있다."},{"verdict":"오답","why":"계획을 따르기보다 변화에 대응하는 것을 중시하는 것은 애자일 선언문의 가치다."}],"keywords":[{"term":"애자일 선언문(Agile Manifesto)","desc":"개인·상호작용, 작동하는 SW, 고객 협력, 변화 대응을 중시"},{"term":"애자일 방법론","desc":"XP, 스크럼, 칸반, 린 등"},{"term":"XP(eXtreme Programming)","desc":"짧은 반복과 고객 참여를 강조하는 애자일 방법론"}],"memo":"애자일은 '빠르고 유연하게'. 문서·계획·계약·도구처럼 무겁고 딱딱한 쪽을 더 중시한다고 하면 틀린 문장이다."}},{"id":"written-2021-1-19","no":19,"unit":"소프트웨어 설계","q":"UML 다이어그램 중 시스템 내 클래스의 정적 구조를 표현하고 클래스와 클래스, 클래스의 속성 사이의 관계를 나타내는 것은?","choices":["Activity Diagram","Modea Diagram","State Diagram","Class Diagram"],"ans":4,"rate":75,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"클래스 다이어그램은 시스템을 이루는 클래스와 그 속성, 연산, 그리고 클래스 사이의 관계(연관, 상속, 의존 등)를 표현하는 정적(구조) 다이어그램이다. 시간이 흘러도 바뀌지 않는 시스템의 뼈대를 보여 준다. 활동 다이어그램과 상태 다이어그램은 동작을 나타내는 행위 다이어그램이다.","choices":[{"verdict":"오답","why":"활동(Activity) 다이어그램은 처리 흐름과 순서를 표현하는 행위(동적) 다이어그램이다."},{"verdict":"오답","why":"Modea Diagram은 UML에 존재하지 않는 다이어그램이다."},{"verdict":"오답","why":"상태(State) 다이어그램은 객체의 상태가 이벤트에 따라 어떻게 바뀌는지 표현하는 행위(동적) 다이어그램이다."},{"verdict":"정답","why":"클래스와 속성, 클래스 간 관계를 표현하는 정적 구조 다이어그램은 클래스(Class) 다이어그램이다."}],"keywords":[{"term":"구조(정적) 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지"},{"term":"행위(동적) 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍"},{"term":"클래스 다이어그램","desc":"클래스·속성·연산·관계의 정적 구조"}],"memo":"'정적 구조'와 '클래스'가 함께 나오면 고민 없이 클래스 다이어그램."}},{"id":"written-2021-1-20","no":20,"unit":"소프트웨어 설계","q":"소프트웨어 설계시 제일 상위에 있는 main user function에서 시작하여 기능을 하위 기능들로 분할해 가면서 설계하는 방식은?","choices":["객체 지향 설계","데이터 흐름 설계","상향식 설계","하향식 설계"],"ans":4,"rate":83,"wiki":[{"title":"소프트웨어 설계","url":"https://itwiki.kr/w/소프트웨어 설계"}],"exp":{"concept":"하향식 설계(Top-Down Design)는 가장 위의 주요 기능(main user function)에서 출발해 그것을 더 작은 하위 기능으로 차례로 쪼개 내려가며 설계하는 방식이다. 큰 목차를 먼저 정하고 장, 절, 문단 순으로 채워 가는 글쓰기와 같다. 반대로 상향식 설계는 작은 모듈부터 만들어 위로 조립해 올라간다.","choices":[{"verdict":"오답","why":"객체 지향 설계는 시스템을 객체와 클래스 단위로 나누어 설계하는 방식이며, 기능을 위에서 아래로 분할하는 방식이 아니다."},{"verdict":"오답","why":"데이터 흐름 설계는 자료 흐름도를 바탕으로 프로그램 구조를 만드는 방식으로, 상위 기능부터 분할하는 방식 자체를 가리키는 용어가 아니다."},{"verdict":"오답","why":"상향식 설계는 최하위 모듈부터 먼저 설계하고 이를 조합해 위로 올라가는 방식이다."},{"verdict":"정답","why":"최상위 기능에서 시작해 하위 기능으로 분할해 가는 설계 방식이 하향식 설계다."}],"keywords":[{"term":"하향식 설계(Top-Down)","desc":"최상위 기능부터 하위 기능으로 분할"},{"term":"상향식 설계(Bottom-Up)","desc":"최하위 모듈부터 만들어 위로 조합"},{"term":"단계적 분할(Stepwise Refinement)","desc":"큰 기능을 점점 세분화하는 하향식 설계 기법"}],"memo":"'제일 상위'에서 '분할해 내려가면' 하향식(Top-Down)."}},{"id":"written-2021-1-21","no":21,"unit":"소프트웨어 개발","q":"구현 단계에서의 작업 절차를 순서에 맞게 나열한 것은?\n<img src=\"data/img/eip_written_20210307_021.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠-㉡-㉢-㉣","㉡-㉠-㉣-㉢","㉢-㉠-㉡-㉣","㉣-㉡-㉠-㉢"],"ans":2,"rate":92,"exp":{"concept":"구현 단계는 설계를 실제 프로그램으로 옮기는 단계다. 먼저 코딩 작업을 계획하고, 계획에 따라 코딩한 뒤, 작성한 코드를 컴파일해 실행 가능한 형태로 만들고, 마지막으로 코드를 테스트한다. 집 짓기로 치면 시공 계획 → 시공 → 완공 → 점검 순서다.","choices":[{"verdict":"오답","why":"코딩 계획(㉡)보다 코딩(㉠)이 먼저 오고, 컴파일(㉣)보다 테스트(㉢)가 먼저 와서 순서가 맞지 않는다."},{"verdict":"정답","why":"코딩 작업 계획(㉡) → 코딩(㉠) → 컴파일(㉣) → 테스트(㉢) 순서가 구현 단계의 작업 절차다."},{"verdict":"오답","why":"테스트(㉢)를 맨 앞에 두었는데, 테스트할 코드가 없는 상태에서는 테스트를 할 수 없다."},{"verdict":"오답","why":"컴파일(㉣)을 맨 앞에 두었는데, 작성된 코드가 있어야 컴파일할 수 있다."}],"keywords":[{"term":"구현 단계 절차","desc":"코딩 계획 → 코딩 → 컴파일 → 테스트"},{"term":"컴파일(Compile)","desc":"소스 코드를 기계가 실행할 수 있는 코드로 번역"},{"term":"단위 테스트","desc":"구현 단계에서 개별 모듈을 검사"}],"memo":"계획 → 작성 → 번역(컴파일) → 검사. 무엇이든 '계획'이 먼저, '테스트'가 마지막이다."}},{"id":"written-2021-1-22","no":22,"unit":"소프트웨어 개발","q":"다음 자료에 대하여 “Selection Sort”를 사용하여 오름차순으로 정렬한 경우 PASS 3의 결과는?\n<img src=\"data/img/eip_written_20210307_022.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["3, 4, 7, 9, 8","3, 4, 8, 9, 7","3, 8, 4, 9, 7","3, 4, 7, 8, 9"],"ans":1,"rate":55,"wiki":[{"title":"선택 정렬","url":"https://itwiki.kr/w/선택 정렬"}],"exp":{"concept":"선택 정렬(Selection Sort)은 매 패스마다 정렬되지 않은 부분에서 가장 작은 값을 찾아 그 구간의 맨 앞 자리와 교환한다. 초기 상태 8, 3, 4, 9, 7에서 PASS 1은 최솟값 3을 첫 자리의 8과 바꿔 3, 8, 4, 9, 7이 된다. PASS 2는 남은 8, 4, 9, 7 중 최솟값 4를 둘째 자리 8과 바꿔 3, 4, 8, 9, 7, PASS 3은 남은 8, 9, 7 중 최솟값 7을 셋째 자리 8과 바꿔 3, 4, 7, 9, 8이 된다.","choices":[{"verdict":"정답","why":"PASS 3에서 셋째 자리의 8과 남은 값 중 최솟값 7을 교환하면 3, 4, 7, 9, 8이 된다."},{"verdict":"오답","why":"3, 4, 8, 9, 7은 PASS 2가 끝난 상태다."},{"verdict":"오답","why":"3, 8, 4, 9, 7은 PASS 1이 끝난 상태다."},{"verdict":"오답","why":"3, 4, 7, 8, 9는 PASS 4가 끝난 최종 정렬 결과다."}],"keywords":[{"term":"선택 정렬(Selection Sort)","desc":"남은 구간의 최솟값을 찾아 맨 앞과 교환, n-1번 패스"},{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 값을 비교해 교환, 패스마다 가장 큰 값이 뒤로 이동"},{"term":"삽입 정렬(Insertion Sort)","desc":"앞쪽 정렬된 부분의 알맞은 위치에 값을 끼워 넣음"}],"memo":"선택 정렬은 PASS k가 끝나면 앞의 k칸이 확정된다. PASS 3이면 앞 세 칸이 3, 4, 7인지부터 확인한다."}},{"id":"written-2021-1-23","no":23,"unit":"소프트웨어 개발","q":"하향식 통합시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈은?","choices":["Stub","Driver","Procedure","Function"],"ans":1,"rate":82,"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"통합 테스트에서 아직 만들어지지 않은 모듈 대신 쓰는 임시 모듈이 있다. 하향식 통합은 위 모듈부터 시험하므로, 아직 없는 하위 모듈 자리에 필요한 조건만 갖춘 가짜 모듈인 스텁(Stub)을 둔다. 상향식 통합은 아래 모듈부터 시험하므로 이를 호출해 줄 임시 상위 모듈인 드라이버(Driver)를 둔다.","choices":[{"verdict":"정답","why":"하향식 통합 시험에서 아직 없는 하위 모듈을 대신하는 임시 시험용 모듈이 스텁(Stub)이다."},{"verdict":"오답","why":"드라이버(Driver)는 상향식 통합 시험에서 하위 모듈을 호출하고 결과를 받는 임시 상위 모듈이다."},{"verdict":"오답","why":"프로시저(Procedure)는 특정 작업을 수행하는 코드 묶음을 말하는 일반 용어로, 통합 시험용 임시 모듈이 아니다."},{"verdict":"오답","why":"함수(Function)는 값을 받아 처리하고 결과를 돌려주는 코드 단위를 말하는 일반 용어로, 통합 시험용 임시 모듈이 아니다."}],"keywords":[{"term":"스텁(Stub)","desc":"하향식 통합에서 하위 모듈을 대신하는 임시 모듈"},{"term":"테스트 드라이버(Driver)","desc":"상향식 통합에서 상위 모듈을 대신하는 임시 모듈"},{"term":"하향식 통합","desc":"상위 모듈부터 아래로 통합하며 시험"},{"term":"상향식 통합","desc":"하위 모듈부터 클러스터로 묶어 위로 통합하며 시험"}],"memo":"하향식-스텁, 상향식-드라이버. 위에서 내려오니 아래가 비어 있어 스텁으로 막는다."}},{"id":"written-2021-1-24","no":24,"unit":"소프트웨어 개발","q":"다음 전위식(prefix)을 후위식(postfix)으로 옳게 표현한 것은?\n<img src=\"data/img/eip_written_20210307_024.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["A B C + D / * E -","A B * C D / + E -","A B * C + D / E -","A B C + * D / E -"],"ans":4,"rate":65,"exp":{"concept":"전위식(prefix)은 연산자가 피연산자 앞에, 후위식(postfix)은 연산자가 피연산자 뒤에 온다. 전위식은 '연산자 피연산자 피연산자' 덩어리를 찾아 괄호로 묶으면 풀린다. - / * A + B C D E에서 + B C는 (B+C), * A (B+C)는 (A*(B+C)), / 그 결과 D는 ((A*(B+C))/D), 마지막 - 그 결과 E는 ((A*(B+C))/D)-E다. 이를 후위식으로 바꾸면 A B C + * D / E -가 된다.","choices":[{"verdict":"오답","why":"A B C + D / * E -는 (A*((B+C)/D))-E로, 곱셈과 나눗셈의 순서가 원래 식과 다르다."},{"verdict":"오답","why":"A B * C D / + E -는 ((A*B)+(C/D))-E로, 원래 식과 연산 구조가 다르다."},{"verdict":"오답","why":"A B * C + D / E -는 (((A*B)+C)/D)-E로, A가 B+C 전체가 아니라 B와만 곱해져 원래 식과 다르다."},{"verdict":"정답","why":"전위식을 중위식으로 풀면 ((A*(B+C))/D)-E이고, 이를 후위식으로 바꾸면 A B C + * D / E -다."}],"keywords":[{"term":"전위식(Prefix)","desc":"연산자 → 피연산자 → 피연산자 순서, 예: + A B"},{"term":"중위식(Infix)","desc":"피연산자 → 연산자 → 피연산자 순서, 예: A + B"},{"term":"후위식(Postfix)","desc":"피연산자 → 피연산자 → 연산자 순서, 예: A B +"}],"memo":"전위식은 뒤쪽에서부터 '연산자 뒤에 피연산자 두 개'가 붙은 덩어리를 찾아 하나씩 괄호로 묶으면 실수가 적다."}},{"id":"written-2021-1-25","no":25,"unit":"소프트웨어 개발","q":"그래프의 특수한 형태로 노드(Node)와 선분(Branch)으로 되어 있고, 정점 사이에 사이클(Cycle)이 형성되어 있지 않으며, 자료 사이의 관계성이 계층 형식으로 나타나는 비선형 구조는?","choices":["tree","network","stack","distributed"],"ans":1,"rate":86,"wiki":[{"title":"자료 구조","url":"https://itwiki.kr/w/자료 구조"},{"title":"비선형 자료 구조","url":"https://itwiki.kr/w/비선형 자료 구조"},{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"트리(Tree)는 그래프의 특수한 형태로, 노드(정점)와 선분(가지)으로 이루어지되 사이클이 없는 구조다. 하나의 루트에서 가지가 뻗어 나가 자료 사이의 관계가 회사 조직도처럼 계층 형식으로 나타난다. 앞뒤가 한 줄로 이어지지 않으므로 비선형 구조에 속한다.","choices":[{"verdict":"정답","why":"사이클이 없고 자료 관계가 계층 형식으로 나타나는 비선형 그래프 구조가 트리다."},{"verdict":"오답","why":"네트워크(그래프)는 정점과 간선으로 이루어진 비선형 구조지만 사이클이 생길 수 있어 계층 구조로 한정되지 않는다."},{"verdict":"오답","why":"스택(Stack)은 한쪽 끝에서만 삽입·삭제하는 선형 구조(LIFO)다."},{"verdict":"오답","why":"distributed(분산)는 자료구조의 이름이 아니다."}],"keywords":[{"term":"트리(Tree)","desc":"사이클 없는 계층형 비선형 구조"},{"term":"그래프(Graph)","desc":"정점과 간선으로 이루어진 비선형 구조, 사이클 가능"},{"term":"선형 구조","desc":"배열, 선형 리스트, 스택, 큐, 데크"},{"term":"비선형 구조","desc":"트리, 그래프"}],"memo":"'사이클 없음'과 '계층'이 함께 나오면 트리."}},{"id":"written-2021-1-26","no":26,"unit":"소프트웨어 개발","q":"스택에 대한 설명으로 틀린 것은?","choices":["입출력이 한쪽 끝으로만 제한된 리스트이다.","Head(front)와 Tail(rear)의 2개 포인터를 갖고 있다.","LIFO 구조이다.","더 이상 삭제할 데이터가 없는 상태에서 데이터를 삭제하면 언더플로(Underflow)가 발생한다."],"ans":2,"rate":71,"wiki":[{"title":"스택","url":"https://itwiki.kr/w/스택"}],"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)에서만 넣고(push) 빼는(pop) 자료구조로, 나중에 넣은 것이 먼저 나오는 LIFO 구조다. 그래서 위치를 가리키는 포인터도 Top 하나만 있으면 된다. 앞(Front)과 뒤(Rear) 두 포인터를 쓰는 것은 한쪽으로 넣고 반대쪽으로 빼는 큐(Queue)다.","choices":[{"verdict":"오답","why":"스택은 삽입과 삭제가 Top이라는 한쪽 끝에서만 일어나는 리스트다. 맞는 설명이다."},{"verdict":"정답","why":"Head(front)와 Tail(rear) 두 개의 포인터를 가지는 것은 큐다. 스택은 Top 포인터 하나만 가진다."},{"verdict":"오답","why":"마지막에 들어간 자료가 먼저 나오는 LIFO(Last In First Out) 구조다. 맞는 설명이다."},{"verdict":"오답","why":"스택이 비어 있는데 삭제(pop)하면 언더플로(Underflow), 가득 찼는데 삽입하면 오버플로(Overflow)가 발생한다. 맞는 설명이다."}],"keywords":[{"term":"스택(Stack)","desc":"LIFO, Top 포인터 하나, push·pop"},{"term":"큐(Queue)","desc":"FIFO, Front(삭제)와 Rear(삽입) 두 포인터"},{"term":"언더플로(Underflow)","desc":"빈 스택에서 삭제할 때 발생"},{"term":"오버플로(Overflow)","desc":"가득 찬 스택에 삽입할 때 발생"}],"memo":"스택은 접시 쌓기(위쪽 하나만 본다), 큐는 줄 서기(앞과 뒤 두 곳을 본다)."}},{"id":"written-2021-1-27","no":27,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM)에 사용되는 기술요소가 아닌 것은?","choices":["키관리","방화벽","암호화","크랙방지"],"ans":2,"rate":74,"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"exp":{"concept":"디지털 저작권 관리(DRM, Digital Rights Management)는 디지털 콘텐츠가 허락된 사람에게만, 허락된 방식으로 쓰이도록 보호하는 기술이다. 콘텐츠를 암호화하고, 암호화 키를 관리하고, 불법 복제를 막는 크랙 방지, 사용자 인증과 정책 관리 같은 기술 요소로 이루어진다. 방화벽은 네트워크 경계에서 트래픽을 거르는 보안 장비로 DRM 기술 요소가 아니다.","choices":[{"verdict":"오답","why":"키 관리는 콘텐츠를 암호화하고 풀 때 쓰는 키의 생성·저장·배포를 관리하는 DRM 기술 요소다."},{"verdict":"정답","why":"방화벽은 외부 네트워크에서 들어오는 접근을 통제하는 네트워크 보안 시스템으로, 콘텐츠 저작권 보호를 위한 DRM 기술 요소가 아니다."},{"verdict":"오답","why":"암호화는 콘텐츠와 라이선스를 암호화해 허가된 사용자만 쓸 수 있게 하는 DRM 기술 요소다."},{"verdict":"오답","why":"크랙 방지는 크랙에 의한 콘텐츠의 불법 사용을 막는 DRM 기술 요소다."}],"keywords":[{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠의 저작권을 보호하고 사용을 통제하는 기술"},{"term":"DRM 기술 요소","desc":"암호화, 키 관리, 암호화 파일 생성(패키저), 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증"},{"term":"방화벽(Firewall)","desc":"내부·외부 네트워크 사이의 트래픽을 통제하는 보안 시스템"}],"memo":"DRM은 콘텐츠 '파일'을 지키는 기술, 방화벽은 '네트워크'를 지키는 기술."}},{"id":"written-2021-1-28","no":28,"unit":"소프트웨어 개발","q":"여러 개의 선택 항목 중 하나의 선택만 가능한 경우 사용하는 사용자 인터페이스(UI)요소는?","choices":["토글 버튼","텍스트 박스","라디오 버튼","체크 박스"],"ans":3,"rate":72,"exp":{"concept":"UI 요소는 입력하는 방식에 따라 고른다. 여러 항목 중 딱 하나만 고르게 할 때는 라디오 버튼, 여러 개를 동시에 고를 수 있게 할 때는 체크 박스를 쓴다. 라디오 버튼이라는 이름은 옛날 라디오의 채널 버튼이 하나를 누르면 다른 버튼이 튀어나와 하나만 선택되던 데서 왔다.","choices":[{"verdict":"오답","why":"토글 버튼은 하나의 버튼으로 켜짐과 꺼짐 두 상태를 번갈아 바꾸는 요소다."},{"verdict":"오답","why":"텍스트 박스는 사용자가 글자를 직접 입력하는 요소다."},{"verdict":"정답","why":"라디오 버튼은 여러 선택 항목 중 하나만 선택할 수 있는 UI 요소다."},{"verdict":"오답","why":"체크 박스는 여러 항목 중 여러 개를 동시에 선택할 수 있는 UI 요소다."}],"keywords":[{"term":"라디오 버튼","desc":"여러 항목 중 하나만 선택"},{"term":"체크 박스","desc":"여러 항목을 중복 선택"},{"term":"토글 버튼","desc":"켜기·끄기 두 상태 전환"},{"term":"콤보 박스","desc":"목록에서 선택하거나 직접 입력"}],"memo":"하나만이면 라디오, 여러 개면 체크."}},{"id":"written-2021-1-29","no":29,"unit":"소프트웨어 개발","q":"소프트웨어의 일부분을 다른 시스템에서 사용할 수 있는 정도를 의미하는 것은?","choices":["신뢰성(Reliability)","유지보수성(Maintainability)","가시성(Visibility)","재사용성(Reusability)"],"ans":4,"rate":88,"exp":{"concept":"재사용성(Reusability)은 이미 만든 소프트웨어의 전부나 일부를 다른 시스템에서도 다시 쓸 수 있는 정도다. 잘 만든 부품을 다른 제품에도 그대로 끼워 쓰는 것과 같다. 재사용성이 높으면 개발 기간과 비용이 줄고 검증된 코드를 써서 품질도 오른다.","choices":[{"verdict":"오답","why":"신뢰성(Reliability)은 소프트웨어가 정해진 조건에서 오류 없이 요구된 기능을 정확하게 수행하는 정도다."},{"verdict":"오답","why":"유지보수성(Maintainability)은 변경이나 오류 수정을 쉽게 할 수 있는 정도다."},{"verdict":"오답","why":"가시성(Visibility)은 개발 진행 상황이나 내부 구조를 외부에서 볼 수 있는 정도로, 다른 시스템에서 다시 쓰는 정도와는 관계없다."},{"verdict":"정답","why":"소프트웨어의 일부분을 다른 시스템에서 다시 사용할 수 있는 정도는 재사용성이다."}],"keywords":[{"term":"재사용성(Reusability)","desc":"다른 시스템에서 다시 쓸 수 있는 정도"},{"term":"신뢰성(Reliability)","desc":"오류 없이 정확하게 기능을 수행하는 정도"},{"term":"유지보수성(Maintainability)","desc":"수정·개선을 쉽게 할 수 있는 정도"},{"term":"이식성(Portability)","desc":"다른 환경(HW·OS)에서도 쉽게 동작하게 옮길 수 있는 정도"}],"memo":"Re(다시) + Use(쓰다) = 다시 쓸 수 있는 정도."}},{"id":"written-2021-1-30","no":30,"unit":"소프트웨어 개발","q":"자료구조에 대한 설명으로 틀린 것은?","choices":["큐는 비선형구조에 해당한다.","큐는 First In – First Out 처리를 수행한다.","스택은 Last In – First out 처리를 수행한다.","스택은 서브루틴 호출, 인터럽트 처리, 수식 계산 및 수식 표기법에 응용된다."],"ans":1,"rate":75,"wiki":[{"title":"자료 구조","url":"https://itwiki.kr/w/자료 구조"},{"title":"선형_자료_구조","url":"https://itwiki.kr/w/선형_자료_구조"},{"title":"비선형 자료 구조","url":"https://itwiki.kr/w/비선형 자료 구조"}],"exp":{"concept":"자료구조는 자료가 한 줄로 이어지느냐에 따라 선형과 비선형으로 나뉜다. 배열, 선형 리스트, 스택, 큐, 데크는 앞뒤 관계가 한 줄로 이어지는 선형 구조이고, 트리와 그래프는 비선형 구조다. 큐는 먼저 들어온 자료가 먼저 나가는 FIFO, 스택은 나중에 들어온 자료가 먼저 나가는 LIFO 구조다.","choices":[{"verdict":"정답","why":"큐는 자료가 한 줄로 나열되는 선형 구조다. 비선형 구조는 트리와 그래프다."},{"verdict":"오답","why":"큐는 먼저 들어온 자료가 먼저 나가는 FIFO(First In First Out) 구조다. 맞는 설명이다."},{"verdict":"오답","why":"스택은 마지막에 들어온 자료가 먼저 나가는 LIFO(Last In First Out) 구조다. 맞는 설명이다."},{"verdict":"오답","why":"스택은 서브루틴 호출 시 복귀 주소 저장, 인터럽트 처리, 수식 계산, 후위식 변환 등에 쓰인다. 맞는 설명이다."}],"keywords":[{"term":"선형 구조","desc":"배열, 선형 리스트, 스택, 큐, 데크"},{"term":"비선형 구조","desc":"트리, 그래프"},{"term":"큐(Queue)","desc":"FIFO, 운영체제 작업 스케줄링 등에 응용"},{"term":"스택(Stack)","desc":"LIFO, 서브루틴 호출·인터럽트·수식 계산에 응용"}],"memo":"비선형은 트리와 그래프 둘뿐이라고 외우면 나머지는 모두 선형이다."}},{"id":"written-2021-1-31","no":31,"unit":"소프트웨어 개발","q":"다음 중 블랙박스 검사 기법은?","choices":["경계값 분석","조건 검사","기초 경로 검사","루프 검사"],"ans":1,"rate":70,"wiki":[{"title":"블랙박스 테스트","url":"https://itwiki.kr/w/블랙박스 테스트"}],"exp":{"concept":"블랙박스 검사는 프로그램 내부 코드를 보지 않고 입력과 출력만으로 요구된 기능이 맞게 동작하는지 확인하는 검사다. 동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사 등이 있다. 화이트박스 검사는 코드 내부 구조를 보고 경로와 조건을 따지는 검사로 기초 경로, 조건, 루프, 데이터 흐름 검사 등이 있다.","choices":[{"verdict":"정답","why":"경계값 분석은 입력 범위의 경계 근처 값을 테스트하는 블랙박스 검사 기법이다."},{"verdict":"오답","why":"조건 검사는 프로그램 안의 논리적 조건을 검사하는 화이트박스 검사 기법이다."},{"verdict":"오답","why":"기초 경로 검사는 제어 흐름을 바탕으로 실행 경로의 기초 집합을 정해 검사하는 화이트박스 검사 기법이다."},{"verdict":"오답","why":"루프 검사는 프로그램의 반복 구조에 초점을 맞춘 화이트박스 검사 기법이다."}],"keywords":[{"term":"블랙박스 검사","desc":"동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 검사","desc":"기초 경로, 조건, 루프, 데이터 흐름 검사"},{"term":"경계값 분석(Boundary Value Analysis)","desc":"입력 범위의 경계값에서 오류가 많다는 점을 이용한 검사"}],"memo":"블랙박스는 '값'(입력·출력)을 보고, 화이트박스는 '경로·조건·루프'(코드 구조)를 본다."}},{"id":"written-2021-1-32","no":32,"unit":"소프트웨어 개발","q":"이진 검색 알고리즘에 대한 설명으로 틀린 것은?","choices":["탐색 효율이 좋고 탐색 시간이 적게 소요된다.","검색할 데이터가 정렬되어 있어야 한다.","피보나치 수열에 따라 다음에 비교할 대상을 선정하여 검색한다.","비교횟수를 거듭할 때마다 검색 대상이 되는 데이터의 수가 절반으로 줄어든다."],"ans":3,"rate":62,"wiki":[{"title":"이진 검색","url":"https://itwiki.kr/w/이진 검색"}],"exp":{"concept":"이진 검색(Binary Search)은 정렬된 자료에서 가운데 값과 찾는 값을 비교해, 찾는 값이 더 작으면 왼쪽 절반, 크면 오른쪽 절반만 남기고 다시 가운데를 비교하는 방법이다. 한 번 비교할 때마다 검색 대상이 절반으로 줄어 매우 빠르다. 사전에서 단어를 찾을 때 대충 가운데를 펼쳐 앞뒤를 정하는 것과 비슷하다.","choices":[{"verdict":"오답","why":"비교할 때마다 대상이 절반으로 줄어 탐색 효율이 좋고 시간이 적게 걸린다. 맞는 설명이다."},{"verdict":"오답","why":"가운데 값과 비교해 좌우를 정하는 방식이므로 데이터가 반드시 정렬되어 있어야 한다. 맞는 설명이다."},{"verdict":"정답","why":"피보나치 수열에 따라 다음 비교 대상을 정하는 것은 피보나치 검색이다. 이진 검색은 구간의 가운데 값을 비교 대상으로 삼는다."},{"verdict":"오답","why":"가운데 값과 비교한 뒤 한쪽 절반만 남기므로 비교할 때마다 검색 대상이 절반으로 줄어든다. 맞는 설명이다."}],"keywords":[{"term":"이진 검색(Binary Search)","desc":"정렬된 자료의 중간값과 비교해 범위를 절반씩 줄임"},{"term":"피보나치 검색(Fibonacci Search)","desc":"피보나치 수열로 비교 위치를 정하는 검색"},{"term":"순차 검색(Sequential Search)","desc":"처음부터 하나씩 차례로 비교, 정렬 불필요"}],"memo":"이진(Binary) 검색은 가운데를 기준으로 반씩 잘라 나간다. 피보나치 수열로 위치를 정하면 피보나치 검색이다."}},{"id":"written-2021-1-33","no":33,"unit":"소프트웨어 개발","q":"소프트웨어 품질목표 중 쉽게 배우고 사용할 수 있는 정도를 나타내는 것은?","choices":["Correctness","Reliability","Usability","Integrity"],"ans":3,"rate":87,"exp":{"concept":"소프트웨어 품질 목표에는 정확성, 신뢰성, 효율성, 무결성, 사용 용이성, 유지보수 용이성, 이식성 등이 있다. 사용 용이성(Usability)은 사용자가 소프트웨어를 쉽게 배우고 편하게 쓸 수 있는 정도다. 처음 보는 앱도 설명서 없이 금방 쓸 수 있다면 사용 용이성이 높은 것이다.","choices":[{"verdict":"오답","why":"정확성(Correctness)은 사용자의 요구 기능을 충족시키는 정도다."},{"verdict":"오답","why":"신뢰성(Reliability)은 정해진 조건에서 오류 없이 기능을 정확하게 수행하는 정도다."},{"verdict":"정답","why":"쉽게 배우고 사용할 수 있는 정도는 사용 용이성(Usability)이다."},{"verdict":"오답","why":"무결성(Integrity)은 허가받지 않은 사용자의 접근이나 변경으로부터 소프트웨어와 데이터를 보호하는 정도다."}],"keywords":[{"term":"Usability(사용 용이성)","desc":"쉽게 배우고 사용할 수 있는 정도"},{"term":"Correctness(정확성)","desc":"사용자 요구 기능을 충족하는 정도"},{"term":"Reliability(신뢰성)","desc":"오류 없이 기능을 정확히 수행하는 정도"},{"term":"Integrity(무결성)","desc":"허가되지 않은 접근·변경으로부터 보호하는 정도"}],"memo":"Use(쓰다) + ability(능력) = 쓰기 쉬운 정도."}},{"id":"written-2021-1-34","no":34,"unit":"소프트웨어 개발","q":"테스트 케이스에 일반적으로 포함되는 항목이 아닌 것은?","choices":["테스트 조건","테스트 데이터","테스트 비용","예상 결과"],"ans":3,"rate":81,"exp":{"concept":"테스트 케이스는 특정 요구사항이 제대로 구현되었는지 확인하기 위해 설계한 입력값, 실행 조건, 기대 결과의 묶음이다. 보통 테스트 케이스 식별자, 테스트 항목, 테스트 조건, 테스트 데이터(입력값), 예상 결과 등이 들어간다. 비용은 프로젝트 관리의 대상이지 개별 테스트 케이스의 항목이 아니다.","choices":[{"verdict":"오답","why":"어떤 상황에서 테스트할지 정하는 테스트 조건은 테스트 케이스의 기본 항목이다."},{"verdict":"오답","why":"테스트에 실제로 넣을 입력값인 테스트 데이터는 테스트 케이스의 기본 항목이다."},{"verdict":"정답","why":"테스트 비용은 테스트 계획이나 프로젝트 관리에서 다루는 내용으로, 일반적인 테스트 케이스 항목이 아니다."},{"verdict":"오답","why":"실행 결과와 비교할 예상 결과는 테스트 케이스의 기본 항목이다."}],"keywords":[{"term":"테스트 케이스(Test Case)","desc":"입력값, 실행 조건, 기대 결과로 구성된 테스트 항목 명세"},{"term":"테스트 오라클(Test Oracle)","desc":"테스트 결과가 옳은지 판단하는 기준"},{"term":"테스트 시나리오","desc":"여러 테스트 케이스를 수행 순서대로 묶은 것"}],"memo":"테스트 케이스는 '무엇을 넣으면(데이터) 어떤 조건에서(조건) 무엇이 나와야 하나(예상 결과)'. 돈 이야기는 없다."}},{"id":"written-2021-1-35","no":35,"unit":"소프트웨어 개발","q":"소프트웨어 설치 매뉴얼에 포함될 항목이 아닌 것은?","choices":["제품 소프트웨어 개요","설치 관련 파일","프로그램 삭제","소프트웨어 개발 기간"],"ans":4,"rate":89,"exp":{"concept":"설치 매뉴얼은 사용자가 소프트웨어를 처음 설치하는 과정을 처음부터 끝까지 안내하는 문서다. 제품 소프트웨어 개요, 설치 관련 파일, 설치 아이콘, 설치 환경과 절차, 프로그램 삭제 방법, 관련 추가 정보 등이 들어간다. 사용자가 설치하는 데 필요 없는 개발 기간 같은 내부 정보는 넣지 않는다.","choices":[{"verdict":"오답","why":"제품 소프트웨어 개요는 설치할 제품의 주요 기능과 구성을 설명하는 설치 매뉴얼 항목이다."},{"verdict":"오답","why":"설치 관련 파일은 설치에 필요한 파일과 그 역할을 설명하는 설치 매뉴얼 항목이다."},{"verdict":"오답","why":"프로그램 삭제는 설치한 소프트웨어를 제거하는 방법을 안내하는 설치 매뉴얼 항목이다."},{"verdict":"정답","why":"소프트웨어 개발 기간은 사용자의 설치 작업과 관계없는 정보로, 설치 매뉴얼에 포함되지 않는다."}],"keywords":[{"term":"설치 매뉴얼","desc":"설치 전 준비부터 설치 완료·삭제까지 안내하는 문서"},{"term":"설치 매뉴얼 구성","desc":"제품 개요, 설치 관련 파일, 설치 아이콘, 설치 절차, 프로그램 삭제, 추가 정보"},{"term":"사용자 매뉴얼","desc":"설치 후 소프트웨어 사용 방법을 안내하는 문서"}],"memo":"설치 매뉴얼은 사용자 눈높이 문서다. 개발자 내부 사정(기간, 인력, 비용)은 들어가지 않는다."}},{"id":"written-2021-1-36","no":36,"unit":"소프트웨어 개발","q":"소프트웨어 형상관리(Configuration management)에 관한 설명으로 틀린 것은?","choices":["소프트웨어에서 일어나는 수정이나 변경을 알아내고 제어하는 것을 의미한다.","소프트웨어 개발의 전체 비용을 줄이고, 개발 과정의 여러 방해 요인이 최소화되도록 보증하는 것을 목적으로 한다.","형상관리를 위하여 구성된 팀을 “chief programmer team”이라고 한다.","형상관리의 기능 중 하나는 버전 제어 기술이다."],"ans":3,"rate":67,"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"},{"title":"버전 관리 시스템","url":"https://itwiki.kr/w/버전 관리 시스템"}],"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 소프트웨어 개발 과정에서 생기는 변경 사항을 찾아내고 기록하고 통제하는 활동이다. 형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록 등의 기능이 있다. 형상 관리를 담당하는 조직은 형상 통제 위원회(CCB) 등이며, '책임 프로그래머 팀'은 개발 팀 구성 방식의 하나다.","choices":[{"verdict":"오답","why":"형상 관리는 소프트웨어의 수정과 변경을 알아내고 제어하는 것이다. 맞는 설명이다."},{"verdict":"오답","why":"변경을 체계적으로 관리해 개발 비용을 줄이고 개발 과정의 방해 요인을 최소화하는 것이 형상 관리의 목적이다. 맞는 설명이다."},{"verdict":"정답","why":"책임 프로그래머 팀(Chief Programmer Team)은 한 명의 책임 프로그래머를 중심으로 구성하는 개발 팀 조직 형태로, 형상 관리를 위해 구성한 팀이 아니다."},{"verdict":"오답","why":"버전 제어는 변경된 소프트웨어의 여러 버전을 관리하는 형상 관리의 주요 기능이다. 맞는 설명이다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"개발 중 변경 사항을 식별·통제·기록하는 활동"},{"term":"형상 관리 기능","desc":"형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록"},{"term":"책임 프로그래머 팀","desc":"책임 프로그래머 1명을 중심으로 한 계층적 개발 팀 구성"},{"term":"형상 관리 도구","desc":"CVS, SVN, Git 등"}],"memo":"chief programmer team은 '팀 구성 방식'이다. 형상 관리 문항에 나오면 함정이다."}},{"id":"written-2021-1-37","no":37,"unit":"소프트웨어 개발","q":"퀵 정렬에 관한 설명으로 옳은 것은?","choices":["레코드의 키 값을 분석하여 같은 값끼리 그 순서에 맞는 버킷에 분배하였다가 버킷의 순서대로 레코드를 꺼내어 정렬한다.","주어진 파일에서 인접한 두 개의 레코드 키 값을 비교하여 그 크기에 따라 레코드 위치를 서로 교환한다.","레코드의 많은 자료 이동을 없애고 하나의 파일을 부분적으로 나누어 가면서 정렬한다.","임의의 레코드 키와 매개변수(h)값만큼 떨어진 곳의 레코드 키를 비교하여 서로 교환해 가면서 정렬한다."],"ans":3,"rate":50,"wiki":[{"title":"퀵 정렬","url":"https://itwiki.kr/w/퀵 정렬"}],"exp":{"concept":"퀵 정렬(Quick Sort)은 기준값(피벗)을 하나 정하고, 피벗보다 작은 값은 왼쪽, 큰 값은 오른쪽으로 나눈 뒤 양쪽을 다시 같은 방법으로 정렬하는 분할 정복 방식이다. 파일을 부분적으로 나누어 가며 정렬하므로 자료 이동이 적고 평균적으로 매우 빠르다. 평균 시간 복잡도는 O(n log n), 최악은 O(n²)이다.","choices":[{"verdict":"오답","why":"키 값을 분석해 같은 값끼리 버킷에 분배했다가 차례로 꺼내 정렬하는 것은 기수 정렬(Radix Sort, 버킷 정렬)이다."},{"verdict":"오답","why":"인접한 두 레코드의 키 값을 비교해 크기에 따라 위치를 교환하는 것은 버블 정렬(Bubble Sort)이다."},{"verdict":"정답","why":"자료 이동을 줄이고 하나의 파일을 부분적으로 나누어 가면서 정렬하는 것은 퀵 정렬이다."},{"verdict":"오답","why":"매개변수 h만큼 떨어진 레코드끼리 비교·교환하며 정렬하는 것은 쉘 정렬(Shell Sort)이다."}],"keywords":[{"term":"퀵 정렬(Quick Sort)","desc":"피벗 기준 분할 정복, 평균 O(n log n), 최악 O(n²)"},{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 값을 비교·교환"},{"term":"쉘 정렬(Shell Sort)","desc":"간격 h만큼 떨어진 값끼리 삽입 정렬, 간격을 줄여 감"},{"term":"기수 정렬(Radix Sort)","desc":"자릿수별로 버킷에 분배했다가 모아 정렬"}],"memo":"버킷=기수, 인접 교환=버블, 간격 h=쉘, 나누어 정복=퀵."}},{"id":"written-2021-1-38","no":38,"unit":"소프트웨어 개발","q":"해싱 함수(Hashing Function)의 종류가 아닌 것은?","choices":["제곱법(mid-square)","숫자분석법(digit analysis)","개방주소법(open addressing)","제산법(division)"],"ans":3,"rate":66,"wiki":[{"title":"해시","url":"https://itwiki.kr/w/해시"}],"exp":{"concept":"해싱 함수는 키 값을 계산해 데이터가 저장될 주소(홈 주소)를 정하는 함수다. 대표적으로 제산법, 제곱법, 폴딩법, 기수 변환법, 숫자 분석법, 무작위법 등이 있다. 서로 다른 키가 같은 주소로 계산되는 충돌이 생기면 개방 주소법이나 체이닝 같은 충돌 해결 기법으로 처리한다.","choices":[{"verdict":"오답","why":"제곱법(Mid-Square)은 키 값을 제곱한 결과의 가운데 부분을 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"숫자 분석법(Digit Analysis)은 키를 이루는 숫자의 분포를 분석해 고르게 분포된 자릿수를 골라 주소로 쓰는 해싱 함수다."},{"verdict":"정답","why":"개방 주소법(Open Addressing)은 충돌이 생겼을 때 비어 있는 다른 주소를 찾아 저장하는 충돌 해결 기법으로, 해싱 함수가 아니다."},{"verdict":"오답","why":"제산법(Division)은 키 값을 특정한 수(보통 해시표 크기보다 큰 수 중 가장 작은 소수)로 나눈 나머지를 주소로 쓰는 해싱 함수다."}],"keywords":[{"term":"해싱 함수 종류","desc":"제산법, 제곱법, 폴딩법, 기수 변환법, 숫자 분석법, 무작위법"},{"term":"충돌(Collision)","desc":"서로 다른 키가 같은 홈 주소로 계산되는 현상"},{"term":"개방 주소법(Open Addressing)","desc":"충돌 시 빈 버킷을 찾아 저장하는 충돌 해결 기법"},{"term":"체이닝(Chaining)","desc":"충돌한 레코드를 연결 리스트로 이어 저장"}],"memo":"'~법'으로 끝나도 '주소법'은 주소를 계산하는 함수가 아니라 충돌 해결 방법이다."}},{"id":"written-2021-1-39","no":39,"unit":"소프트웨어 개발","q":"필드 테스팅(field testing)이라고도 불리며 개발자 없이 고객의 사용 환경에 소프트웨어를 설치하여 검사를 수행하는 인수검사 기법은?","choices":["베타 검사","알파 검사","형상 검사","복구 검사"],"ans":1,"rate":77,"wiki":[{"title":"인수 테스트","url":"https://itwiki.kr/w/인수 테스트"}],"exp":{"concept":"인수 테스트 중 알파 테스트와 베타 테스트는 장소와 개발자 참여 여부로 구분한다. 알파 테스트는 개발자의 장소에서 사용자가 개발자 앞에서 수행하는 통제된 환경의 테스트다. 베타 테스트는 실제 사용자의 환경에서 개발자 없이 수행하는 테스트로, 현장(field)에서 하기 때문에 필드 테스팅이라고도 한다.","choices":[{"verdict":"정답","why":"개발자 없이 고객의 실제 사용 환경에서 수행하는 필드 테스팅은 베타 검사다."},{"verdict":"오답","why":"알파 검사는 개발자의 장소에서 개발자가 지켜보는 가운데 사용자가 수행하는 검사다."},{"verdict":"오답","why":"형상 검사는 소프트웨어 구성 요소와 문서 등이 빠짐없이 갖추어졌는지 확인하는 검사로, 고객 환경에서 하는 인수 검사 기법이 아니다."},{"verdict":"오답","why":"복구 검사는 소프트웨어에 고의로 장애를 일으켜 정상적으로 복구되는지 확인하는 시스템 테스트다."}],"keywords":[{"term":"베타 테스트","desc":"사용자 환경, 개발자 없이 수행, 필드 테스팅"},{"term":"알파 테스트","desc":"개발자 장소, 개발자가 함께 있는 통제된 환경"},{"term":"인수 테스트(Acceptance Test)","desc":"사용자 요구를 충족하는지 사용자 입장에서 확인"},{"term":"복구 테스트(Recovery Test)","desc":"고의로 장애를 일으켜 복구 여부 확인"}],"memo":"필드(현장)에 내보내면 베타, 회사 안에서 개발자와 함께면 알파."}},{"id":"written-2021-1-40","no":40,"unit":"소프트웨어 개발","q":"다음 트리를 Preorder 운행법으로 운행할 경우 다섯 번째로 탐색되는 것은?\n<img src=\"data/img/eip_written_20210307_040.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["C","E","G","H"],"ans":2,"rate":86,"exp":{"concept":"전위 순회(Preorder)는 루트 → 왼쪽 서브트리 → 오른쪽 서브트리 순서로 방문한다. 그림의 트리는 A의 왼쪽 자식이 B(B의 왼쪽 자식 D), 오른쪽 자식이 C이고, C의 왼쪽 자식 E(E의 자식 G, H), 오른쪽 자식 F다. 방문 순서는 A, B, D, C, E, G, H, F이므로 다섯 번째는 E다.","choices":[{"verdict":"오답","why":"C는 A, B, D 다음 네 번째로 방문된다."},{"verdict":"정답","why":"A → B → D → C → E 순서로 E가 다섯 번째로 방문된다. C를 방문한 뒤 형제 F보다 왼쪽 자식 E로 먼저 내려간다."},{"verdict":"오답","why":"G는 E 다음 여섯 번째로 방문된다."},{"verdict":"오답","why":"H는 G 다음 일곱 번째로 방문되며, 마지막 여덟 번째가 F다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"Root → Left → Right"},{"term":"중위 순회(Inorder)","desc":"Left → Root → Right"},{"term":"후위 순회(Postorder)","desc":"Left → Right → Root"}],"memo":"전위·중위·후위는 루트(Root)를 언제 방문하느냐(앞·가운데·뒤)로 구분한다. 형제보다 자식이 먼저다."}},{"id":"written-2021-1-41","no":41,"unit":"데이터베이스 구축","q":"결과 값이 아래와 같을 때 SQL 질의로 옳은 것은?\n<img src=\"data/img/eip_written_20210307_041.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["SELECT * FROM 공급자 WHERE공급자명 LIKE '%신%';","SELECT * FROM 공급자 WHERE공급자명 LIKE '%대%';","SELECT * FROM 공급자 WHERE공급자명 LIKE '%사%';","SELECT * FROM 공급자 WHERE공급자명 IS NOT NULL;"],"ans":1,"rate":89,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"LIKE는 문자열 패턴으로 행을 고르는 SQL 조건이고, %는 0개 이상의 아무 문자를 뜻한다. '%신%'은 '신'이 어디든 들어 있는 값을 찾는다. 공급자 테이블에서 공급자명에 '신'이 들어 있는 행은 대신공업사(16)와 신촌상사(70) 두 개뿐이어서 결과 테이블과 같다.","choices":[{"verdict":"정답","why":"LIKE '%신%'은 '신'이 포함된 대신공업사와 신촌상사만 골라 결과 테이블과 일치한다."},{"verdict":"오답","why":"LIKE '%대%'는 '대'가 포함된 대신공업사 한 행만 나온다. 신촌상사가 빠진다."},{"verdict":"오답","why":"LIKE '%사%'는 다섯 공급자명 모두 '사'를 포함하므로 다섯 행이 모두 나온다."},{"verdict":"오답","why":"IS NOT NULL은 공급자명이 비어 있지 않은 행을 모두 고르므로 다섯 행이 모두 나온다."}],"keywords":[{"term":"LIKE","desc":"문자열 패턴 비교 연산자"},{"term":"%","desc":"0개 이상의 임의 문자"},{"term":"_","desc":"임의의 문자 정확히 1개"},{"term":"IS NOT NULL","desc":"값이 NULL이 아닌 행 선택"}],"memo":"결과에 있는 행들에만 공통으로 있고 빠진 행들에는 없는 글자를 찾으면 된다."}},{"id":"written-2021-1-42","no":42,"unit":"데이터베이스 구축","q":"다음에서 설명하는 스키마(Schema)는?\n<img src=\"data/img/eip_written_20210307_042.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["개념 스키마","내부 스키마","외부 스키마","내용 스키마"],"ans":1,"rate":78,"wiki":[{"title":"스키마","url":"https://itwiki.kr/w/스키마"}],"exp":{"concept":"데이터베이스 스키마는 보는 관점에 따라 외부, 개념, 내부 세 단계로 나뉜다. 개념 스키마는 조직 전체 관점에서 데이터베이스 전체를 정의한 것으로, 데이터 개체, 관계, 제약 조건, 접근 권한, 무결성 규칙 등을 명세한다. 보통 그냥 '스키마'라고 하면 개념 스키마를 가리킨다.","choices":[{"verdict":"정답","why":"데이터베이스 전체를 정의하고 개체, 관계, 제약 조건, 접근 권한, 무결성 규칙을 명세한 것은 개념 스키마다."},{"verdict":"오답","why":"내부 스키마는 물리적 저장 장치 관점에서 레코드 형식, 인덱스, 저장 방식 등 실제 저장 구조를 정의한 것이다."},{"verdict":"오답","why":"외부 스키마는 개별 사용자나 응용 프로그램 관점에서 필요한 데이터만 정의한 것으로, 서브 스키마라고도 한다."},{"verdict":"오답","why":"내용 스키마는 3단계 스키마 구조에 없는 용어다."}],"keywords":[{"term":"외부 스키마","desc":"사용자·응용 프로그램 관점, 서브 스키마, 여러 개 존재"},{"term":"개념 스키마","desc":"조직 전체 관점의 DB 전체 정의, 하나만 존재"},{"term":"내부 스키마","desc":"물리적 저장 관점, 레코드 형식·인덱스·저장 방법"}],"memo":"'전체'가 나오면 개념, '사용자'가 나오면 외부, '물리적 저장'이 나오면 내부."}},{"id":"written-2021-1-43","no":43,"unit":"데이터베이스 구축","q":"데이터베이스 설계 단계 중 저장 레코드 양식설계, 레코드 집중의 분석 및 설계, 접근 경로 설계와 관계되는 것은?","choices":["논리적 설계","요구 조건 분석","개념적 설계","물리적 설계"],"ans":4,"rate":58,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행한다. 물리적 설계는 논리 구조를 실제 저장 장치에 어떻게 저장할지 정하는 단계다. 저장 레코드 양식, 레코드 집중(클러스터링) 분석, 접근 경로와 인덱스 설계 등이 여기서 이루어진다.","choices":[{"verdict":"오답","why":"논리적 설계는 개념 모델을 특정 DBMS의 논리 구조(릴레이션 등)로 바꾸고 정규화와 트랜잭션 인터페이스를 설계하는 단계다."},{"verdict":"오답","why":"요구 조건 분석은 사용자의 요구를 수집·분석해 요구 조건 명세서를 작성하는 단계다."},{"verdict":"오답","why":"개념적 설계는 E-R 다이어그램 등으로 DBMS와 무관한 개념 스키마를 만드는 단계다."},{"verdict":"정답","why":"저장 레코드 양식 설계, 레코드 집중 분석·설계, 접근 경로 설계는 실제 저장 구조를 정하는 물리적 설계 단계의 작업이다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS 독립적"},{"term":"논리적 설계","desc":"DBMS에 맞는 논리 스키마 작성, 정규화"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로·인덱스 설계"}],"memo":"'저장', '접근 경로', '레코드 양식'처럼 실제 디스크 이야기가 나오면 물리적 설계."}},{"id":"written-2021-1-44","no":44,"unit":"데이터베이스 구축","q":"다음 릴레이션의 카디널리티와 차수가 옳게 나타낸 것은?\n<img src=\"data/img/eip_written_20210307_044.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["카디널리티 : 4, 차수 : 4","카디널리티 : 4, 차수 : 6","카디널리티 : 6, 차수 : 4","카디널리티 : 6, 차수 : 6"],"ans":2,"rate":76,"exp":{"concept":"릴레이션에서 카디널리티(Cardinality)는 튜플(행)의 개수이고, 차수(Degree)는 속성(열)의 개수다. 표의 데이터 행은 yuyu01, sykim10, kshan4, namsu52 네 개이므로 카디널리티는 4다. 열은 아이디, 성명, 나이, 등급, 적립금, 가입연도 여섯 개이므로 차수는 6이다.","choices":[{"verdict":"오답","why":"카디널리티 4는 맞지만 속성이 6개이므로 차수는 4가 아니라 6이다."},{"verdict":"정답","why":"튜플이 4개(카디널리티 4), 속성이 6개(차수 6)다."},{"verdict":"오답","why":"카디널리티와 차수를 서로 바꾸어 센 값이다."},{"verdict":"오답","why":"차수 6은 맞지만 튜플은 4개이므로 카디널리티는 6이 아니다."}],"keywords":[{"term":"카디널리티(Cardinality)","desc":"튜플(행)의 수, 기수"},{"term":"차수(Degree)","desc":"속성(열)의 수"},{"term":"튜플(Tuple)","desc":"릴레이션의 한 행"},{"term":"속성(Attribute)","desc":"릴레이션의 한 열"}],"memo":"제목 행(아이디, 성명, ...)은 튜플이 아니다. 데이터 행만 센다."}},{"id":"written-2021-1-45","no":45,"unit":"데이터베이스 구축","q":"다음과 같은 트랜잭션의 특성은?\n<img src=\"data/img/eip_written_20210307_045.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["원자성(atomicity)","일관성(consistency)","격리성(isolation)","영속성(durability)"],"ans":2,"rate":78,"wiki":[{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"},{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"exp":{"concept":"트랜잭션은 ACID 특성을 가져야 한다. 일관성(Consistency)은 트랜잭션이 성공적으로 끝나면 데이터베이스가 언제나 일관된 상태를 유지해야 한다는 성질이다. 시스템이 가진 고정 요소(규칙, 제약 조건)는 트랜잭션 수행 전과 후에 같아야 한다. 계좌 이체 전후에 두 계좌의 합계가 같아야 하는 것이 예다.","choices":[{"verdict":"오답","why":"원자성(Atomicity)은 트랜잭션의 연산이 모두 반영되거나 전혀 반영되지 않아야 한다는 성질(All or Nothing)이다."},{"verdict":"정답","why":"트랜잭션 수행 전과 후에 시스템의 고정 요소가 같아야 한다, 즉 일관된 상태를 유지해야 한다는 것은 일관성이다."},{"verdict":"오답","why":"격리성(Isolation)은 동시에 실행되는 트랜잭션들이 서로의 중간 결과에 끼어들 수 없다는 성질이다."},{"verdict":"오답","why":"영속성(Durability)은 성공적으로 완료된 트랜잭션의 결과는 장애가 나도 영구히 반영되어야 한다는 성질이다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"모두 반영되거나 전혀 반영되지 않음, Commit·Rollback"},{"term":"일관성(Consistency)","desc":"수행 전후 고정 요소가 같아 일관된 상태 유지"},{"term":"격리성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"영속성(Durability)","desc":"완료된 결과는 영구히 반영"}],"memo":"ACID. '전과 후가 같다'는 말이 나오면 Consistency(일관성)."}},{"id":"written-2021-1-46","no":46,"unit":"데이터베이스 구축","q":"병행제어의 로킹(Locking) 단위에 대한 설명으로 옳지 않은 것은?","choices":["데이터베이스, 파일, 레코드 등은 로킹 단위가 될 수 있다.","로킹 단위가 작아지면 로킹 오버헤드가 증가한다.","한꺼번에 로킹할 수 있는 단위를 로킹단위라고 한다.","로킹 단위가 작아지면 병행성 수준이 낮아진다."],"ans":4,"rate":76,"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"exp":{"concept":"로킹(Locking)은 한 트랜잭션이 쓰는 데이터를 다른 트랜잭션이 못 쓰게 잠그는 병행 제어 기법이다. 잠그는 단위(로킹 단위)는 데이터베이스, 파일, 레코드, 필드 등이 될 수 있다. 단위를 작게 잡으면 잠금 개수가 많아져 관리 부담(오버헤드)은 커지지만, 여러 트랜잭션이 동시에 일할 수 있어 병행성은 높아진다.","choices":[{"verdict":"오답","why":"데이터베이스, 파일, 레코드, 필드 등이 모두 로킹 단위가 될 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"로킹 단위가 작아지면 관리해야 할 잠금 수가 많아져 로킹 오버헤드가 증가한다. 맞는 설명이다."},{"verdict":"오답","why":"한꺼번에 로킹할 수 있는 데이터의 크기를 로킹 단위라고 한다. 맞는 설명이다."},{"verdict":"정답","why":"로킹 단위가 작아지면 동시에 접근할 수 있는 데이터가 많아져 병행성 수준은 높아진다. 낮아진다는 설명은 틀렸다."}],"keywords":[{"term":"로킹(Locking)","desc":"데이터를 잠가 다른 트랜잭션의 접근을 막는 병행 제어 기법"},{"term":"로킹 단위 작음","desc":"병행성 높음, 오버헤드 증가"},{"term":"로킹 단위 큼","desc":"병행성 낮음, 오버헤드 감소"}],"memo":"도서관에서 건물째 잠그면(단위 큼) 관리는 쉽지만 한 명만 쓰고, 책 한 권씩 잠그면(단위 작음) 관리는 힘들지만 여럿이 동시에 쓴다."}},{"id":"written-2021-1-47","no":47,"unit":"데이터베이스 구축","q":"뷰(VIEW)에 대한 설명으로 옳지 않은 것은?","choices":["DBA는 보안 측면에서 뷰를 활용할 수 있다.","뷰 위에 또 다른 뷰를 정의할 수 있다.","뷰에 대한 삽입, 갱신, 삭제 연산 시 제약사항이 따르지 않는다.","독립적인 인덱스를 가질 수 없다."],"ans":3,"rate":75,"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"exp":{"concept":"뷰(View)는 하나 이상의 기본 테이블에서 유도된, 실제 데이터를 따로 저장하지 않는 가상 테이블이다. 필요한 데이터만 보여 줄 수 있어 보안에 유리하고, 뷰 위에 또 다른 뷰를 만들 수도 있다. 하지만 실제 테이블이 아니므로 독립적인 인덱스를 가질 수 없고, 삽입·갱신·삭제 연산에 제약이 따른다.","choices":[{"verdict":"오답","why":"뷰로 사용자에게 필요한 열과 행만 보여 주어 나머지를 숨길 수 있으므로 DBA는 보안 측면에서 뷰를 활용한다. 맞는 설명이다."},{"verdict":"오답","why":"이미 정의된 뷰를 기반으로 또 다른 뷰를 정의할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"뷰는 가상 테이블이어서 기본 키 열이 빠졌거나 집계·조인으로 만든 뷰 등은 삽입·갱신·삭제가 제한된다. 제약이 따르지 않는다는 설명은 틀렸다."},{"verdict":"오답","why":"뷰는 실제 데이터를 저장하지 않는 가상 테이블이므로 독립적인 인덱스를 가질 수 없다. 맞는 설명이다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 독립성 제공, 보안, 사용자 데이터 관리 단순화"},{"term":"뷰의 단점","desc":"독립 인덱스 불가, 정의 변경 불가(삭제 후 재생성), 삽입·갱신·삭제 제약"},{"term":"CREATE VIEW / DROP VIEW","desc":"뷰 생성·삭제 명령, ALTER로 정의 변경 불가"}],"memo":"뷰는 '창문'이다. 창문으로 보이는 것만 볼 수 있고, 창문을 통해 안의 물건을 마음대로 바꾸기는 어렵다."}},{"id":"written-2021-1-48","no":48,"unit":"데이터베이스 구축","q":"다음 정의에서 말하는 기본 정규형은?\n<img src=\"data/img/eip_written_20210307_048.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["제1정규형(1NF)","제2정규형(2NF)","제3정규형(3NF)","보이스/코드 정규형(BCNF)"],"ans":1,"rate":83,"exp":{"concept":"정규화는 이상 현상을 없애기 위해 릴레이션을 단계적으로 나누는 과정이다. 제1정규형(1NF)은 릴레이션의 모든 도메인이 더 이상 나눌 수 없는 원자값(Atomic Value)만으로 되어 있는 상태다. 한 칸에 '사과, 배'처럼 여러 값이 들어 있으면 1NF가 아니다.","choices":[{"verdict":"정답","why":"모든 도메인이 원자값만으로 되어 있는 정규형은 제1정규형이다."},{"verdict":"오답","why":"제2정규형은 1NF이면서 기본 키가 아닌 모든 속성이 기본 키 전체에 완전 함수적 종속인 상태(부분 함수 종속 제거)다."},{"verdict":"오답","why":"제3정규형은 2NF이면서 기본 키가 아닌 속성들이 기본 키에 이행적 함수 종속을 갖지 않는 상태다."},{"verdict":"오답","why":"보이스/코드 정규형(BCNF)은 3NF이면서 모든 결정자가 후보 키인 상태다."}],"keywords":[{"term":"1NF","desc":"도메인이 원자값만으로 구성"},{"term":"2NF","desc":"부분 함수 종속 제거"},{"term":"3NF","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보 키가 아닌 것 제거"}],"memo":"'도부이결다조' (도메인 원자값 → 부분 종속 → 이행 종속 → 결정자 → 다치 종속 → 조인 종속). 원자값이면 1NF."}},{"id":"written-2021-1-49","no":49,"unit":"데이터베이스 구축","q":"릴레이션 R1에 속한 애튜리뷰트의 조합인 외래키를 변경하려면 이를 참조하고 있는 릴레이션 R2의 기본키도 변경해야 하는데 이를 무엇이라 하는가?","choices":["정보 무결성","고유 무결성","널 제약성","참조 무결성"],"ans":4,"rate":91,"wiki":[{"title":"무결성","url":"https://itwiki.kr/w/무결성"},{"title":"참조 무결성","url":"https://itwiki.kr/w/참조 무결성"}],"exp":{"concept":"참조 무결성은 외래 키 값이 참조하는 릴레이션의 기본 키 값으로 실제로 존재하거나 NULL이어야 한다는 규칙이다. 그래서 외래 키와 그것이 참조하는 기본 키는 서로 맞물려 있어, 한쪽을 바꿀 때 다른 쪽도 함께 맞춰 주어야 일관성이 지켜진다. 지문은 외래 키와 이를 참조하는 기본 키를 함께 변경해야 하는 제약을 묻고 있다.","choices":[{"verdict":"오답","why":"정보 무결성은 관계형 데이터베이스의 무결성 제약 조건 분류에서 쓰는 표준 용어가 아니다."},{"verdict":"오답","why":"고유 무결성은 특정 속성에 고유(UNIQUE) 조건이 지정되면 각 튜플의 그 속성 값이 서로 달라야 한다는 규칙으로, 외래 키와 기본 키의 관계와는 관계없다."},{"verdict":"오답","why":"널 제약성은 특정 속성 값에 NULL이 올 수 없게 하는 제약으로, 외래 키와 기본 키의 관계와는 관계없다."},{"verdict":"정답","why":"외래 키와 이를 참조하는 기본 키의 값이 서로 맞아야 한다는 제약이 참조 무결성이다."}],"keywords":[{"term":"개체 무결성","desc":"기본 키는 NULL이나 중복 값을 가질 수 없음"},{"term":"참조 무결성","desc":"외래 키 값은 참조 릴레이션의 기본 키 값이거나 NULL"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인에 속해야 함"},{"term":"외래 키(Foreign Key)","desc":"다른 릴레이션의 기본 키를 참조하는 속성"}],"memo":"외래 키 + 기본 키 이야기면 참조 무결성, 기본 키 혼자 NULL 금지 이야기면 개체 무결성."}},{"id":"written-2021-1-50","no":50,"unit":"데이터베이스 구축","q":"시스템 카탈로그에 대한 설명으로 틀린 것은?","choices":["시스템 카탈로그의 갱신은 무결성 유지를 위하여 SQL을 이용하여 사용자가 직접 갱신하여야 한다.","데이터베이스에 포함되는 데이터 객체에 대한 정의나 명세에 대한 정보를 유지관리한다.","DBMS가 스스로 생성하고 유지하는 데이터베이스 내의 특별한 테이블의 집합체이다.","카탈로그에 저장된 정보를 메타 데이터라고도 한다."],"ans":1,"rate":79,"wiki":[{"title":"시스템 카탈로그","url":"https://itwiki.kr/w/시스템 카탈로그"}],"exp":{"concept":"시스템 카탈로그는 DBMS가 스스로 만들고 관리하는, 데이터베이스 객체(테이블, 뷰, 인덱스, 사용자, 권한 등)에 대한 정보를 담은 특별한 테이블 모음이다. 여기에 저장된 정보는 '데이터에 관한 데이터'라서 메타 데이터라고 한다. 사용자가 SQL로 조회할 수는 있지만, 내용은 DBMS가 자동으로 갱신하며 사용자가 직접 갱신할 수 없다.","choices":[{"verdict":"정답","why":"시스템 카탈로그는 사용자가 CREATE, ALTER 등을 실행하면 DBMS가 자동으로 갱신한다. 사용자가 SQL로 직접 갱신해야 한다는 설명은 틀렸다."},{"verdict":"오답","why":"데이터베이스에 포함된 데이터 객체의 정의와 명세 정보를 유지·관리한다. 맞는 설명이다."},{"verdict":"오답","why":"DBMS가 스스로 생성하고 유지하는 데이터베이스 안의 특별한 테이블들의 집합이다. 맞는 설명이다."},{"verdict":"오답","why":"카탈로그에 저장된 정보는 데이터에 관한 데이터이므로 메타 데이터(Meta-Data)라고 한다. 맞는 설명이다."}],"keywords":[{"term":"시스템 카탈로그(System Catalog)","desc":"DB 객체 정보를 담은 시스템 테이블, DBMS가 자동 갱신"},{"term":"메타 데이터(Meta-Data)","desc":"데이터에 관한 데이터, 카탈로그에 저장된 정보"},{"term":"데이터 사전(Data Dictionary)","desc":"시스템 카탈로그와 같은 의미로 쓰임"}],"memo":"카탈로그는 사용자가 '조회'는 할 수 있지만 '갱신'은 DBMS만 한다."}},{"id":"written-2021-1-51","no":51,"unit":"데이터베이스 구축","q":"조건을 만족하는 릴레이션의 수평적 부분집합으로 구성하며, 연산자의 기호는 그리스 문자 시그마(σ)를 사용하는 관계대수 연산은?","choices":["Select","Project","Join","Division"],"ans":1,"rate":65,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계대수의 Select 연산은 조건을 만족하는 튜플(행)만 골라내는 연산으로, 기호는 시그마(σ)다. 표를 가로로 잘라 일부 행만 남기므로 수평적 부분집합이라고 한다. 반대로 Project 연산(π)은 필요한 속성(열)만 골라 세로로 자르는 수직적 부분집합이다.","choices":[{"verdict":"정답","why":"조건을 만족하는 튜플을 골라 수평적 부분집합을 만드는 연산은 Select이며, 기호는 σ(시그마)다."},{"verdict":"오답","why":"Project는 지정한 속성(열)만 추출하는 수직적 부분집합 연산이며, 기호는 π(파이)다."},{"verdict":"오답","why":"Join은 공통 속성을 기준으로 두 릴레이션을 하나로 합치는 연산이며, 기호는 ⋈다."},{"verdict":"오답","why":"Division은 한 릴레이션이 다른 릴레이션의 모든 튜플과 관련된 튜플만 골라내는 연산이며, 기호는 ÷다."}],"keywords":[{"term":"Select(σ)","desc":"조건에 맞는 튜플 선택, 수평적 부분집합"},{"term":"Project(π)","desc":"지정한 속성만 추출, 수직적 부분집합"},{"term":"Join(⋈)","desc":"공통 속성으로 두 릴레이션 결합"},{"term":"Division(÷)","desc":"다른 릴레이션의 모든 튜플과 관련된 튜플 추출"}],"memo":"σ는 '선택(Select)'의 s, π는 'Project'의 p. 행은 수평, 열은 수직."}},{"id":"written-2021-1-52","no":52,"unit":"데이터베이스 구축","q":"SQL에서 스키마(schema), 도메인(domain), 테이블(table), 뷰(view), 인덱스(index)를 정의하거나 변경 또는 삭제할 때 사용하는 언어는?","choices":["DML(Data Manipulation Language)","DDL(Data Definition Language)","DCL(Data Control Language)","IDL(Interactive Data Language)"],"ans":2,"rate":72,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"SQL은 쓰임새에 따라 세 가지로 나뉜다. DDL(데이터 정의어)은 스키마, 도메인, 테이블, 뷰, 인덱스 같은 구조를 만들고(CREATE) 바꾸고(ALTER) 없앤다(DROP). DML은 데이터 자체를 조회·삽입·수정·삭제하고, DCL은 권한과 트랜잭션을 제어한다.","choices":[{"verdict":"오답","why":"DML(데이터 조작어)은 SELECT, INSERT, UPDATE, DELETE로 테이블 안의 데이터를 다룬다. 구조를 정의하지 않는다."},{"verdict":"정답","why":"스키마, 도메인, 테이블, 뷰, 인덱스를 정의·변경·삭제하는 언어는 DDL(데이터 정의어)이며 CREATE, ALTER, DROP 등이 있다."},{"verdict":"오답","why":"DCL(데이터 제어어)은 GRANT, REVOKE, COMMIT, ROLLBACK 등으로 권한과 트랜잭션을 제어한다."},{"verdict":"오답","why":"IDL은 SQL 언어 분류(DDL, DML, DCL)에 속하지 않는다."}],"keywords":[{"term":"DDL(Data Definition Language)","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML(Data Manipulation Language)","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL(Data Control Language)","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"Definition은 그릇(구조)을 만들고, Manipulation은 그릇 속 내용물을 다루고, Control은 누가 쓸지 정한다."}},{"id":"written-2021-1-53","no":53,"unit":"데이터베이스 구축","q":"정규화를 거치지 않아 발생하게 되는 이상(anomaly) 현상의 종류에 대한 설명으로 옳지 않은 것은?","choices":["삭제 이상이란 릴레이션에서 한 튜플을 삭제할 때 의도와는 상관없는 값들도 함께 삭제되는 연쇄 삭제 현상이다.","삽입 이상이란 릴레이션에서 데이터를 삽입할 때 의도와는 상관없이 원하지 않는 값들도 함께 삽입되는 현상이다.","갱신 이상이란 릴레이션에서 튜플에 있는 속성값을 갱신할 때 일부 튜플의 정보만 갱신되어 정보에 모순이 생기는 현상이다.","종속 이상이란 하나의 릴레이션에 하나 이상의 함수적 종속성이 존재하는 현상이다."],"ans":4,"rate":67,"exp":{"concept":"정규화가 안 된 릴레이션에서는 데이터 중복 때문에 이상(Anomaly) 현상이 생긴다. 이상 현상은 삽입 이상, 삭제 이상, 갱신 이상 세 가지다. 함수적 종속이 존재하는 것 자체는 이상 현상이 아니며, '종속 이상'이라는 종류는 없다.","choices":[{"verdict":"오답","why":"삭제 이상은 한 튜플을 삭제할 때 의도하지 않은 다른 정보까지 함께 삭제되는 연쇄 삭제 현상이다. 맞는 설명이다."},{"verdict":"오답","why":"삽입 이상은 데이터를 삽입할 때 원하지 않는 값까지 함께 넣어야 하거나, 그렇지 않으면 삽입할 수 없는 현상이다. 맞는 설명이다."},{"verdict":"오답","why":"갱신 이상은 중복된 튜플 중 일부만 갱신되어 정보에 모순이 생기는 현상이다. 맞는 설명이다."},{"verdict":"정답","why":"이상 현상은 삽입·삭제·갱신 이상 세 가지뿐이다. 함수적 종속성이 존재하는 것은 이상 현상이 아니며, 종속 이상이라는 종류는 없다."}],"keywords":[{"term":"삽입 이상","desc":"원하지 않는 값도 함께 넣어야 삽입 가능"},{"term":"삭제 이상","desc":"튜플 삭제 시 필요한 정보까지 연쇄 삭제"},{"term":"갱신 이상","desc":"일부 튜플만 갱신되어 데이터 불일치"},{"term":"정규화(Normalization)","desc":"이상 현상을 없애기 위해 릴레이션을 분해하는 과정"}],"memo":"이상 현상은 '삽삭갱' 세 개뿐. 다른 이름이 보이면 틀린 보기다."}},{"id":"written-2021-1-54","no":54,"unit":"데이터베이스 구축","q":"관계 데이터 모델에서 릴레이션(relation)에 관한 설명으로 옳은 것은?","choices":["릴레이션의 각 행을 스키마(schema)라 하며, 예로 도서 릴레이션을 구성하는 스키마에서는 도서번호, 도서명, 저자, 가격 등이 있다.","릴레이션의 각 열을 튜플(tuple)이라 하며, 하나의 튜플은 각 속성에서 정의된 값을 이용하여 구성된다.","도메인(domain)은 하나의 속성이 가질 수 있는 같은 타입의 모든 값의 집합으로 각 속성의 도메인은 원자값을 갖는다.","속성(attribute)은 한 개의 릴레이션의 논리적인 구조를 정의한 것으로 릴레이션의 이름과 릴레이션에 포함된 속성들의 집합을 의미한다."],"ans":3,"rate":59,"exp":{"concept":"릴레이션은 표 형태로, 행 하나를 튜플, 열 하나를 속성(애트리뷰트)이라고 한다. 도메인은 하나의 속성이 가질 수 있는 같은 타입의 원자값들의 집합이다. 릴레이션의 이름과 속성들의 집합으로 논리 구조를 정의한 것은 릴레이션 스키마라고 한다.","choices":[{"verdict":"오답","why":"릴레이션의 각 행은 튜플이다. 도서번호, 도서명, 저자, 가격은 열인 속성이며, 스키마는 이 속성들로 릴레이션 구조를 정의한 것이다."},{"verdict":"오답","why":"릴레이션의 각 열은 속성이다. 튜플은 각 속성 값들로 구성된 행이다."},{"verdict":"정답","why":"도메인은 하나의 속성이 가질 수 있는 같은 타입의 모든 값의 집합이며, 각 값은 원자값이다."},{"verdict":"오답","why":"릴레이션의 이름과 속성들의 집합으로 논리 구조를 정의한 것은 릴레이션 스키마다. 속성은 릴레이션의 열 하나를 뜻한다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행, 개수는 카디널리티"},{"term":"속성(Attribute)","desc":"릴레이션의 열, 개수는 차수"},{"term":"도메인(Domain)","desc":"한 속성이 가질 수 있는 원자값들의 집합"},{"term":"릴레이션 스키마","desc":"릴레이션 이름과 속성들의 집합으로 정의한 구조"}],"memo":"행=튜플, 열=속성, 열에 올 수 있는 값의 범위=도메인, 표의 틀=스키마."}},{"id":"written-2021-1-55","no":55,"unit":"데이터베이스 구축","q":"3NF에서 BCNF가 되기 위한 조건은?","choices":["이행적 함수 종속 제거","부분적 함수 종속 제거","다치 종속 제거","결정자이면서 후보 키가 아닌 것 제거"],"ans":4,"rate":72,"exp":{"concept":"BCNF(보이스/코드 정규형)는 3NF보다 강한 정규형으로, 모든 결정자가 후보 키여야 한다. 3NF를 만족해도 후보 키가 아닌 속성이 다른 속성을 결정하는 경우가 남을 수 있는데, 이를 없애면 BCNF가 된다. 결정자란 함수적 종속 X → Y에서 Y를 결정하는 X를 말한다.","choices":[{"verdict":"오답","why":"이행적 함수 종속 제거는 2NF에서 3NF로 가는 조건이다."},{"verdict":"오답","why":"부분적 함수 종속 제거는 1NF에서 2NF로 가는 조건이다."},{"verdict":"오답","why":"다치 종속 제거는 BCNF에서 4NF로 가는 조건이다."},{"verdict":"정답","why":"결정자이면서 후보 키가 아닌 것을 제거해 모든 결정자를 후보 키로 만드는 것이 3NF에서 BCNF로 가는 조건이다."}],"keywords":[{"term":"결정자(Determinant)","desc":"X → Y에서 Y를 결정하는 X"},{"term":"후보 키(Candidate Key)","desc":"유일성과 최소성을 만족하는 키"},{"term":"BCNF","desc":"모든 결정자가 후보 키인 정규형"},{"term":"4NF","desc":"다치 종속 제거"}],"memo":"도부이결다조: 도메인 원자값(1) → 부분 종속(2) → 이행 종속(3) → 결정자(BCNF) → 다치(4) → 조인(5)."}},{"id":"written-2021-1-56","no":56,"unit":"데이터베이스 구축","q":"데이터베이스 성능에 많은 영향을 주는 DBMS의 구성 요소로 테이블과 클러스터에 연관되어 독립적인 저장 공간을 보유하며, 데이터베이스에 저장된 자료를 더욱 빠르게 조회하기 위하여 사용되는 것은?","choices":["인덱스(Index)","트랜잭션(Transaction)","역정규화(Denormalization)","트리거(Trigger)"],"ans":1,"rate":77,"exp":{"concept":"인덱스(Index)는 책 뒤의 찾아보기처럼, 키 값과 그 데이터가 저장된 위치를 정리해 둔 별도의 구조다. 테이블과 별개로 독립된 저장 공간을 가지며, 전체 테이블을 처음부터 훑지 않고 원하는 행을 빠르게 찾게 해 준다. 그래서 데이터베이스 성능에 큰 영향을 준다.","choices":[{"verdict":"정답","why":"테이블·클러스터와 연관된 독립 저장 공간을 가지고 조회 속도를 높이기 위해 쓰는 것은 인덱스다."},{"verdict":"오답","why":"트랜잭션(Transaction)은 데이터베이스 상태를 바꾸는 하나의 논리적 작업 단위다."},{"verdict":"오답","why":"역정규화(Denormalization)는 성능을 위해 정규화된 테이블을 일부러 다시 합치거나 중복을 허용하는 설계 기법으로, 독립된 저장 공간을 가진 DBMS 구성 요소가 아니다."},{"verdict":"오답","why":"트리거(Trigger)는 삽입·갱신·삭제 같은 이벤트가 발생할 때 자동으로 실행되는 프로시저다."}],"keywords":[{"term":"인덱스(Index)","desc":"키 값과 위치를 저장해 검색 속도를 높이는 구조"},{"term":"클러스터드 인덱스","desc":"인덱스 순서와 실제 데이터 저장 순서가 같은 인덱스"},{"term":"트리거(Trigger)","desc":"이벤트 발생 시 자동 실행되는 프로시저"},{"term":"역정규화(Denormalization)","desc":"성능 향상을 위해 중복을 허용하는 설계"}],"memo":"'더 빠르게 조회'와 '독립적인 저장 공간'이 함께 나오면 인덱스."}},{"id":"written-2021-1-57","no":57,"unit":"데이터베이스 구축","q":"아래의 SQL문을 실행한 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<div class=\"q-tbl-title\">[R1 테이블]</div><table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>이름</th><th>학년</th><th>학과</th><th>주소</th></tr></thead><tbody><tr><td>1000</td><td>홍길동</td><td>4</td><td>컴퓨터</td><td>서울</td></tr><tr><td>2000</td><td>김철수</td><td>3</td><td>전기</td><td>경기</td></tr><tr><td>3000</td><td>강남길</td><td>1</td><td>컴퓨터</td><td>경기</td></tr><tr><td>4000</td><td>오말자</td><td>4</td><td>컴퓨터</td><td>경기</td></tr><tr><td>5000</td><td>장미화</td><td>2</td><td>전자</td><td>서울</td></tr></tbody></table>\n<div class=\"q-tbl-title\">[R2 테이블]</div><table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>과목번호</th><th>학점</th><th>점수</th></tr></thead><tbody><tr><td>1000</td><td>C100</td><td>A</td><td>91</td></tr><tr><td>1000</td><td>C200</td><td>A</td><td>94</td></tr><tr><td>2000</td><td>C300</td><td>B</td><td>85</td></tr><tr><td>3000</td><td>C400</td><td>A</td><td>90</td></tr><tr><td>3000</td><td>C500</td><td>C</td><td>75</td></tr><tr><td>3000</td><td>C100</td><td>A</td><td>90</td></tr><tr><td>4000</td><td>C400</td><td>A</td><td>95</td></tr><tr><td>4000</td><td>C500</td><td>A</td><td>91</td></tr><tr><td>4000</td><td>C100</td><td>B</td><td>80</td></tr><tr><td>4000</td><td>C200</td><td>C</td><td>74</td></tr><tr><td>5000</td><td>C400</td><td>B</td><td>85</td></tr></tbody></table>\n<pre class=\"q-sql\"><code class=\"language-sql\">SELECT 이름\nFROM R1\nWHERE 학번 IN\n    (SELECT 학번\n     FROM R2\n     WHERE 과목번호 = 'C100');</code></pre>\n</div>","choices":["<table class=\"q-tbl is-data\"><thead><tr><th>이름</th></tr></thead><tbody><tr><td>홍길동</td></tr><tr><td>강남길</td></tr><tr><td>장미화</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>이름</th></tr></thead><tbody><tr><td>홍길동</td></tr><tr><td>강남길</td></tr><tr><td>오말자</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>이름</th></tr></thead><tbody><tr><td>홍길동</td></tr><tr><td>김철수</td></tr><tr><td>강남길</td></tr><tr><td>오말자</td></tr><tr><td>장미화</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>이름</th></tr></thead><tbody><tr><td>홍길동</td></tr><tr><td>김철수</td></tr></tbody></table>"],"ans":2,"rate":93,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"IN 뒤의 하위 질의가 먼저 실행되어 학번 목록을 만들고, 바깥 질의는 그 목록에 들어 있는 학번의 이름만 고른다. R2에서 과목번호가 'C100'인 행은 학번 1000(A, 91), 3000(A, 90), 4000(B, 80) 세 개다. 따라서 R1에서 학번이 1000, 3000, 4000인 홍길동, 강남길, 오말자가 출력된다.","choices":[{"verdict":"오답","why":"장미화(5000)는 C400만 수강했고 C100 수강 기록이 없다. 대신 C100을 수강한 오말자(4000)가 빠졌다."},{"verdict":"정답","why":"C100을 수강한 학번은 1000, 3000, 4000이고, 이에 해당하는 이름은 홍길동, 강남길, 오말자다."},{"verdict":"오답","why":"R1의 모든 학생이 나온 결과다. 하위 질의의 조건(과목번호 = 'C100')을 무시한 것이다."},{"verdict":"오답","why":"김철수(2000)는 C300만 수강해 C100 수강 기록이 없고, 강남길과 오말자가 빠졌다."}],"keywords":[{"term":"하위 질의(Subquery)","desc":"다른 질의 안에 들어 있는 SELECT 문"},{"term":"IN","desc":"값이 목록 안의 어느 하나와 같으면 참"},{"term":"WHERE","desc":"조건에 맞는 행만 선택"}],"memo":"하위 질의 먼저 풀어 목록을 적어 두고, 바깥 질의에 대입한다. 'C100' 행을 R2에서 빠짐없이 찾는 것이 핵심이다."}},{"id":"written-2021-1-58","no":58,"unit":"데이터베이스 구축","q":"『회원』테이블 생성 후 『주소』 필드(컬럼)가 누락되어 이를 추가하려고 한다. 이에 적합한 SQL명령어는?","choices":["DELETE","RESTORE","ALTER","ACCESS"],"ans":3,"rate":91,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"이미 만든 테이블의 구조(열 추가, 변경, 삭제)를 바꿀 때는 DDL 명령인 ALTER TABLE을 쓴다. 회원 테이블에 주소 열을 추가하려면 ALTER TABLE 회원 ADD 주소 VARCHAR(100);처럼 작성한다. 행(데이터)을 지우는 DELETE와 헷갈리지 않아야 한다.","choices":[{"verdict":"오답","why":"DELETE는 테이블의 행(데이터)을 삭제하는 DML 명령이다. 열을 추가할 수 없다."},{"verdict":"오답","why":"RESTORE는 SQL 표준 명령어가 아니며, 테이블에 열을 추가하는 명령이 아니다."},{"verdict":"정답","why":"ALTER는 테이블의 구조를 변경하는 DDL 명령으로, ALTER TABLE ... ADD로 누락된 열을 추가한다."},{"verdict":"오답","why":"ACCESS는 SQL 명령어가 아니다."}],"keywords":[{"term":"ALTER TABLE ADD","desc":"새 열 추가"},{"term":"ALTER TABLE MODIFY/ALTER","desc":"열의 정의 변경"},{"term":"ALTER TABLE DROP","desc":"열 삭제"},{"term":"DELETE","desc":"테이블의 행 삭제(DML)"}],"memo":"구조(열)를 고치면 ALTER, 데이터(행)를 지우면 DELETE."}},{"id":"written-2021-1-59","no":59,"unit":"데이터베이스 구축","q":"트랜잭션을 수행하는 도중 장애로 인해 손상된 데이터베이스를 손상되기 이전에 정상적인 상태로 복구시키는 작업은?","choices":["Recovery","Commit","Abort","Restart"],"ans":1,"rate":85,"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"}],"exp":{"concept":"회복(Recovery)은 트랜잭션 수행 중 장애가 일어나 손상된 데이터베이스를 장애 이전의 정상 상태로 되돌리는 작업이다. 로그와 백업을 이용해 완료된 작업은 다시 반영(Redo)하고 미완료 작업은 취소(Undo)한다. 게임에서 저장해 둔 지점으로 되돌아가는 것과 비슷하다.","choices":[{"verdict":"정답","why":"장애로 손상된 데이터베이스를 손상 이전의 정상 상태로 복구하는 작업은 회복(Recovery)이다."},{"verdict":"오답","why":"Commit은 트랜잭션이 성공적으로 끝났을 때 변경 내용을 데이터베이스에 영구 반영하는 연산이다."},{"verdict":"오답","why":"Abort는 트랜잭션이 비정상적으로 종료되어 롤백된 상태를 말한다."},{"verdict":"오답","why":"Restart는 철회(Abort)된 트랜잭션을 다시 시작하는 것을 말하며, 손상된 데이터베이스를 복구하는 작업 자체를 가리키지 않는다."}],"keywords":[{"term":"회복(Recovery)","desc":"장애 발생 전 정상 상태로 복구"},{"term":"Redo","desc":"로그를 보고 완료된 변경을 다시 반영"},{"term":"Undo","desc":"로그를 보고 미완료 변경을 취소"},{"term":"Commit / Rollback","desc":"변경 확정 / 변경 취소"}],"memo":"장애 뒤 정상 상태로 '되돌리는' 작업은 Recovery(회복), 변경 '확정'은 Commit, 트랜잭션 '철회'는 Abort로 구분한다."}},{"id":"written-2021-1-60","no":60,"unit":"데이터베이스 구축","q":"E-R 다이어그램의 표기법으로 옳지 않은 것은?","choices":["개체타입 - 사각형","속성 - 타원","관계집합 - 삼각형","개체타입과 속성을 연결 – 선"],"ans":3,"rate":84,"wiki":[{"title":"ER 다이어그램","url":"https://itwiki.kr/w/ER 다이어그램"}],"exp":{"concept":"E-R 다이어그램은 개체(Entity), 속성(Attribute), 관계(Relationship)를 도형으로 그린다. 개체 타입은 사각형, 속성은 타원, 관계 타입은 마름모로 표시하고, 이들을 선으로 연결한다. 기본 키 속성은 타원 안 이름에 밑줄을 긋는다.","choices":[{"verdict":"오답","why":"개체 타입은 사각형으로 표시한다. 맞는 표기다."},{"verdict":"오답","why":"속성은 타원으로 표시한다. 맞는 표기다."},{"verdict":"정답","why":"관계 집합(관계 타입)은 마름모로 표시한다. 삼각형이 아니다."},{"verdict":"오답","why":"개체 타입과 속성, 개체 타입과 관계는 선(링크)으로 연결한다. 맞는 표기다."}],"keywords":[{"term":"사각형","desc":"개체 타입"},{"term":"마름모","desc":"관계 타입"},{"term":"타원","desc":"속성 (밑줄 타원은 기본 키 속성)"},{"term":"이중 타원","desc":"다중값 속성"}],"memo":"개체는 네모, 관계는 마름모, 속성은 동그라미. 세모는 없다."}},{"id":"written-2021-1-61","no":61,"unit":"프로그래밍 언어 활용","q":"다음 중 응집도가 가장 높은 것은?","choices":["절차적 응집도","순차적 응집도","우연적 응집도","논리적 응집도"],"ans":2,"rate":59,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도는 모듈 안의 요소들이 하나의 목적으로 얼마나 잘 뭉쳐 있는지를 나타내며, 높을수록 좋다. 높은 것부터 기능적 > 순차적 > 교환(통신)적 > 절차적 > 시간적 > 논리적 > 우연적 응집도 순이다. 보기 중에서는 순차적 응집도가 가장 높다.","choices":[{"verdict":"오답","why":"절차적 응집도는 모듈 안의 요소들이 정해진 순서대로 수행되는 경우로, 순차적·교환적 응집도보다 낮다."},{"verdict":"정답","why":"순차적 응집도는 한 활동의 출력이 다음 활동의 입력으로 쓰이는 경우로, 보기 중 가장 높다(기능적 응집도 바로 다음)."},{"verdict":"오답","why":"우연적 응집도는 서로 관련 없는 요소들이 우연히 한 모듈에 모인 경우로, 응집도가 가장 낮다."},{"verdict":"오답","why":"논리적 응집도는 비슷한 성격의 처리들을 한 모듈에 모아 놓은 경우로, 우연적 응집도 다음으로 낮다."}],"keywords":[{"term":"기능적 응집도","desc":"모듈 내부 요소가 하나의 기능만 수행, 가장 높음"},{"term":"순차적 응집도","desc":"한 활동의 출력이 다음 활동의 입력"},{"term":"교환(통신)적 응집도","desc":"같은 입력·출력을 사용하는 서로 다른 기능을 모음"},{"term":"우연적 응집도","desc":"서로 관련 없는 요소의 모임, 가장 낮음"}],"memo":"높은 순서 '기순교절시논우' (기능-순차-교환-절차-시간-논리-우연)."}},{"id":"written-2021-1-62","no":62,"unit":"프로그래밍 언어 활용","q":"OSI 7계층에서 물리적 연결을 이용해 신뢰성 있는 정보를 전송하려고 동기화, 오류제어, 흐름제어 등의 전송에러를 제어하는 계층은?","choices":["데이터 링크 계층","물리 계층","응용 계층","표현 계층"],"ans":1,"rate":69,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"OSI 7계층의 데이터 링크 계층(2계층)은 물리 계층이 만든 연결을 이용해 이웃한 노드 사이에 데이터를 신뢰성 있게 전달한다. 이를 위해 프레임 단위로 데이터를 묶고, 동기화, 오류 제어, 흐름 제어를 수행한다. 물리 계층은 비트를 전기 신호로 보내는 일만 한다.","choices":[{"verdict":"정답","why":"물리적 연결을 이용해 신뢰성 있는 전송을 하도록 동기화, 오류 제어, 흐름 제어를 하는 계층은 데이터 링크 계층이다."},{"verdict":"오답","why":"물리 계층은 전송 매체를 통해 비트 신호를 전송하는 전기적·기계적 특성을 다룬다. 오류·흐름 제어를 하지 않는다."},{"verdict":"오답","why":"응용 계층은 사용자가 네트워크 서비스(HTTP, FTP 등)를 이용할 수 있게 해 주는 최상위 계층이다."},{"verdict":"오답","why":"표현 계층은 데이터의 형식 변환, 암호화, 압축을 담당하는 계층이다."}],"keywords":[{"term":"물리 계층(1)","desc":"비트 전송, 전기적·기계적 특성"},{"term":"데이터 링크 계층(2)","desc":"프레임, 동기화·오류 제어·흐름 제어, 인접 노드 간 전송"},{"term":"네트워크 계층(3)","desc":"패킷, 경로 설정(라우팅)"},{"term":"전송 계층(4)","desc":"종단 간 신뢰성 있는 전송, TCP·UDP"}],"memo":"'물리적 연결을 이용해' 신뢰성을 더한다 = 물리 계층 바로 위의 데이터 링크 계층."}},{"id":"written-2021-1-63","no":63,"unit":"프로그래밍 언어 활용","q":"운영체제를 기능에 따라 분류할 경우 제어 프로그램이 아닌 것은?","choices":["데이터 관리 프로그램","서비스 프로그램","작업 제어 프로그램","감시 프로그램"],"ans":2,"rate":61,"wiki":[{"title":"운영체제","url":"https://itwiki.kr/w/운영체제"}],"exp":{"concept":"운영체제는 기능에 따라 제어 프로그램과 처리 프로그램으로 나뉜다. 제어 프로그램은 시스템 전체를 감시하고 관리하는 프로그램으로 감시 프로그램, 작업 제어 프로그램, 데이터 관리 프로그램이 있다. 처리 프로그램은 실제 작업을 처리하는 프로그램으로 언어 번역 프로그램, 서비스 프로그램, 문제 처리 프로그램이 있다.","choices":[{"verdict":"오답","why":"데이터 관리 프로그램은 주기억장치와 보조기억장치 사이의 데이터 전송, 파일과 데이터 처리를 관리하는 제어 프로그램이다."},{"verdict":"정답","why":"서비스 프로그램은 사용자가 자주 쓰는 기능(정렬, 병합 등)을 미리 만들어 둔 처리 프로그램이다. 제어 프로그램이 아니다."},{"verdict":"오답","why":"작업 제어 프로그램은 작업의 연속 처리를 위한 스케줄 및 시스템 자원 할당 등을 담당하는 제어 프로그램이다."},{"verdict":"오답","why":"감시 프로그램(Supervisor)은 각종 프로그램의 실행과 시스템 전체의 작동 상태를 감시·감독하는 제어 프로그램이다."}],"keywords":[{"term":"제어 프로그램","desc":"감시 프로그램, 작업 제어 프로그램, 데이터 관리 프로그램"},{"term":"처리 프로그램","desc":"언어 번역 프로그램, 서비스 프로그램, 문제 처리 프로그램"},{"term":"감시 프로그램(Supervisor)","desc":"제어 프로그램 중 핵심, 시스템 작동 상태 감시"}],"memo":"제어 프로그램은 '감작데'(감시·작업 제어·데이터 관리). 서비스·언어 번역·문제 처리는 처리 프로그램."}},{"id":"written-2021-1-64","no":64,"unit":"프로그래밍 언어 활용","q":"IEEE 802.3 LAN에서 사용되는 전송매체 접속제어(MAC) 방식은?","choices":["CSMA/CD","Token Bus","Token Ring","Slotted Ring"],"ans":1,"rate":62,"wiki":[{"title":"IEEE 802","url":"https://itwiki.kr/w/IEEE 802"},{"title":"CSMA/CD","url":"https://itwiki.kr/w/CSMA/CD"}],"exp":{"concept":"IEEE 802.3은 이더넷(Ethernet) 유선 LAN 표준이고, 매체 접근 제어 방식으로 CSMA/CD를 쓴다. CSMA/CD는 전송 전에 회선이 비어 있는지 확인하고(반송파 감지), 보내는 중 충돌이 감지되면 전송을 멈추고 임의 시간 기다렸다가 다시 보낸다. 여러 사람이 한 방에서 대화하다 동시에 말하면 잠깐 멈췄다가 다시 말하는 것과 같다.","choices":[{"verdict":"정답","why":"IEEE 802.3(이더넷)의 매체 접근 제어 방식은 CSMA/CD(Carrier Sense Multiple Access with Collision Detection)다."},{"verdict":"오답","why":"토큰 버스(Token Bus)는 IEEE 802.4 표준의 방식이다."},{"verdict":"오답","why":"토큰 링(Token Ring)은 IEEE 802.5 표준의 방식이다."},{"verdict":"오답","why":"슬롯 링(Slotted Ring)은 링을 도는 고정 길이 슬롯에 데이터를 실어 보내는 방식으로, IEEE 802.3의 접근 방식이 아니다."}],"keywords":[{"term":"IEEE 802.3","desc":"이더넷, CSMA/CD"},{"term":"IEEE 802.4","desc":"토큰 버스"},{"term":"IEEE 802.5","desc":"토큰 링"},{"term":"IEEE 802.11","desc":"무선 LAN, CSMA/CA"}],"memo":"802.3 → 3 → CD(Collision Detection, 유선), 802.11 → 무선 → CA(Collision Avoidance)."}},{"id":"written-2021-1-65","no":65,"unit":"프로그래밍 언어 활용","q":"기억공간이 15K, 23K, 22K, 21K 순으로 빈 공간이 있을 때 기억장치 배치 전력으로 “First Fit”을 사용하여 17K의 프로그램을 적재할 경우 내부단편화의 크기는 얼마인가?","choices":["5K","6K","7K","8K"],"ans":2,"rate":80,"exp":{"concept":"최초 적합(First Fit)은 빈 공간을 앞에서부터 차례로 보다가 프로그램이 들어갈 수 있는 첫 번째 공간에 바로 넣는 배치 전략이다. 17K 프로그램은 15K에는 들어가지 않고, 두 번째인 23K에 처음으로 들어간다. 23K 공간에 17K를 넣으면 23 - 17 = 6K가 쓰이지 않고 남는데, 이것이 내부 단편화다.","choices":[{"verdict":"오답","why":"5K는 First Fit으로 고른 23K 공간의 남는 크기(6K)와 다르다. 22K에 넣었을 때의 값이며, 22K는 First Fit의 선택이 아니다."},{"verdict":"정답","why":"17K가 들어가는 첫 공간은 23K이므로 내부 단편화는 23K - 17K = 6K다."},{"verdict":"오답","why":"7K는 계산 결과(6K)와 맞지 않는다."},{"verdict":"오답","why":"8K는 계산 결과(6K)와 맞지 않는다."}],"keywords":[{"term":"최초 적합(First Fit)","desc":"들어갈 수 있는 첫 번째 빈 공간에 배치"},{"term":"최적 적합(Best Fit)","desc":"단편화가 가장 작게 남는 공간에 배치"},{"term":"최악 적합(Worst Fit)","desc":"단편화가 가장 크게 남는 공간에 배치"},{"term":"내부 단편화","desc":"할당된 공간이 프로그램보다 커서 안에 남는 빈 공간"}],"memo":"First는 '처음 들어가는 곳', 크기 비교 없이 앞에서부터 본다. 같은 문제에서 Best Fit이면 21K(4K 남음), Worst Fit이면 23K(6K 남음)."}},{"id":"written-2021-1-66","no":66,"unit":"프로그래밍 언어 활용","q":"교착상태가 발생할 수 있는 조건이 아닌 것은?","choices":["Mutual exclusion","Hold and wait","Non-preemption","Linear wait"],"ans":4,"rate":56,"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"exp":{"concept":"교착 상태(Deadlock)는 여러 프로세스가 서로 상대가 가진 자원을 기다리며 영원히 멈춰 버리는 상태다. 상호 배제, 점유와 대기, 비선점, 환형 대기 네 가지 조건이 동시에 성립할 때 발생할 수 있다. 네 명이 원탁에 앉아 각자 오른쪽 사람의 젓가락을 기다리는 모습을 떠올리면 된다.","choices":[{"verdict":"오답","why":"상호 배제(Mutual Exclusion)는 한 자원을 한 번에 한 프로세스만 쓸 수 있다는 조건으로, 교착 상태의 발생 조건이다."},{"verdict":"오답","why":"점유와 대기(Hold and Wait)는 자원을 가진 채로 다른 자원을 기다리는 조건으로, 교착 상태의 발생 조건이다."},{"verdict":"오답","why":"비선점(Non-preemption)은 다른 프로세스가 가진 자원을 강제로 빼앗을 수 없다는 조건으로, 교착 상태의 발생 조건이다."},{"verdict":"정답","why":"교착 상태 조건은 환형 대기(Circular Wait)다. 선형 대기(Linear Wait)는 발생 조건이 아니다."}],"keywords":[{"term":"상호 배제(Mutual Exclusion)","desc":"한 자원은 한 프로세스만 사용"},{"term":"점유와 대기(Hold and Wait)","desc":"자원을 가진 채 다른 자원 대기"},{"term":"비선점(Non-preemption)","desc":"남의 자원을 강제로 빼앗을 수 없음"},{"term":"환형 대기(Circular Wait)","desc":"프로세스들이 원형으로 서로의 자원을 기다림"}],"memo":"교착 상태는 '원을 그리며' 기다린다. Linear(직선)가 아니라 Circular(원형)."}},{"id":"written-2021-1-67","no":67,"unit":"프로그래밍 언어 활용","q":"IPv6에 대한 설명으로 틀린 것은?","choices":["멀티캐스팅(Multicast) 대신 브로드캐스트(Broadcast)를 사용한다.","보안과 인증 확장 헤더를 사용함으로써 인터넷 계층의 보안기능을 강화하였다.","애니캐스트(Anycast)는 하나의 호스트에서 그룹 내의 가장 가까운 곳에 있는 수신자에게 전달하는 방식이다.","128비트 주소체계를 사용한다."],"ans":1,"rate":68,"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv6는 IPv4의 주소 부족 문제를 해결하려고 만든 128비트 주소 체계다. 전송 방식으로 유니캐스트, 멀티캐스트, 애니캐스트를 쓰며, IPv4의 브로드캐스트는 없애고 멀티캐스트로 대신한다. 인증과 보안을 위한 확장 헤더를 지원해 보안 기능이 강화되었다.","choices":[{"verdict":"정답","why":"IPv6는 브로드캐스트를 쓰지 않고 멀티캐스트로 대신한다. 설명이 거꾸로 되어 있다."},{"verdict":"오답","why":"IPv6는 인증 헤더와 보안 페이로드 같은 확장 헤더로 인터넷 계층의 보안 기능을 강화했다. 맞는 설명이다."},{"verdict":"오답","why":"애니캐스트는 같은 그룹 안에서 가장 가까운 한 수신자에게 전달하는 방식이다. 맞는 설명이다."},{"verdict":"오답","why":"IPv6 주소는 128비트로 이루어진다(IPv4는 32비트). 맞는 설명이다."}],"keywords":[{"term":"IPv6","desc":"128비트, 16비트씩 8부분을 16진수로 표기, 콜론(:)으로 구분"},{"term":"유니캐스트(Unicast)","desc":"1:1 전송"},{"term":"멀티캐스트(Multicast)","desc":"1:다(특정 그룹) 전송"},{"term":"애니캐스트(Anycast)","desc":"그룹 중 가장 가까운 한 곳에 전송"}],"memo":"IPv6에는 브로드캐스트가 없다. 유니·멀티·애니 세 가지만 기억한다."}},{"id":"written-2021-1-68","no":68,"unit":"프로그래밍 언어 활용","q":"TCP/IP 프로토콜에서 TCP가 해당하는 계층은?","choices":["데이터 링크 계층","네트워크 계층","트랜스포트 계층","세션 계층"],"ans":3,"rate":55,"wiki":[{"title":"TCP/IP","url":"https://itwiki.kr/w/TCP/IP"},{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"TCP/IP는 링크(네트워크 액세스) 계층, 인터넷 계층, 전송(트랜스포트) 계층, 응용 계층의 4계층으로 이루어진다. TCP(Transmission Control Protocol)는 전송 계층에서 연결형 서비스, 순서 제어, 오류 제어, 흐름 제어로 신뢰성 있는 전송을 맡는다. 같은 전송 계층에 UDP가 있다.","choices":[{"verdict":"오답","why":"데이터 링크 계층에는 이더넷, PPP 등의 프로토콜이 해당한다."},{"verdict":"오답","why":"네트워크(인터넷) 계층에는 IP, ICMP, ARP 등이 해당한다."},{"verdict":"정답","why":"TCP는 UDP와 함께 트랜스포트(전송) 계층의 프로토콜이다."},{"verdict":"오답","why":"세션 계층은 OSI 7계층에만 있는 계층으로 TCP/IP 4계층에는 따로 없다. TCP는 세션 계층 프로토콜이 아니다."}],"keywords":[{"term":"TCP","desc":"전송 계층, 연결형, 신뢰성 있는 전송"},{"term":"UDP","desc":"전송 계층, 비연결형, 빠르지만 신뢰성 낮음"},{"term":"IP","desc":"인터넷 계층, 주소 지정과 경로 설정"},{"term":"TCP/IP 4계층","desc":"링크 - 인터넷 - 전송 - 응용"}],"memo":"TCP의 T는 Transmission, 전송(Transport) 계층과 짝."}},{"id":"written-2021-1-69","no":69,"unit":"프로그래밍 언어 활용","q":"C언어에서 변수로 사용할 수 없는 것은?","choices":["data02","int01","_sub","short"],"ans":4,"rate":70,"exp":{"concept":"C언어 변수 이름은 영문자, 숫자, 밑줄(_)로 만들고 첫 글자는 숫자일 수 없다. 대소문자를 구분하며, 언어가 미리 정해 둔 예약어(키워드)는 변수 이름으로 쓸 수 없다. short는 짧은 정수 자료형을 뜻하는 예약어이므로 변수 이름이 될 수 없다.","choices":[{"verdict":"오답","why":"data02는 영문자로 시작하고 영문자와 숫자로만 이루어져 변수 이름으로 쓸 수 있다."},{"verdict":"오답","why":"int01은 예약어 int에 숫자가 붙은 다른 이름이므로 예약어가 아니어서 변수 이름으로 쓸 수 있다."},{"verdict":"오답","why":"_sub는 밑줄로 시작하는데, 밑줄은 첫 글자로 쓸 수 있으므로 변수 이름으로 쓸 수 있다."},{"verdict":"정답","why":"short는 C언어의 자료형 예약어이므로 변수 이름으로 쓰면 컴파일 오류가 난다."}],"keywords":[{"term":"식별자 규칙","desc":"영문자·숫자·_ 사용, 숫자로 시작 불가, 공백 불가"},{"term":"예약어(Keyword)","desc":"int, short, long, char, if, for, while, return 등"},{"term":"대소문자 구분","desc":"Short와 short는 다른 이름"}],"memo":"예약어와 '똑같은' 이름만 안 된다. int01처럼 무언가 덧붙으면 다른 이름이다."}},{"id":"written-2021-1-70","no":70,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 코드 출력문의 결과는?\n<img src=\"data/img/eip_written_20210307_070.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["5 + 2 = 34<chal>5 + 2 = 34","5 + 2 + 3 + 4<chal>5 + 2 = 7","7 = 7<chal>7 + 7","5 + 2 = 34<chal>5 + 2 = 7"],"ans":4,"rate":76,"exp":{"concept":"자바에서 + 연산은 왼쪽부터 차례로 계산하며, 한쪽이 문자열이면 문자열 연결이 된다. 첫 줄은 \"5 + 2 = \" + 3이 먼저 계산되어 \"5 + 2 = 3\"이 되고, 여기에 4가 이어 붙어 \"5 + 2 = 34\"가 된다. 둘째 줄은 괄호 안의 3 + 4가 먼저 정수 덧셈으로 7이 되어 \"5 + 2 = 7\"이 된다. println은 출력 후 줄을 바꾸므로 두 결과가 두 줄로 나온다.","choices":[{"verdict":"오답","why":"둘째 줄은 괄호 때문에 3 + 4가 먼저 더해져 7이 되므로 '5 + 2 = 34'가 아니다."},{"verdict":"오답","why":"출력문의 큰따옴표 안 문자열은 '5 + 2 = '까지이고 3과 4는 문자열 밖의 숫자이므로 '+ 3 + 4' 같은 글자가 출력되지 않는다."},{"verdict":"오답","why":"문자열 '5 + 2 = '는 계산되지 않고 그대로 출력되므로 '7 = 7'처럼 바뀌지 않는다."},{"verdict":"정답","why":"첫 줄은 문자열 연결로 '5 + 2 = 34', 둘째 줄은 괄호 안 덧셈 후 연결로 '5 + 2 = 7'이 출력된다. 보기는 두 줄을 이어 적은 것이다."}],"keywords":[{"term":"문자열 연결 연산자 +","desc":"피연산자 중 하나가 문자열이면 문자열로 이어 붙임"},{"term":"연산 순서","desc":"+는 왼쪽에서 오른쪽으로 계산, 괄호가 먼저"},{"term":"System.out.println","desc":"출력 후 줄 바꿈"}],"memo":"문자열 뒤에 오는 +는 모두 '이어 붙이기'. 숫자끼리 더하려면 괄호로 먼저 묶어야 한다. 반대로 3 + 4 + \"\"처럼 숫자가 앞에 있으면 7이 먼저 계산된다."}},{"id":"written-2021-1-71","no":71,"unit":"프로그래밍 언어 활용","q":"C언어에서 문자열을 정수형으로 변환하는 라이브러리 함수는?","choices":["atoi( )","atof( )","itoa( )","ceil( )"],"ans":1,"rate":76,"exp":{"concept":"C언어 표준 라이브러리 stdlib.h에는 문자열을 숫자로 바꾸는 함수가 있다. 이름의 a는 ASCII 문자열, to는 '~로', i는 int를 뜻해 atoi는 문자열을 정수로 바꾼다. 예를 들어 atoi(\"123\")은 정수 123을 돌려준다.","choices":[{"verdict":"정답","why":"atoi()는 문자열을 정수(int)로 변환하는 함수다."},{"verdict":"오답","why":"atof()는 문자열을 실수(double)로 변환하는 함수다."},{"verdict":"오답","why":"itoa()는 반대로 정수를 문자열로 변환하는 함수이며, C 표준 라이브러리 함수는 아니다."},{"verdict":"오답","why":"ceil()은 math.h의 함수로, 실수를 올림한 값을 돌려준다."}],"keywords":[{"term":"atoi()","desc":"문자열 → 정수(int)"},{"term":"atof()","desc":"문자열 → 실수(double)"},{"term":"atol()","desc":"문자열 → long 정수"},{"term":"ceil() / floor()","desc":"올림 / 내림 (math.h)"}],"memo":"a to i = 문자열(ASCII)에서 int로. 앞이 변환 전, 뒤가 변환 후."}},{"id":"written-2021-1-72","no":72,"unit":"프로그래밍 언어 활용","q":"운영체제의 가상기억장치 관리에서 프로세스가 일정 시간동안 자주 참조하는 페이지들의 집합을 의미하는 것은?","choices":["Locality","Deadlock","Thrashing","Working Set"],"ans":4,"rate":68,"exp":{"concept":"워킹 셋(Working Set)은 프로세스가 일정 시간 동안 자주 참조하는 페이지들의 집합이다. 이 페이지들을 주기억장치에 계속 올려 두면 페이지 부재가 줄어 스래싱을 막을 수 있다. 공부할 때 자주 펴 보는 책 몇 권을 책상 위에 올려 두는 것과 같다.","choices":[{"verdict":"오답","why":"구역성(Locality)은 프로세스가 실행 중 일부 페이지를 집중적으로 참조하는 성질로, 페이지들의 집합 자체가 아니다. 워킹 셋은 이 구역성을 바탕으로 한다."},{"verdict":"오답","why":"교착 상태(Deadlock)는 여러 프로세스가 서로 상대의 자원을 기다리며 진행하지 못하는 상태다."},{"verdict":"오답","why":"스래싱(Thrashing)은 페이지 부재가 너무 자주 일어나 실행보다 페이지 교체에 더 많은 시간을 쓰는 현상이다."},{"verdict":"정답","why":"프로세스가 일정 시간 동안 자주 참조하는 페이지들의 집합은 워킹 셋이다."}],"keywords":[{"term":"워킹 셋(Working Set)","desc":"일정 시간 동안 자주 참조하는 페이지 집합"},{"term":"구역성(Locality)","desc":"일부 페이지를 집중 참조하는 성질, 시간·공간 구역성"},{"term":"스래싱(Thrashing)","desc":"페이지 교체에 시간을 더 많이 써 성능이 급격히 떨어지는 현상"},{"term":"PFF(Page Fault Frequency)","desc":"페이지 부재 빈도로 프레임 수를 조절하는 방식"}],"memo":"'페이지들의 집합'이면 Working Set, '성질'이면 Locality, '현상'이면 Thrashing."}},{"id":"written-2021-1-73","no":73,"unit":"프로그래밍 언어 활용","q":"결합도가 낮은 것부터 높은 순으로 옳게 나열한 것은?\n<img src=\"data/img/eip_written_20210307_073.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["(ㄱ) → (ㄴ) → (ㄹ) → (ㅂ) → (ㅁ) → (ㄷ)","(ㄴ) → (ㄹ) → (ㅁ) → (ㅂ) → (ㄷ) → (ㄱ)","(ㄴ) → (ㄹ) → (ㅂ) → (ㅁ) → (ㄷ) → (ㄱ)","(ㄱ) → (ㄴ) → (ㄹ) → (ㅁ) → (ㅂ) → (ㄷ)"],"ans":3,"rate":64,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"},{"title":"모듈화","url":"https://itwiki.kr/w/모듈화"}],"exp":{"concept":"결합도는 모듈끼리 얼마나 의존하는지를 나타내며, 낮을수록 좋다. 낮은 것부터 자료 < 스탬프 < 제어 < 외부 < 공통 < 내용 결합도 순이다. 따라서 (ㄴ) 자료 → (ㄹ) 스탬프 → (ㅂ) 제어 → (ㅁ) 외부 → (ㄷ) 공통 → (ㄱ) 내용 순서가 된다.","choices":[{"verdict":"오답","why":"가장 높은 내용 결합도(ㄱ)를 맨 앞에 두었고, 공통 결합도(ㄷ)를 맨 끝에 두었다."},{"verdict":"오답","why":"외부(ㅁ)와 제어(ㅂ)의 순서가 바뀌었다. 제어 결합도가 외부 결합도보다 낮다."},{"verdict":"정답","why":"자료(ㄴ) → 스탬프(ㄹ) → 제어(ㅂ) → 외부(ㅁ) → 공통(ㄷ) → 내용(ㄱ)이 낮은 것부터 높은 순서다."},{"verdict":"오답","why":"가장 높은 내용 결합도(ㄱ)를 맨 앞에 두었고, 외부(ㅁ)와 제어(ㅂ)의 순서도 바뀌었다."}],"keywords":[{"term":"자료 결합도","desc":"필요한 자료 요소만 매개변수로 전달, 가장 낮음"},{"term":"스탬프 결합도","desc":"배열·레코드 같은 자료 구조를 전달"},{"term":"제어 결합도","desc":"다른 모듈의 처리 흐름을 제어하는 신호(플래그)를 전달"},{"term":"외부 결합도","desc":"외부에서 선언한 데이터(변수)를 참조"},{"term":"공통 / 내용 결합도","desc":"공유 전역 변수 사용 / 다른 모듈 내부를 직접 참조, 내용이 가장 높음"}],"memo":"낮은 순서 '자스제외공내' (자료-스탬프-제어-외부-공통-내용)."}},{"id":"written-2021-1-74","no":74,"unit":"프로그래밍 언어 활용","q":"다음 설명의 ㉠과 ㉡에 들어갈 내용으로 옳은 것은?\n<img src=\"data/img/eip_written_20210307_074.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["㉠ : Paging, ㉡ : Segmentation","㉠ : Segmentation, ㉡ : Allocation","㉠ : Segmentation, ㉡ : Compaction","㉠ : Paging, ㉡ : Linking"],"ans":1,"rate":77,"wiki":[{"title":"가상 메모리","url":"https://itwiki.kr/w/가상 메모리"}],"exp":{"concept":"가상기억장치는 보조기억장치를 주기억장치처럼 쓰게 하는 기법이며, 프로그램을 블록으로 나누어 필요한 부분만 주기억장치에 올린다. 블록을 모두 같은 크기로 나누면 페이징(Paging), 논리적인 의미 단위로 서로 다른 크기로 나누면 세그먼테이션(Segmentation)이다. 페이징은 외부 단편화가 없지만 내부 단편화가 생길 수 있고, 세그먼테이션은 그 반대다.","choices":[{"verdict":"정답","why":"고정된 같은 크기의 블록으로 나누는 것이 페이징(㉠), 가변적인 크기의 블록으로 나누는 것이 세그먼테이션(㉡)이다."},{"verdict":"오답","why":"세그먼테이션은 가변 크기 블록으로 나누는 기법이므로 ㉠에 맞지 않고, 할당(Allocation)은 가상기억장치 구현 기법의 이름이 아니다."},{"verdict":"오답","why":"세그먼테이션은 ㉠이 아니라 ㉡에 해당하고, 압축(Compaction)은 흩어진 빈 공간을 한곳으로 모으는 기법으로 가상기억장치 구현 방법이 아니다."},{"verdict":"오답","why":"㉠의 페이징은 맞지만, 링킹(Linking)은 여러 목적 프로그램을 연결해 실행 파일을 만드는 작업으로 가상기억장치 구현 방법이 아니다."}],"keywords":[{"term":"페이징(Paging)","desc":"같은 크기(페이지)로 분할, 내부 단편화 발생 가능"},{"term":"세그먼테이션(Segmentation)","desc":"논리 단위·가변 크기로 분할, 외부 단편화 발생 가능"},{"term":"압축(Compaction)","desc":"흩어진 빈 공간을 하나로 모음"},{"term":"통합(Coalescing)","desc":"인접한 빈 공간을 하나로 합침"}],"memo":"Page는 책의 쪽처럼 크기가 같고, Segment는 단원처럼 길이가 제각각이다."}},{"id":"written-2021-1-75","no":75,"unit":"프로그래밍 언어 활용","q":"라이브러리의 개념과 구성에 대한 설명 중 틀린 것은?","choices":["라이브러리란 필요할 때 찾아서 쓸 수 있도록 모듈화되어 제공되는 프로그램을 말한다.","프로그래밍 언어에 따라 일반적으로 도움말, 설치 파일, 샘플 코드 등을 제공한다.","외부 라이브러리는 프로그래밍 언어가 기본적으로 가지고 있는 라이브러리를 의미하며, 표준 라이브러리는 별\n도의 파일 설치를 필요로 하는 라이브러리를 의미한다.","라이브러리는 모듈과 패키지를 총칭하며, 모듈이 개별 파일이라면 패키지는 파일들을 모아 놓은 폴더라고 볼 수 있다."],"ans":3,"rate":84,"exp":{"concept":"라이브러리는 자주 쓰는 기능을 모듈화해 필요할 때 가져다 쓸 수 있게 만든 프로그램 모음이다. 프로그래밍 언어에 기본으로 포함된 것은 표준 라이브러리, 별도로 설치해야 쓸 수 있는 것은 외부 라이브러리다. 모듈은 개별 파일, 패키지는 모듈들을 모은 폴더에 해당한다.","choices":[{"verdict":"오답","why":"라이브러리는 필요할 때 찾아 쓸 수 있도록 모듈화되어 제공되는 프로그램이다. 맞는 설명이다."},{"verdict":"오답","why":"라이브러리는 도움말, 설치 파일, 샘플 코드 등을 함께 제공하는 경우가 일반적이다. 맞는 설명이다."},{"verdict":"정답","why":"설명이 서로 바뀌었다. 언어가 기본으로 가진 것이 표준 라이브러리이고, 별도 설치가 필요한 것이 외부 라이브러리다."},{"verdict":"오답","why":"라이브러리는 모듈과 패키지를 아우르며, 모듈은 개별 파일, 패키지는 파일을 모은 폴더로 볼 수 있다. 맞는 설명이다."}],"keywords":[{"term":"표준 라이브러리","desc":"언어에 기본 포함, 별도 설치 불필요"},{"term":"외부 라이브러리","desc":"별도로 설치해야 사용 가능"},{"term":"모듈(Module)","desc":"기능을 담은 개별 파일"},{"term":"패키지(Package)","desc":"모듈들을 모아 놓은 폴더"}],"memo":"'외부'는 밖에서 가져온다(설치), '표준'은 처음부터 들어 있다."}},{"id":"written-2021-1-76","no":76,"unit":"프로그래밍 언어 활용","q":"C언어에서 산술 연산자가 아닌 것은?","choices":["%","*","/","="],"ans":4,"rate":79,"exp":{"concept":"C언어의 산술 연산자는 +, -, *, /, %(나머지)와 증감 연산자 ++, -- 등이다. =는 오른쪽 값을 왼쪽 변수에 저장하는 대입 연산자이며, 같은지 비교하는 관계 연산자는 ==다. 수학의 등호와 모양이 같아도 하는 일이 다르다.","choices":[{"verdict":"오답","why":"%는 나눗셈의 나머지를 구하는 산술 연산자다. 예: 7 % 3은 1."},{"verdict":"오답","why":"*는 곱셈을 하는 산술 연산자다."},{"verdict":"오답","why":"/는 나눗셈을 하는 산술 연산자다. 정수끼리 나누면 몫만 남는다."},{"verdict":"정답","why":"=는 대입 연산자로, 산술 연산자가 아니다."}],"keywords":[{"term":"산술 연산자","desc":"+, -, *, /, %, ++, --"},{"term":"대입 연산자","desc":"=, +=, -=, *=, /=, %= 등"},{"term":"관계 연산자","desc":"==, !=, >, >=, <, <="}],"memo":"=는 '넣는다', ==는 '같은가'. 둘 다 산술 연산자가 아니다."}},{"id":"written-2021-1-77","no":77,"unit":"프로그래밍 언어 활용","q":"UDP 특성에 해당되는 것은?","choices":["양방향 연결형 서비스를 제공한다.","송신중에 링크를 유지관리하므로 신뢰성이 높다.","순서제어, 오류제어, 흐름제어 기능을 한다.","흐름제어나 순서제어가 없어 전송속도가 빠르다."],"ans":4,"rate":67,"wiki":[{"title":"UDP","url":"https://itwiki.kr/w/UDP"}],"exp":{"concept":"UDP(User Datagram Protocol)는 전송 계층의 비연결형 프로토콜이다. 연결 설정 없이 바로 보내고, 순서 제어나 흐름 제어, 재전송 같은 신뢰성 기능이 없어서 헤더가 단순하고 전송 속도가 빠르다. 실시간 영상·음성 스트리밍, DNS 질의처럼 속도가 중요한 곳에 쓴다.","choices":[{"verdict":"오답","why":"양방향 연결형 서비스를 제공하는 것은 TCP다. UDP는 비연결형이다."},{"verdict":"오답","why":"송신 중 연결(링크)을 유지·관리해 신뢰성이 높은 것은 TCP의 특성이다."},{"verdict":"오답","why":"순서 제어, 오류 제어, 흐름 제어 기능을 하는 것은 TCP다. UDP는 이런 제어를 하지 않는다."},{"verdict":"정답","why":"UDP는 흐름 제어나 순서 제어가 없어 처리가 단순하고 전송 속도가 빠르다."}],"keywords":[{"term":"UDP","desc":"비연결형, 신뢰성 낮음, 빠름, 실시간 전송에 적합"},{"term":"TCP","desc":"연결형, 순서·오류·흐름 제어로 신뢰성 높음"},{"term":"3-way handshake","desc":"TCP의 연결 설정 과정(SYN, SYN+ACK, ACK)"}],"memo":"TCP는 등기 우편(확인·재발송), UDP는 일반 우편(보내고 끝, 대신 빠름)."}},{"id":"written-2021-1-78","no":78,"unit":"프로그래밍 언어 활용","q":"JAVA에서 변수와 자료형에 대한 설명으로 틀린 것은?","choices":["변수는 어떤 값을 주기억 장치에 기억하기 위해서 사용하는 공간이다.","변수의 자료형에 따라 저장할 수 있는 값의 종류와 범위가 달라진다.","char 자료형은 나열된 여러 개의 문자를 저장하고자 할 때 사용한다.","boolean 자료형은 조건이 참인지 거짓인지 판단하고자 할 때 사용한다."],"ans":3,"rate":74,"exp":{"concept":"변수는 값을 주기억장치에 저장하기 위한 이름 붙은 공간이고, 자료형에 따라 저장할 수 있는 값의 종류와 범위가 정해진다. 자바의 char는 문자 하나만 저장하는 2바이트 자료형이다. 여러 개의 문자를 나열한 문자열은 String 클래스로 저장한다.","choices":[{"verdict":"오답","why":"변수는 어떤 값을 주기억장치에 기억하기 위해 사용하는 공간이다. 맞는 설명이다."},{"verdict":"오답","why":"자료형에 따라 저장할 수 있는 값의 종류(정수, 실수, 문자 등)와 범위가 달라진다. 맞는 설명이다."},{"verdict":"정답","why":"char는 문자 한 개를 저장하는 자료형이다. 여러 개의 문자를 저장할 때는 String을 사용한다."},{"verdict":"오답","why":"boolean은 true 또는 false 값만 가지며 조건의 참·거짓을 판단할 때 쓴다. 맞는 설명이다."}],"keywords":[{"term":"char","desc":"문자 1개, 2바이트(유니코드), 작은따옴표 'A'"},{"term":"String","desc":"문자열(여러 문자), 큰따옴표 \"ABC\""},{"term":"boolean","desc":"true / false"},{"term":"자바 정수형","desc":"byte(1), short(2), int(4), long(8) 바이트"}],"memo":"char는 글자 '하나', 여러 글자는 String."}},{"id":"written-2021-1-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음은 파이썬으로 만들어진 반복문 코드이다. 이 코드의 결과는?\n<img src=\"data/img/eip_written_20210307_079.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["A, B, C 출력이 반복된다.","A, B, C 까지만 출력된다.","A, B, C, D 출력이 반복된다.","A, B, C, D 까지만 출력된다."],"ans":1,"rate":72,"exp":{"concept":"while(True)는 조건이 항상 참이라 끝없이 반복하는 무한 루프다. continue를 만나면 그 아래 문장을 건너뛰고 곧바로 반복문의 처음으로 돌아간다. 그래서 print('A'), print('B'), print('C')는 매번 실행되지만 continue 아래의 print('D')는 한 번도 실행되지 않고, A, B, C 출력이 끝없이 반복된다.","choices":[{"verdict":"정답","why":"break가 없어 반복이 끝나지 않고, continue 때문에 D는 출력되지 않으므로 A, B, C 출력이 무한히 반복된다."},{"verdict":"오답","why":"조건이 True로 고정되어 있고 반복을 끝내는 break가 없으므로 A, B, C를 한 번 출력하고 끝나지 않고 계속 반복한다."},{"verdict":"오답","why":"continue가 print('D')보다 먼저 실행되어 반복의 처음으로 돌아가므로 D는 출력되지 않는다."},{"verdict":"오답","why":"D는 continue 때문에 출력되지 않고, 반복도 끝나지 않는다."}],"keywords":[{"term":"while True","desc":"조건이 항상 참인 무한 반복"},{"term":"continue","desc":"아래 문장을 건너뛰고 반복의 처음으로 이동"},{"term":"break","desc":"반복문을 즉시 빠져나감"}],"memo":"continue는 '다음 바퀴로', break는 '반복 끝'. continue 아래 줄은 영원히 실행되지 않는다."}},{"id":"written-2021-1-80","no":80,"unit":"프로그래밍 언어 활용","q":"WAS(Web Application Server)가 아닌 것은?","choices":["JEUS","JVM","Tomcat","WebSphere"],"ans":2,"rate":64,"exp":{"concept":"WAS(Web Application Server)는 사용자 요청에 따라 프로그램을 실행해 동적인 웹 페이지를 만들어 주는 미들웨어다. 대표적으로 Tomcat, JEUS, WebLogic, WebSphere 등이 있다. JVM(Java Virtual Machine)은 자바 바이트코드를 실행하는 가상 머신으로, WAS가 아니다.","choices":[{"verdict":"오답","why":"JEUS는 티맥스소프트가 만든 국산 WAS다."},{"verdict":"정답","why":"JVM은 자바 바이트코드를 운영체제에 맞게 실행해 주는 가상 머신으로, WAS가 아니다."},{"verdict":"오답","why":"Tomcat은 Apache 재단의 오픈 소스 WAS(서블릿·JSP 컨테이너)다."},{"verdict":"오답","why":"WebSphere는 IBM의 WAS다."}],"keywords":[{"term":"WAS","desc":"동적 콘텐츠를 처리하는 미들웨어, Tomcat·JEUS·WebLogic·WebSphere"},{"term":"웹 서버(Web Server)","desc":"정적 콘텐츠(HTML, 이미지) 제공, Apache HTTP Server·Nginx"},{"term":"JVM(Java Virtual Machine)","desc":"자바 바이트코드 실행 가상 머신"}],"memo":"JVM의 VM은 Virtual Machine, 서버(Server)가 아니다."}},{"id":"written-2021-1-81","no":81,"unit":"정보시스템 구축 관리","q":"다음 암호 알고리즘 중 성격이 다른 하나는?","choices":["MD4","MD5","SHA-1","AES"],"ans":4,"rate":71,"wiki":[{"title":"암호","url":"https://itwiki.kr/w/암호"},{"title":"해시","url":"https://itwiki.kr/w/해시"},{"title":"대칭키 암호화","url":"https://itwiki.kr/w/대칭키 암호화"},{"title":"AES","url":"https://itwiki.kr/w/AES"},{"title":"SHA-1","url":"https://itwiki.kr/w/SHA-1"},{"title":"MD5","url":"https://itwiki.kr/w/MD5"},{"title":"MD4","url":"https://itwiki.kr/w/MD4"}],"exp":{"concept":"해시 함수는 임의 길이의 입력을 고정 길이의 값으로 바꾸는 단방향 함수로, 원래 값으로 되돌릴 수 없다. MD4, MD5, SHA-1은 모두 해시 알고리즘이다. AES는 같은 키로 암호화와 복호화를 하는 대칭키 블록 암호 알고리즘이라 성격이 다르다.","choices":[{"verdict":"오답","why":"MD4는 로널드 리베스트(Ronald Rivest)가 만든 해시 알고리즘이다."},{"verdict":"오답","why":"MD5는 MD4를 개선한 128비트 해시 알고리즘이다."},{"verdict":"오답","why":"SHA-1은 미국 NSA가 설계하고 NIST가 표준으로 채택한 160비트 해시 알고리즘이다."},{"verdict":"정답","why":"AES는 대칭키(개인키) 블록 암호 알고리즘으로, 나머지 세 해시 알고리즘과 성격이 다르다."}],"keywords":[{"term":"해시(Hash) 알고리즘","desc":"MD4, MD5, SHA 계열, HAVAL 등"},{"term":"대칭키 암호","desc":"DES, AES, SEED, ARIA, IDEA, RC4 등"},{"term":"비대칭키(공개키) 암호","desc":"RSA, ECC, ElGamal 등"},{"term":"AES(Advanced Encryption Standard)","desc":"128비트 블록, 키 128·192·256비트, DES 대체 표준"}],"memo":"MD·SHA는 해시(되돌릴 수 없음), AES는 암호(키로 복호화 가능)."}},{"id":"written-2021-1-82","no":82,"unit":"정보시스템 구축 관리","q":"크래커가 침입하여 백도어를 만들어 놓거나, 설정파일을 변경했을 때 분석하는 도구는?","choices":["tripwire","tcpdump","cron","netcat"],"ans":1,"rate":70,"wiki":[{"title":"Tripwire","url":"https://itwiki.kr/w/Tripwire"}],"exp":{"concept":"트립와이어(Tripwire)는 시스템 파일의 해시 값 등 상태를 미리 기록해 두었다가 나중에 비교해, 파일이 바뀌었는지 찾아내는 무결성 검사 도구다. 크래커가 침입해 백도어를 심거나 설정 파일을 바꾸면 그 변화를 알아낼 수 있다. 집에 들어갈 때 문틈에 끼워 둔 종이가 떨어졌는지 보는 것과 비슷하다.","choices":[{"verdict":"정답","why":"tripwire는 파일의 변경 여부를 검사해 백도어 설치나 설정 파일 변경을 분석하는 무결성 검사 도구다."},{"verdict":"오답","why":"tcpdump는 네트워크 인터페이스를 지나는 패킷을 캡처해 보여 주는 패킷 분석 도구다."},{"verdict":"오답","why":"cron은 정해진 시간에 작업을 자동으로 실행하는 유닉스·리눅스의 작업 스케줄러다."},{"verdict":"오답","why":"netcat은 TCP·UDP 연결로 데이터를 읽고 쓰는 네트워크 유틸리티로, 포트 스캔이나 연결 점검 등에 쓰인다."}],"keywords":[{"term":"Tripwire","desc":"파일 무결성 검사로 백도어·설정 변경 탐지"},{"term":"tcpdump","desc":"네트워크 패킷 캡처·분석"},{"term":"cron","desc":"주기적 작업 예약 실행"},{"term":"netcat","desc":"TCP·UDP로 데이터를 주고받는 네트워크 유틸리티"}],"memo":"trip(걸려 넘어지다) + wire(줄) = 침입자가 건드리면 걸리는 줄."}},{"id":"written-2021-1-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 것은?\n<img src=\"data/img/eip_written_20210307_083.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["GRID","TELNET","GPN","MQTT"],"ans":4,"rate":63,"wiki":[{"title":"mqtt","url":"https://itwiki.kr/w/mqtt"}],"exp":{"concept":"MQTT(Message Queuing Telemetry Transport)는 IBM이 주도해 개발한 경량 메시지 전송 프로토콜이다. 대역폭이 제한된 사물 통신·사물 인터넷 환경에 맞게 설계되었고, 발행·구독(Publish-Subscribe) 방식을 쓴다. 송신자가 브로커에게 메시지를 발행하면, 그 주제를 구독한 수신자들이 메시지를 받는다.","choices":[{"verdict":"오답","why":"그리드(GRID) 컴퓨팅은 네트워크로 연결된 여러 컴퓨터의 자원을 묶어 하나의 큰 컴퓨터처럼 쓰는 기술로, 메시지 전송 프로토콜이 아니다."},{"verdict":"오답","why":"텔넷(TELNET)은 원격지 컴퓨터에 접속해 명령을 실행하는 원격 접속 프로토콜이다."},{"verdict":"오답","why":"GPN은 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"IBM이 주도해 개발하고, 브로커를 통한 발행·구독 방식으로 동작하는 IoT용 경량 메시지 프로토콜은 MQTT다."}],"keywords":[{"term":"MQTT","desc":"IBM 주도, 발행·구독 방식, IoT용 경량 메시지 프로토콜"},{"term":"브로커(Broker)","desc":"발행된 메시지를 구독자에게 전달하는 중개자"},{"term":"CoAP","desc":"제약된 기기용 웹 전송 프로토콜, UDP 기반"},{"term":"TELNET","desc":"원격 접속 프로토콜, 평문 전송"}],"memo":"'브로커', '발행·구독', 'IBM'이 나오면 MQTT."}},{"id":"written-2021-1-84","no":84,"unit":"정보시스템 구축 관리","q":"나선형(Spiral) 모형의 주요 태스크에 해당되지 않는 것은?","choices":["버전 관리","위험 분석","개발","평가"],"ans":1,"rate":69,"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"exp":{"concept":"나선형(Spiral) 모형은 Boehm이 제안한 모형으로, 개발 과정을 여러 번 반복하면서 매번 위험을 분석해 줄여 나간다. 한 바퀴는 계획 수립 → 위험 분석 → 개발(공학적 개발) → 고객 평가의 네 가지 작업으로 이루어진다. 버전 관리는 형상 관리의 활동이지 나선형 모형의 주요 태스크가 아니다.","choices":[{"verdict":"정답","why":"버전 관리는 형상 관리에서 하는 활동으로, 나선형 모형의 네 가지 주요 태스크(계획, 위험 분석, 개발, 평가)에 들어가지 않는다."},{"verdict":"오답","why":"위험 분석은 나선형 모형의 핵심 태스크로, 위험 요소를 찾아 줄이는 단계다."},{"verdict":"오답","why":"개발(공학적 개발)은 나선형 모형에서 실제로 시스템을 만드는 태스크다."},{"verdict":"오답","why":"평가(고객 평가)는 개발 결과를 고객이 평가하고 다음 단계를 정하는 태스크다."}],"keywords":[{"term":"나선형 모형(Spiral Model)","desc":"Boehm 제안, 반복하며 위험 분석으로 위험 최소화"},{"term":"나선형 4단계","desc":"계획 수립 → 위험 분석 → 개발 → 고객 평가"},{"term":"형상 관리","desc":"버전 관리 등 변경 사항을 관리하는 활동"}],"memo":"나선형은 '계위개평' (계획-위험 분석-개발-평가). 나선형의 핵심어는 위험 분석."}},{"id":"written-2021-1-85","no":85,"unit":"정보시스템 구축 관리","q":"정보 보안을 위한 접근통제 정책 종류에 해당하지 않는 것은?","choices":["임의적 접근 통제","데이터 전환 접근 통제","강제적 접근 통제","역할 기반 접근 통제"],"ans":2,"rate":58,"wiki":[{"title":"접근통제 정책","url":"https://itwiki.kr/w/접근통제 정책"}],"exp":{"concept":"접근 통제 정책은 누가 어떤 자원에 접근할 수 있는지 정하는 규칙이다. 대표적으로 데이터 소유자가 권한을 정하는 임의적 접근 통제(DAC), 보안 등급에 따라 시스템이 강제로 정하는 강제적 접근 통제(MAC), 사용자의 역할에 따라 권한을 주는 역할 기반 접근 통제(RBAC) 세 가지가 있다.","choices":[{"verdict":"오답","why":"임의적 접근 통제(DAC, Discretionary Access Control)는 데이터 소유자가 사용자 신원에 따라 접근 권한을 부여하는 정책이다."},{"verdict":"정답","why":"데이터 전환 접근 통제는 접근 통제 정책의 종류가 아니다."},{"verdict":"오답","why":"강제적 접근 통제(MAC, Mandatory Access Control)는 주체와 객체의 보안 등급을 비교해 시스템이 접근을 강제로 통제하는 정책이다."},{"verdict":"오답","why":"역할 기반 접근 통제(RBAC, Role Based Access Control)는 사용자의 역할(직무)에 따라 접근 권한을 부여하는 정책이다."}],"keywords":[{"term":"DAC(임의적 접근 통제)","desc":"데이터 소유자가 신원 기반으로 권한 부여"},{"term":"MAC(강제적 접근 통제)","desc":"보안 등급(레이블) 기반으로 시스템이 강제 통제"},{"term":"RBAC(역할 기반 접근 통제)","desc":"역할(직무)에 따라 권한 부여, 중앙 관리자가 관리"}],"memo":"접근 통제는 '임강역' (임의적-강제적-역할 기반) 세 가지."}},{"id":"written-2021-1-86","no":86,"unit":"정보시스템 구축 관리","q":"LOC기법에 의하여 예측된 총 라인수가 36,000라인, 개발에 참여할 프로그래머가 6명, 프로그래머들의 평균 생산성이 월간 300라인일 때 개발에 소요되는 기간은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"rate":89,"exp":{"concept":"LOC(Line Of Code) 기법은 예상 코드 줄 수로 개발 노력과 기간을 추정한다. 노력(인월) = 총 라인 수 ÷ 1인당 월 생산성이고, 기간 = 노력 ÷ 투입 인원이다. 36,000 ÷ 300 = 120인월, 120 ÷ 6명 = 20개월이다.","choices":[{"verdict":"오답","why":"5개월이면 6명 × 300라인 × 5개월 = 9,000라인밖에 만들지 못한다."},{"verdict":"오답","why":"10개월이면 6명 × 300라인 × 10개월 = 18,000라인으로 36,000라인의 절반이다."},{"verdict":"오답","why":"15개월이면 6명 × 300라인 × 15개월 = 27,000라인으로 36,000라인에 못 미친다."},{"verdict":"정답","why":"노력 = 36,000 ÷ 300 = 120인월, 기간 = 120 ÷ 6 = 20개월이다."}],"keywords":[{"term":"LOC 기법","desc":"예상 라인 수로 비용·노력·기간 추정"},{"term":"노력(인월)","desc":"LOC ÷ 1인당 월평균 생산 코드 라인 수"},{"term":"개발 기간","desc":"노력(인월) ÷ 투입 인원"},{"term":"개발 비용","desc":"노력(인월) × 단위 비용(1인당 월평균 인건비)"}],"memo":"한 달에 팀 전체가 만드는 양(6 × 300 = 1,800라인)으로 전체(36,000)를 나누면 바로 20개월."}},{"id":"written-2021-1-87","no":87,"unit":"정보시스템 구축 관리","q":"정형화된 분석 절차에 따라 사용자 요구사항을 파악, 문서화하는 체계적 분석방법으로 자료흐름도, 자료사전, 소단위명세서의 특징을 갖는 것은?","choices":["구조적 개발 방법론","객체지향 개발 방법론","정보공학 방법론","CBD 방법론"],"ans":1,"rate":65,"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"},{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"exp":{"concept":"구조적 개발 방법론은 정형화된 분석 절차에 따라 사용자 요구사항을 파악하고 문서화하는 체계적인 방법론이다. 분석 도구로 자료 흐름도(DFD), 자료 사전(DD), 소단위 명세서(Mini-Spec), 개체 관계도(ERD) 등을 쓴다. 문제를 큰 기능에서 작은 기능으로 나누는 분할 정복 방식을 따른다.","choices":[{"verdict":"정답","why":"자료 흐름도, 자료 사전, 소단위 명세서를 사용해 요구사항을 체계적으로 분석·문서화하는 것은 구조적 개발 방법론이다."},{"verdict":"오답","why":"객체지향 개발 방법론은 현실 세계를 객체와 클래스로 모델링하며, UML 다이어그램을 주로 사용한다."},{"verdict":"오답","why":"정보공학 방법론은 기업 전체 관점에서 정보 시스템을 계획·분석·설계·구축하는 데이터 중심 방법론이다."},{"verdict":"오답","why":"CBD 방법론은 재사용 가능한 컴포넌트를 조립해 새 응용 프로그램을 만드는 방법론이다."}],"keywords":[{"term":"구조적 방법론","desc":"DFD, 자료 사전, 소단위 명세서, 분할 정복"},{"term":"정보공학 방법론","desc":"기업 전체의 정보 시스템을 데이터 중심으로 구축"},{"term":"객체지향 방법론","desc":"객체·클래스 중심, UML 사용"},{"term":"CBD 방법론","desc":"컴포넌트 조립, 재사용성 향상"}],"memo":"DFD, DD, 소단위 명세서 세 가지가 함께 나오면 무조건 구조적 방법론."}},{"id":"written-2021-1-88","no":88,"unit":"정보시스템 구축 관리","q":"정보보호를 위한 암호화에 대한 설명으로 틀린 것은?","choices":["평문 – 암호화되기 전의 원본 메시지","암호문 – 암호화가 적용된 메시지","복호화 – 평문을 암호문으로 바꾸는 작업","키(Key) - 적절한 암호화를 위하여 사용하는 값"],"ans":3,"rate":84,"wiki":[{"title":"암호#용어_정의","url":"https://itwiki.kr/w/암호#용어_정의"}],"exp":{"concept":"암호화는 평문(원본 메시지)을 키를 이용해 알아볼 수 없는 암호문으로 바꾸는 것이고, 복호화는 그 반대로 암호문을 다시 평문으로 되돌리는 것이다. 키는 암호화와 복호화에 쓰는 값이다. 자물쇠로 잠그는 것이 암호화, 열쇠로 여는 것이 복호화다.","choices":[{"verdict":"오답","why":"평문은 암호화되기 전의 원본 메시지다. 맞는 설명이다."},{"verdict":"오답","why":"암호문은 암호화가 적용된 메시지다. 맞는 설명이다."},{"verdict":"정답","why":"평문을 암호문으로 바꾸는 작업은 암호화다. 복호화는 암호문을 평문으로 되돌리는 작업이다."},{"verdict":"오답","why":"키는 암호화와 복호화를 위해 사용하는 값이다. 맞는 설명이다."}],"keywords":[{"term":"평문(Plaintext)","desc":"암호화 전 원본 메시지"},{"term":"암호문(Ciphertext)","desc":"암호화된 메시지"},{"term":"암호화(Encryption)","desc":"평문 → 암호문"},{"term":"복호화(Decryption)","desc":"암호문 → 평문"}],"memo":"복호화의 '복'은 회복(되돌림). 암호문을 평문으로 되돌린다."}},{"id":"written-2021-1-89","no":89,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 것은?\n<img src=\"data/img/eip_written_20210307_089.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["OTT","Baas","SDDC","Wi-SUN"],"ans":2,"rate":76,"wiki":[{"title":"BaaS","url":"https://itwiki.kr/w/BaaS"}],"exp":{"concept":"BaaS(Blockchain as a Service)는 블록체인 개발 환경을 클라우드 서비스로 빌려 쓰는 개념이다. 블록체인의 기본 인프라를 추상화해 제공하므로, 사용자는 직접 서버와 네트워크를 구축하지 않고도 블록체인 응용 프로그램을 만들고 노드를 쉽게 추가·제거할 수 있다. IaaS, PaaS, SaaS처럼 '무엇을 서비스로 제공하느냐'를 이름에 담은 형태다.","choices":[{"verdict":"오답","why":"OTT(Over The Top)는 인터넷을 통해 방송·영화 등 동영상 콘텐츠를 제공하는 서비스다."},{"verdict":"정답","why":"블록체인 개발 환경과 기본 인프라를 클라우드로 제공하는 플랫폼은 BaaS(Blockchain as a Service)다."},{"verdict":"오답","why":"SDDC(Software Defined Data Center)는 데이터센터의 모든 자원을 가상화해 소프트웨어로 정의하고 관리하는 데이터센터다."},{"verdict":"오답","why":"Wi-SUN(Wireless Smart Utility Network)은 스마트 그리드 같은 장거리 저전력 무선 통신을 위한 기술이다."}],"keywords":[{"term":"BaaS(Blockchain as a Service)","desc":"블록체인 개발 환경을 클라우드로 제공"},{"term":"SDDC(Software Defined Data Center)","desc":"자원을 가상화해 소프트웨어로 관리하는 데이터센터"},{"term":"OTT(Over The Top)","desc":"인터넷 기반 동영상 콘텐츠 서비스"},{"term":"Wi-SUN","desc":"스마트 그리드용 장거리 저전력 무선 통신 기술"}],"memo":"B는 Blockchain, aaS는 as a Service(클라우드로 빌려 씀)."}},{"id":"written-2021-1-90","no":90,"unit":"정보시스템 구축 관리","q":"소프트웨어 비용 산정 기법 중 개발 유형으로 organic, semi-detach, embedded로 구분되는 것은?","choices":["PUTNAM","COCOMO","FP","SLIM"],"ans":2,"rate":85,"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"exp":{"concept":"COCOMO(COnstructive COst MOdel)는 Boehm이 제안한 LOC 기반 비용 산정 모형이다. 소프트웨어를 규모와 복잡도에 따라 조직형(Organic), 반분리형(Semi-detached), 내장형(Embedded) 세 가지 개발 유형으로 나누어 비용을 계산한다. 같은 규모라도 내장형으로 갈수록 노력과 비용이 많이 든다.","choices":[{"verdict":"오답","why":"Putnam 모형은 소프트웨어 생명 주기 전체에 걸친 노력 분포를 Rayleigh-Norden 곡선으로 가정해 추정하는 모형이다."},{"verdict":"정답","why":"개발 유형을 조직형(organic), 반분리형(semi-detached), 내장형(embedded)으로 나누는 것은 COCOMO 모형이다."},{"verdict":"오답","why":"FP(Function Point) 모형은 기능 점수(입력, 출력, 조회, 파일, 인터페이스 등)로 비용을 산정하는 모형이다."},{"verdict":"오답","why":"SLIM은 Putnam 모형을 바탕으로 만든 자동화 비용 산정 도구다."}],"keywords":[{"term":"조직형(Organic)","desc":"기관 내부 업무용, 5만 라인 이하 중소 규모"},{"term":"반분리형(Semi-detached)","desc":"조직형과 내장형의 중간, 30만 라인 이하"},{"term":"내장형(Embedded)","desc":"초대형 규모·복잡한 시스템, 30만 라인 이상"},{"term":"COCOMO 모형 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"조직-반분리-내장 = COCOMO. Putnam과 SLIM은 Rayleigh-Norden 곡선, FP는 기능 점수."}},{"id":"written-2021-1-91","no":91,"unit":"정보시스템 구축 관리","q":"다음 LAN의 네트워크 토폴로지는 어떤 형인가?\n<img src=\"data/img/eip_written_20210307_091.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["그물형","십자형","버스형","링형"],"ans":3,"rate":94,"exp":{"concept":"네트워크 토폴로지는 장치들을 연결한 모양이다. 그림처럼 한 개의 공용 케이블(버스)에 모든 스테이션이 짧은 선으로 매달려 있고 데이터가 그 케이블을 따라 양방향으로 흐르면 버스형이다. 구조가 단순해 설치가 쉽고 노드 추가·제거가 쉽지만, 공용 회선에 문제가 생기면 전체 통신이 끊기고 충돌이 생길 수 있다.","choices":[{"verdict":"오답","why":"그물형(Mesh)은 모든 노드가 서로 직접 연결된 형태로, 그림처럼 한 줄에 매달린 구조가 아니다."},{"verdict":"오답","why":"십자형은 표준 네트워크 토폴로지 분류에 없는 용어다."},{"verdict":"정답","why":"하나의 공용 통신 회선에 여러 스테이션이 연결된 형태이므로 버스형이다."},{"verdict":"오답","why":"링형(Ring)은 인접한 노드끼리 연결해 원형(닫힌 고리)을 이룬 형태로, 그림처럼 양 끝이 열린 한 줄 구조가 아니다."}],"keywords":[{"term":"버스형(Bus)","desc":"하나의 공용 회선에 모든 노드 연결"},{"term":"링형(Ring)","desc":"노드들을 원형으로 연결"},{"term":"성형(Star)","desc":"중앙 장치에 모든 노드를 연결"},{"term":"망형(Mesh)","desc":"모든 노드가 서로 연결, 회선 수 n(n-1)/2"}],"memo":"버스 노선 한 줄에 정류장(스테이션)이 줄줄이 매달린 모양 = 버스형."}},{"id":"written-2021-1-92","no":92,"unit":"정보시스템 구축 관리","q":"전기 및 정보통신기술을 활용하여 전력망을 지능화, 고도화함으로써 고품질의 전력서비스를 제공하고 에너지 이용효율을 극대화하는 전력망은?","choices":["사물 인터넷","스마트 그리드","디지털 아카이빙","미디어 빅뱅"],"ans":2,"rate":73,"exp":{"concept":"스마트 그리드(Smart Grid)는 기존 전력망에 정보통신기술(ICT)을 더해 전력 공급자와 소비자가 실시간으로 정보를 주고받는 지능형 전력망이다. 전력 수요와 공급을 효율적으로 맞춰 고품질 전력 서비스를 제공하고 에너지 이용 효율을 높인다. 그리드(Grid)는 전력망을 뜻한다.","choices":[{"verdict":"오답","why":"사물 인터넷(IoT)은 사물에 센서와 통신 기능을 넣어 인터넷으로 정보를 주고받게 하는 기술로, 전력망 자체를 가리키지 않는다."},{"verdict":"정답","why":"전기와 정보통신기술로 전력망을 지능화·고도화해 에너지 효율을 높인 전력망은 스마트 그리드다."},{"verdict":"오답","why":"디지털 아카이빙은 디지털 정보를 장기간 보존하기 위해 저장·관리하는 작업이다."},{"verdict":"오답","why":"미디어 빅뱅은 미디어 환경이 급격하게 변하는 현상을 가리키는 말로, 전력망과 관계없다."}],"keywords":[{"term":"스마트 그리드(Smart Grid)","desc":"ICT를 결합한 지능형 전력망"},{"term":"사물 인터넷(IoT)","desc":"사물끼리 인터넷으로 정보를 주고받는 기술"},{"term":"Wi-SUN","desc":"스마트 그리드용 장거리 저전력 무선 통신 기술"}],"memo":"Grid = 전력망. '전력망'이라는 단어가 나오면 스마트 그리드."}},{"id":"written-2021-1-93","no":93,"unit":"정보시스템 구축 관리","q":"다음 내용이 설명하는 소프트웨어 개발 모형은?\n<img src=\"data/img/eip_written_20210307_093.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["프로토타입 모형","나선형 모형","폭포수 모형","RAD 모형"],"ans":3,"rate":76,"exp":{"concept":"폭포수 모형(Waterfall Model)은 Boehm이 제시한 가장 오래된 고전적 생명 주기 모형으로, 폭포가 아래로만 흐르듯 각 단계를 순서대로 끝내고 다음 단계로 넘어가는 선형 순차적 모형이다. 타당성 검토, 계획, 요구사항 분석, 설계, 구현, 테스트, 유지보수 순서로 진행한다. 각 단계가 끝나면 결과를 확인한 뒤 다음 단계로 넘어가며, 이전 단계로 되돌아가기 어렵다.","choices":[{"verdict":"오답","why":"프로토타입 모형은 사용자 요구를 확인하기 위해 견본(시제품)을 먼저 만들어 보여 주고 보완해 가는 모형이다."},{"verdict":"오답","why":"나선형 모형은 계획, 위험 분석, 개발, 평가를 반복하며 위험을 줄여 가는 점진적 모형이다."},{"verdict":"정답","why":"고전적 생명 주기 모형이자 선형 순차적 모델로, 단계를 차례로 거쳐 개발하는 모형은 폭포수 모형이다."},{"verdict":"오답","why":"RAD(Rapid Application Development) 모형은 CASE 도구 등을 활용해 매우 짧은 개발 주기로 빠르게 개발하는 모형이다."}],"keywords":[{"term":"폭포수 모형","desc":"고전적·선형 순차적 모형, 단계별 완료 후 다음 단계"},{"term":"프로토타입 모형","desc":"견본을 만들어 요구사항 확인"},{"term":"나선형 모형","desc":"반복하며 위험 분석으로 위험 최소화"},{"term":"RAD 모형","desc":"짧은 주기의 신속한 개발"}],"memo":"'고전적', '선형 순차적'이 보이면 폭포수."}},{"id":"written-2021-1-94","no":94,"unit":"정보시스템 구축 관리","q":"스트림 암호화 방식의 설명으로 옳지 않은 것은?","choices":["비트/바이트/단어들을 순차적으로 암호화한다.","해쉬 함수를 이용한 해쉬 암호화 방식을 사용한다.","RC4는 스트림 암호화 방식에 해당한다.","대칭키 암호화 방식이다."],"ans":2,"rate":51,"wiki":[{"title":"암호","url":"https://itwiki.kr/w/암호"}],"exp":{"concept":"스트림 암호는 대칭키 암호 방식의 하나로, 키로 만든 의사 난수 키 스트림을 평문과 비트·바이트 단위로 차례로 XOR해 암호화한다. 대표 알고리즘은 RC4, LFSR 등이다. 해시 함수는 되돌릴 수 없는 단방향 함수라서 복호화가 필요한 스트림 암호화 방식으로 쓰지 않는다.","choices":[{"verdict":"오답","why":"스트림 암호는 평문을 비트, 바이트, 단어 단위로 순차적으로 암호화한다. 맞는 설명이다."},{"verdict":"정답","why":"스트림 암호는 키 스트림과의 XOR 연산으로 암호화하는 방식이며, 해시 함수를 쓰는 해시 암호화 방식이 아니다."},{"verdict":"오답","why":"RC4는 대표적인 스트림 암호 알고리즘이다. 맞는 설명이다."},{"verdict":"오답","why":"스트림 암호는 암호화와 복호화에 같은 키를 쓰는 대칭키 암호 방식이다. 맞는 설명이다."}],"keywords":[{"term":"스트림 암호","desc":"비트·바이트 단위 순차 암호화, RC4·LFSR"},{"term":"블록 암호","desc":"고정 크기 블록 단위 암호화, DES·AES·SEED·ARIA"},{"term":"해시 함수","desc":"임의 길이 입력을 고정 길이로 바꾸는 단방향 함수"}],"memo":"스트림(흐름) = 물 흐르듯 조금씩 순서대로. 해시는 되돌릴 수 없어 암호화·복호화 방식과 다르다."}},{"id":"written-2021-1-95","no":95,"unit":"정보시스템 구축 관리","q":"세션 하이재킹을 탐지하는 방법으로 거리가 먼 것은?","choices":["FTP SYN SEGNENT 탐지","비동기화 상태 탐지","ACK STORM 탐지","패킷의 유실 및 재전송 증가 탐지"],"ans":1,"rate":47,"wiki":[{"title":"세션 하이재킹","url":"https://itwiki.kr/w/세션 하이재킹"}],"exp":{"concept":"세션 하이재킹은 이미 인증을 마친 정상 사용자의 세션을 가로채 그 사용자인 것처럼 통신하는 공격이다. 공격 과정에서 TCP 순서 번호가 어긋나 비동기화 상태가 되고, 서로 맞지 않는 ACK 패킷이 계속 오가는 ACK Storm이 생기며, 패킷 유실과 재전송이 늘어난다. 그래서 이런 징후와 예상치 못한 접속 리셋을 탐지해 공격을 알아낸다.","choices":[{"verdict":"정답","why":"FTP SYN 세그먼트 탐지는 세션 하이재킹 탐지 방법에 해당하지 않는다."},{"verdict":"오답","why":"세션 하이재킹 중에는 순서 번호가 어긋난 비동기화 상태가 생기므로, 이를 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"비동기화된 양쪽이 서로 ACK를 계속 주고받는 ACK Storm을 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"공격 과정에서 패킷 유실과 재전송이 늘어나므로, 이를 탐지하는 것은 세션 하이재킹 탐지 방법이다."}],"keywords":[{"term":"세션 하이재킹(Session Hijacking)","desc":"인증된 세션을 가로채 정상 사용자로 위장"},{"term":"ACK Storm","desc":"비동기화된 양쪽이 ACK를 끝없이 주고받는 현상"},{"term":"탐지 방법","desc":"비동기화 상태, ACK Storm, 패킷 유실·재전송 증가, 예상치 못한 접속 리셋 탐지"}],"memo":"세션 하이재킹 탐지는 '비동기화·ACK Storm·재전송 증가·리셋'. FTP라는 특정 서비스 이름이 끼어 있으면 엉뚱한 보기다."}},{"id":"written-2021-1-96","no":96,"unit":"정보시스템 구축 관리","q":"소프트웨어공학에 대한 설명으로 거리가 먼 것은?","choices":["소프트웨어공학이란 소프트웨어의 개발, 운용, 유지보수 및 파기에 대한 체계적인 접근 방법이다.","소프트웨어공학은 소프트웨어 제품의 품질을 향상시키고 소프트웨어 생산성과 작업 만족도를 증대시키는 것이 목적이다.","소프트웨어공학의 궁극적 목표는 최대의 비용으로 계획된 일정보다 가능한 빠른 시일 내에 소프트웨어를 개발하는 것이다.","소프트웨어공학은 신뢰성 있는 소프트웨어를 경제적인 비용으로 획득하기 위해 공학적 원리를 정립하고 이를 이용하는 것이다."],"ans":3,"rate":90,"wiki":[{"title":"소프트웨어 위기","url":"https://itwiki.kr/w/소프트웨어 위기"}],"exp":{"concept":"소프트웨어 공학은 소프트웨어의 개발, 운용, 유지보수, 폐기까지 전 과정에 공학적 원리를 적용하는 체계적인 접근 방법이다. 목표는 품질 좋은 소프트웨어를 최소의 비용으로 계획된 일정 안에 개발하는 것이다. 비용을 최대로 쓴다는 것은 공학의 목표가 될 수 없다.","choices":[{"verdict":"오답","why":"소프트웨어 공학은 개발, 운용, 유지보수, 파기에 대한 체계적인 접근 방법이다. 맞는 설명이다."},{"verdict":"오답","why":"소프트웨어 품질과 생산성, 작업 만족도를 높이는 것이 소프트웨어 공학의 목적이다. 맞는 설명이다."},{"verdict":"정답","why":"소프트웨어 공학의 목표는 최소의 비용으로 계획된 일정 안에 고품질 소프트웨어를 개발하는 것이다. '최대의 비용'은 틀렸다."},{"verdict":"오답","why":"신뢰성 있는 소프트웨어를 경제적인 비용으로 얻기 위해 공학적 원리를 정립하고 적용하는 것이다. 맞는 설명이다."}],"keywords":[{"term":"소프트웨어 공학","desc":"SW 개발·운용·유지보수·폐기에 공학적 원리를 적용하는 학문"},{"term":"소프트웨어 위기","desc":"SW 수요 증가를 개발 능력이 따라가지 못해 생긴 문제, 소프트웨어 공학 등장 배경"},{"term":"소프트웨어 공학의 목표","desc":"최소 비용, 계획된 일정, 고품질"}],"memo":"공학은 언제나 '최소 비용, 최대 효과'. '최대의 비용'이 보이면 바로 틀린 문장."}},{"id":"written-2021-1-97","no":97,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론 중 CBD(Component Based Development)에 대한 설명으로 틀린 것은?","choices":["생산성과 품질을 높이고, 유지보수 비용을 최소화할 수 있다.","컴포넌트 제작 기법을 통해 재사용성을 향상시킨다.","모듈의 분할과 정복에 의한 하향식 설계방식이다.","독립적인 컴포넌트 단위의 관리로 복잡성을 최소화할 수 있다."],"ans":3,"rate":84,"exp":{"concept":"CBD(Component Based Development)는 재사용 가능한 컴포넌트(부품)를 만들고, 이를 조립해 새 응용 프로그램을 만드는 개발 방법론이다. 레고 블록을 조립해 모형을 만드는 것과 같다. 재사용성이 높아져 생산성과 품질이 오르고 유지보수 비용과 복잡성이 줄어든다.","choices":[{"verdict":"오답","why":"검증된 컴포넌트를 재사용하므로 생산성과 품질이 높아지고 유지보수 비용이 줄어든다. 맞는 설명이다."},{"verdict":"오답","why":"컴포넌트 제작 기법으로 재사용성을 높이는 것이 CBD의 핵심이다. 맞는 설명이다."},{"verdict":"정답","why":"모듈의 분할과 정복에 의한 하향식 설계는 구조적 방법론의 특징이다. CBD는 컴포넌트를 조립하는 방식이다."},{"verdict":"오답","why":"독립적인 컴포넌트 단위로 관리하므로 복잡성을 최소화할 수 있다. 맞는 설명이다."}],"keywords":[{"term":"CBD(Component Based Development)","desc":"컴포넌트를 조립해 개발, 재사용성 향상"},{"term":"컴포넌트(Component)","desc":"독립적으로 실행되고 교체 가능한 SW 부품"},{"term":"구조적 방법론","desc":"분할 정복, 하향식 설계"}],"memo":"CBD는 '조립'. '분할과 정복', '하향식'은 구조적 방법론의 단어다."}},{"id":"written-2021-1-98","no":98,"unit":"정보시스템 구축 관리","q":"정보 보안의 3요소에 해당하지 않는 것은?","choices":["기밀성","무결성","가용성","휘발성"],"ans":4,"rate":90,"wiki":[{"title":"보안","url":"https://itwiki.kr/w/보안"},{"title":"CIA","url":"https://itwiki.kr/w/CIA"}],"exp":{"concept":"정보 보안의 3요소는 기밀성, 무결성, 가용성이다. 기밀성은 허락된 사람만 정보를 볼 수 있게, 무결성은 허락된 사람만 정보를 바꿀 수 있게, 가용성은 허락된 사람이 필요할 때 언제든 정보를 쓸 수 있게 하는 것이다. 영어 머리글자를 따서 CIA라고 부른다.","choices":[{"verdict":"오답","why":"기밀성(Confidentiality)은 인가된 사용자만 정보에 접근할 수 있게 하는 정보 보안의 3요소다."},{"verdict":"오답","why":"무결성(Integrity)은 인가된 사용자만 정보를 수정할 수 있게 하는 정보 보안의 3요소다."},{"verdict":"오답","why":"가용성(Availability)은 인가된 사용자가 필요할 때 언제든 정보를 사용할 수 있게 하는 정보 보안의 3요소다."},{"verdict":"정답","why":"휘발성은 전원이 꺼지면 데이터가 사라지는 기억장치의 성질로, 정보 보안의 요소가 아니다."}],"keywords":[{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 접근"},{"term":"무결성(Integrity)","desc":"인가된 사용자만 수정"},{"term":"가용성(Availability)","desc":"인가된 사용자가 언제든 사용 가능"},{"term":"인증·부인 방지","desc":"3요소에 더해 자주 함께 다루는 보안 요소"}],"memo":"보안 3요소는 CIA (Confidentiality, Integrity, Availability)."}},{"id":"written-2021-1-99","no":99,"unit":"정보시스템 구축 관리","q":"소셜 네트워크에서 악의적인 사용자가 지인 또는 특정 유명인으로 가장하여 활동하는 공격 기법은?(문제 오류로 가답안 발표시 1번으로 발표되었지만 확정답안 발표시 1, 2번이 정답처리 되었습니다. 여기서는 가답안인 1번을 누르시면 정답 처리 됩니다.)","choices":["Evil Twin Attack","Phishing","Logic Bomb","Cyberbullying"],"ans":1,"rate":76,"exp":{"concept":"SNS에서 지인이나 유명인인 척하며 활동하는 공격은 상대가 믿는 대상을 사칭해 속이는 사회공학적 공격이다. 이 시험에서는 이 설명을 이블 트윈 어택(Evil Twin Attack)의 정의로 출제했다. 이블 트윈은 원래 정상 무선 AP와 똑같이 보이는 가짜 AP를 세워 접속을 가로채는 공격을 가리키는 말이기도 하다.","choices":[{"verdict":"정답","why":"소셜 네트워크에서 지인이나 유명인으로 가장해 활동하는 공격을 이 시험에서는 이블 트윈 어택(Evil Twin Attack)으로 출제했다."},{"verdict":"오답","why":"피싱(Phishing)은 금융기관이나 지인 등 믿을 만한 대상을 사칭한 메일·메시지로 개인정보를 빼내는 공격이다. 사칭이라는 점이 지문과 겹쳐 보기 내용상 맞는 설명으로 볼 수도 있으며, 문제 안내문대로 확정 답안에서도 정답으로 인정되었다."},{"verdict":"오답","why":"논리 폭탄(Logic Bomb)은 특정 날짜나 조건이 충족되면 실행되도록 프로그램 안에 숨겨 둔 악성 코드다."},{"verdict":"오답","why":"사이버 불링(Cyberbullying)은 인터넷이나 SNS에서 특정인을 반복적으로 괴롭히는 행위다."}],"keywords":[{"term":"이블 트윈 어택(Evil Twin Attack)","desc":"SNS에서 지인·유명인 사칭 / 정상 AP로 위장한 가짜 무선 AP"},{"term":"피싱(Phishing)","desc":"신뢰 기관·지인을 사칭해 개인정보를 빼내는 공격"},{"term":"논리 폭탄(Logic Bomb)","desc":"특정 조건에서 실행되는 숨겨진 악성 코드"},{"term":"사회 공학(Social Engineering)","desc":"사람의 신뢰를 이용해 정보를 빼내는 기법"}],"memo":"Evil Twin = 사악한 쌍둥이. 진짜와 똑같이 생긴 가짜(사칭 계정, 가짜 AP)로 속인다.","doubt":"문제 안내문에 따르면 확정 답안에서 1번(Evil Twin Attack)과 2번(Phishing)이 모두 정답 처리되었다. 피싱도 지인·기관을 사칭해 속이는 공격이므로 보기 내용상 2번도 맞는 설명으로 볼 수 있다. 이 문제에서는 가답안인 1번을 정답으로 처리한다."}},{"id":"written-2021-1-100","no":100,"unit":"정보시스템 구축 관리","q":"공개키 암호에 대한 설명으로 틀린 것은?","choices":["10명이 공개키 암호를 사용할 경우 5개의 키가 필요하다.","복호화키는 비공개 되어 있다.","송신자는 수신자의 공개키로 문서를 암호화한다.","공개키 암호로 널리 알려진 알고리즘은 RSA가 있다."],"ans":1,"rate":69,"wiki":[{"title":"공개키 암호","url":"https://itwiki.kr/w/공개키 암호"}],"exp":{"concept":"공개키(비대칭키) 암호는 암호화 키(공개키)는 모두에게 공개하고 복호화 키(개인키)는 본인만 가진다. 송신자는 수신자의 공개키로 암호화하고, 수신자는 자신의 개인키로 복호화한다. 사람마다 공개키와 개인키 한 쌍이 필요하므로 n명이면 2n개의 키가 필요하다. 10명이면 20개다.","choices":[{"verdict":"정답","why":"공개키 암호는 한 사람당 공개키와 개인키 2개가 필요하므로 10명이면 2 × 10 = 20개의 키가 필요하다. 5개는 틀렸다."},{"verdict":"오답","why":"복호화에 쓰는 개인키는 본인만 갖고 공개하지 않는다. 맞는 설명이다."},{"verdict":"오답","why":"송신자는 수신자의 공개키로 암호화하고, 수신자만 자신의 개인키로 풀 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"RSA는 큰 수의 소인수분해가 어렵다는 점을 이용한 대표적인 공개키 암호 알고리즘이다. 맞는 설명이다."}],"keywords":[{"term":"공개키 암호 키 개수","desc":"n명이면 2n개"},{"term":"대칭키 암호 키 개수","desc":"n명이면 n(n-1)/2개 (10명이면 45개)"},{"term":"공개키(Public Key)","desc":"암호화에 사용, 모두에게 공개"},{"term":"개인키(Private Key)","desc":"복호화에 사용, 본인만 보관"},{"term":"RSA","desc":"소인수분해의 어려움을 이용한 공개키 암호"}],"memo":"공개키는 '한 사람당 한 쌍'이라 2n, 대칭키는 '두 사람마다 하나'라 n(n-1)/2."}}]};